import React, { useState, useEffect, useMemo, useCallback, Suspense, lazy } from 'react';
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { Layout } from './components/Layout';
import { Task, ViewMode, TaskStatus, Partner, TaskPriority, TaskType, ThemeOption, ViewSourceMode } from './types';
import { getUrgencyScore } from './utils/taskScoring';
import { logger } from './utils/logger';
import { supabase, getProviderToken, signInWithGoogleCalendar } from './services/supabaseClient';
import { CalendarEvent, listGoogleEvents, GoogleCalendarError } from './services/googleCalendarService';
import TaskCard from './components/TaskCard';
import TaskEditor from './components/TaskEditor';
import FocusSession from './components/FocusSession';
import MorningBriefingModal from './components/MorningBriefingModal';
import Button from './components/Button';
import Auth from './components/Auth';
import Select from './components/Select';
import { Search, Filter, Bell, CalendarDays, Clock, CheckSquare, Activity, ArrowRight, Repeat, MessageSquare, Loader2, X } from 'lucide-react';
import { enhanceTaskWithAI } from './services/geminiService';
import { ParsedTaskData } from './services/geminiService';
import { getGreeting, t } from './themeText';
import CommandBar from './components/CommandBar';

// Lazy load heavy components for better initial bundle size
const AIChat = lazy(() => import('./components/AIChat'));
const CalendarView = lazy(() => import('./components/CalendarView'));
const BudgetPlanner = lazy(() => import('./components/BudgetPlanner'));
const NotesManager = lazy(() => import('./components/NotesManager'));

// Import new hooks and contexts
import { useAuth } from './context/AuthContext';
import { useTheme } from './context/ThemeContext';
import { useTasks } from './hooks/useTasks';
import { useBudget } from './hooks/useBudget';
import { useUserSettings } from './hooks/useUserSettings';
import { useRoutines } from './hooks/useRoutines';
import * as PartnerService from './services/partnerService';
import * as NotificationService from './services/notificationService';
import { NotificationSettings, Routine } from './types';
import RoutineEditor from './components/RoutineEditor';
import RoutineList from './components/RoutineList';
// SettingsPage handles DeleteAccountModal internally
import SettingsPage from './pages/SettingsPage';

// Custom Hooks
import { useSMSListener } from './hooks/useSMSListener';
import { useNotificationScheduler } from './hooks/useNotificationScheduler';
import { useRecurringProcessor } from './hooks/useRecurringProcessor';
import { useMorningBriefing } from './hooks/useMorningBriefing';
import { useNetworkStatus } from './hooks/useNetworkStatus';

// Import page components
import ActivitiesPage from './pages/ActivitiesPage';
import DayPlannerPage from './pages/DayPlannerPage';

// Map URL paths to ViewMode for Layout compatibility
const pathToViewMode: Record<string, ViewMode> = {
    '/': 'activities',
    '/activities': 'activities',
    '/all-activities': 'all-activities',
    '/tasks': 'tasks',
    '/reminders': 'reminders',
    '/events': 'events',
    '/appointments': 'appointments',
    '/calendar': 'calendar',
    '/budget': 'budget',
    '/ai-chat': 'ai-chat',
    '/settings': 'settings',
    '/routines': 'routines',
    '/notes': 'notes',
    '/day-planner': 'day-planner',
};

const viewModeToPath: Record<ViewMode, string> = {
    'dashboard': '/',
    'activities': '/activities',
    'all-activities': '/all-activities',
    'tasks': '/tasks',
    'reminders': '/reminders',
    'events': '/events',
    'appointments': '/appointments',
    'calendar': '/calendar',
    'budget': '/budget',
    'ai-chat': '/ai-chat',
    'settings': '/settings',
    'routines': '/routines',
    'notes': '/notes',
    'day-planner': '/day-planner',
};

const App: React.FC = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const currentView: ViewMode = pathToViewMode[location.pathname] || 'dashboard';

    // Use new contexts and hooks
    const { session, isAuthLoading, signOut } = useAuth();
    const { theme, setTheme } = useTheme();
    const { 
        tasks, 
        isLoading: isTasksLoading, 
        createTask, 
        updateTask, 
        deleteTask, 
        toggleStatus 
    } = useTasks();
    const { 
        budget, 
        isLoading: isBudgetLoading, 
        refetch: refetchBudget, 
        processRecurring 
    } = useBudget();
    
    // Network Status
    const isOnline = useNetworkStatus();

    // Local UI state
    const [isEditorOpen, setIsEditorOpen] = useState(false);
    const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<string>('ALL');

    // Focus Mode State
    const [isFocusModeOpen, setIsFocusModeOpen] = useState(false);
    const [focusedTask, setFocusedTask] = useState<Task | undefined>(undefined);

    // Username state
    const [username, setUsername] = useState('User');

    // State for creating task from calendar or create button
    const [calendarSelectedDate, setCalendarSelectedDate] = useState<Date | undefined>(undefined);
    const [editorInitialType, setEditorInitialType] = useState<TaskType>('TASK');

    // Partner State
    const [partner, setPartner] = useState<Partner | null>(null);

    // Tag Filtering State for Calendar
    const [selectedCalendarTags, setSelectedCalendarTags] = useState<string[]>([]);

    // Command Bar State (Cmd+K)
    const [isCommandBarOpen, setIsCommandBarOpen] = useState(false);

    // AI Chat Modal State
    const [isAIChatOpen, setIsAIChatOpen] = useState(false);

    // Calendar Navigate Date State
    const [calendarNavigateDate, setCalendarNavigateDate] = useState<Date | undefined>(undefined);

    // Calendar Visible Tags State - tags from tasks in the current calendar period
    const [calendarVisibleTags, setCalendarVisibleTags] = useState<string[]>([]);

    const [viewSourceMode, setViewSourceMode] = useState<ViewSourceMode>('combined');

    const handleViewSourceModeChange = useCallback((mode: ViewSourceMode) => {
        setViewSourceMode(mode);
        localStorage.setItem('viewSourceMode', mode);
    }, []);
    const [hasConnectedPartners, setHasConnectedPartners] = useState(false);

    // Notification Settings State
    const [notificationSettings, setNotificationSettings] = useState<NotificationSettings>(
        NotificationService.getSettings()
    );

    // Routine State
    const { 
        routines, 
        saveRoutine: saveRoutineHook, 
        deleteRoutine: deleteRoutineHook, 
        toggleRoutine: toggleRoutineHook 
    } = useRoutines();
    const [isRoutineEditorOpen, setIsRoutineEditorOpen] = useState(false);
    const [editingRoutine, setEditingRoutine] = useState<Routine | undefined>(undefined);

    // Google Calendar Integration State
    const [googleCalendarEnabled, setGoogleCalendarEnabled] = useState<boolean>(() => {
        return localStorage.getItem('googleCalendarEnabled') === 'true';
    });
    const [hasGoogleToken, setHasGoogleToken] = useState<boolean>(false);
    const [externalEvents, setExternalEvents] = useState<CalendarEvent[]>([]);
    const [isLoadingGoogleEvents, setIsLoadingGoogleEvents] = useState(false);

    // --- CUSTOM HOOKS INTEGRATION ---

    // SMS Listener
    const { lastSmsTransaction, setLastSmsTransaction } = useSMSListener();

    // Notification Scheduler
    const { 
        notificationPermission,
        handleNotificationToggle, 
        handleNotificationPreferenceChange 
    } = useNotificationScheduler(tasks, notificationSettings, setNotificationSettings);

    // Recurring Processor
    const { 
        dueRecurringItems, 
        showRecurringModal, 
        handleProcessRecurring, 
        handleDismissRecurring 
    } = useRecurringProcessor();

    // Morning Briefing
    const {
        showBriefing,
        overdueTasks,
        dismissBriefing
    } = useMorningBriefing({ tasks });

    // --- END HOOKS ---

    // Load username when session changes
    useEffect(() => {
        const loadUsername = async () => {
            if (session?.user) {
                const { data } = await supabase
                    .from('user_settings')
                    .select('display_name')
                    .eq('user_id', session.user.id)
                    .single();
                if (data?.display_name) {
                    setUsername(data.display_name);
                }
            }
        };
        loadUsername();
    }, [session]);

    // Check for connected partners
    useEffect(() => {
        const checkPartners = async () => {
            if (session?.user) {
                const partnerships = await PartnerService.getPartnerships();
                const acceptedPartners = partnerships.filter(p => p.status === 'accepted');
                setHasConnectedPartners(acceptedPartners.length > 0);
                
                if (acceptedPartners.length > 0) {
                    const firstPartner = acceptedPartners[0];
                    setPartner({
                        id: firstPartner.partnerId,
                        name: firstPartner.partnerName || firstPartner.partnerEmail,
                        email: firstPartner.partnerEmail,
                        isConnected: true
                    });
                } else {
                    setPartner(null);
                }
            }
        };
        checkPartners();
    }, [session]);

    // Initialize calendar tags
    useEffect(() => {
        if (tasks.length > 0) {
            const allUniqueTags = new Set<string>();
            tasks.forEach(t => t.tags.forEach(tag => allUniqueTags.add(tag)));
            if (tasks.some(t => t.tags.length === 0)) allUniqueTags.add('Untagged');
            const sortedTags = Array.from(allUniqueTags).sort((a, b) => {
                if (a === 'Untagged') return -1;
                if (b === 'Untagged') return 1;
                return a.localeCompare(b);
            });
            setSelectedCalendarTags(sortedTags);
        }
    }, [tasks]);

    // Global Cmd+K keyboard listener
    useEffect(() => {
        const handleGlobalKeyDown = (e: KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
                e.preventDefault();
                setIsCommandBarOpen(true);
            }
        };
        window.addEventListener('keydown', handleGlobalKeyDown);
        return () => window.removeEventListener('keydown', handleGlobalKeyDown);
    }, []);

    // Register Service Worker and Initialize Push Notifications
    useEffect(() => {
        const registerServiceWorker = async () => {
            if ('serviceWorker' in navigator) {
                try {
                    // Register the custom service worker
                    const registration = await navigator.serviceWorker.register(
                        '/sw.js',
                        { scope: '/' }
                    );
                    
                    logger.debug('[App] Service Worker registered', { registration });

                    // Wait for service worker to be ready
                    await navigator.serviceWorker.ready;

                    // Send VAPID public key to service worker for push subscription
                    const vapidKey = import.meta.env.VITE_VAPID_PUBLIC_KEY;
                    if (vapidKey && registration.active) {
                        registration.active.postMessage({
                            type: 'SET_VAPID_KEY',
                            key: vapidKey
                        });
                    }

                    // Initialize push notifications if enabled and user is authenticated
                    if (session?.user && notificationSettings.enabled) {
                        await NotificationService.initializePushNotifications();
                    }
                } catch (error) {
                    console.error('[App] Service Worker registration failed:', error);
                }
            }
        };

        registerServiceWorker();
    }, [session, notificationSettings.enabled]);

    // Google Calendar: Check token availability
    useEffect(() => {
        const checkGoogleToken = async () => {
            if (session?.user && googleCalendarEnabled) {
                const token = await getProviderToken();
                setHasGoogleToken(!!token);
            } else {
                setHasGoogleToken(false);
            }
        };
        checkGoogleToken();
    }, [session, googleCalendarEnabled]);

    // Google Calendar: Fetch events when enabled and token available
    useEffect(() => {
        const fetchGoogleEvents = async () => {
            if (!googleCalendarEnabled || !hasGoogleToken) {
                setExternalEvents([]);
                return;
            }

            setIsLoadingGoogleEvents(true);
            try {
                const token = await getProviderToken();
                if (!token) {
                    setHasGoogleToken(false);
                    return;
                }

                // Fetch events for next 3 months
                const now = new Date();
                const threeMonthsLater = new Date();
                threeMonthsLater.setMonth(threeMonthsLater.getMonth() + 3);

                const events = await listGoogleEvents(
                    token,
                    now.toISOString(),
                    threeMonthsLater.toISOString()
                );
                setExternalEvents(events);
                logger.debug('[App] Fetched Google Calendar events', { count: events.length });
            } catch (error) {
                if (error instanceof GoogleCalendarError) {
                    console.error('[App] Google Calendar error:', error.code, error.message);
                    if (error.code === 'UNAUTHORIZED') {
                        setHasGoogleToken(false);
                    }
                } else {
                    console.error('[App] Failed to fetch Google Calendar events:', error);
                }
                setExternalEvents([]);
            } finally {
                setIsLoadingGoogleEvents(false);
            }
        };

        fetchGoogleEvents();
    }, [googleCalendarEnabled, hasGoogleToken]);

    // Google Calendar: Toggle handler
    const handleGoogleCalendarToggle = useCallback(async (enabled: boolean) => {
        setGoogleCalendarEnabled(enabled);
        localStorage.setItem('googleCalendarEnabled', String(enabled));

        if (enabled) {
            // Check if we have a token
            const token = await getProviderToken();
            if (!token) {
                // Trigger OAuth flow
                logger.debug('[App] No Google token, triggering OAuth flow');
                await signInWithGoogleCalendar();
            } else {
                setHasGoogleToken(true);
            }
        } else {
            setExternalEvents([]);
        }
    }, []);

    // Filter tasks based on View Source Mode (Personal, Partners, Combined)
    const visibleTasks = useMemo(() => {
        if (!session?.user?.id) return [];
        switch (viewSourceMode) {
            case 'personal':
                return tasks.filter(t => t.user_id === session.user.id && !t.isShared);
            case 'partners':
                return tasks.filter(t =>
                    t.user_id !== session.user.id || // Tasks created by partners
                    (t.user_id === session.user.id && t.isShared) // Tasks created by user and shared
                );
            case 'combined':
                return tasks;
            default:
                return tasks.filter(t => t.user_id === session.user.id);
        }
    }, [tasks, viewSourceMode, session?.user?.id]);

    // Computed Values needed for AI context
    const allTags = useMemo(() => {
        const tags = new Set<string>();
        visibleTasks.forEach(t => t.tags.forEach(tag => tags.add(tag)));
        if (visibleTasks.some(t => t.tags.length === 0)) tags.add('Untagged');
        return Array.from(tags).sort((a, b) => {
            if (a === 'Untagged') return -1;
            if (b === 'Untagged') return 1;
            return a.localeCompare(b);
        });
    }, [visibleTasks]);

    // Routine Handlers
    const handleSaveRoutine = useCallback((routine: Routine) => {
        saveRoutineHook(routine);
        setIsRoutineEditorOpen(false);
        setEditingRoutine(undefined);
    }, [saveRoutineHook]);

    const handleDeleteRoutine = useCallback((id: string) => {
        deleteRoutineHook(id);
        setIsRoutineEditorOpen(false);
        setEditingRoutine(undefined);
    }, [deleteRoutineHook]);

    const handleToggleRoutine = useCallback((id: string) => {
        toggleRoutineHook(id);
    }, [toggleRoutineHook]);

    const handleCreateRoutine = useCallback(() => {
        setEditingRoutine(undefined);
        setIsRoutineEditorOpen(true);
    }, []);

    const handleEditRoutine = useCallback((routine: Routine) => {
        setEditingRoutine(routine);
        setIsRoutineEditorOpen(true);
    }, []);

    const handleUsernameChange = useCallback((name: string) => {
        setUsername(name);
        if (session?.user) {
            supabase.from('user_settings').upsert({ user_id: session.user.id, display_name: name }).then();
        }
    }, [session?.user]);

    const handleCreateTask = useCallback((initialDate?: Date, type: TaskType = 'TASK') => {
        setEditingTask(undefined);
        setCalendarSelectedDate(initialDate);
        setEditorInitialType(type);
        setIsEditorOpen(true);
    }, []);

    const handleEditTask = useCallback((task: Task) => {
        setEditingTask(task);
        setCalendarSelectedDate(undefined);
        setEditorInitialType(task.type);
        setIsEditorOpen(true);
    }, []);

    const handleEditDraft = useCallback((taskData: Partial<Task>) => {
        setEditingTask(taskData as Task);
        setCalendarSelectedDate(undefined);
        setEditorInitialType(taskData.type || 'TASK');
        setIsEditorOpen(true);
    }, []);

    // Handler for Command Bar parsed task data
    const handleCommandBarTask = useCallback((parsedData: ParsedTaskData) => {
        const taskDraft: Partial<Task> = {
            title: parsedData.title,
            type: parsedData.type,
            dueDate: parsedData.dueDate,
            reminderTime: parsedData.reminderTime,
            description: parsedData.description,
            priority: parsedData.priority === 'HIGH' ? TaskPriority.HIGH :
                      parsedData.priority === 'LOW' ? TaskPriority.LOW : TaskPriority.MEDIUM,
            duration: parsedData.duration,
            location: parsedData.location,
            status: TaskStatus.TODO,
            tags: [],
            subtasks: [],
            dependencyIds: [],
            isShared: false
        };
        handleEditDraft(taskDraft);
    }, [handleEditDraft]);

    // ΓÜí Performance Optimization: Memoized handler to prevent re-renders of TaskEditor
    const handleSaveTask = useCallback(async (taskData: Partial<Task>) => {
        logger.debug('[App] handleSaveTask called', { taskData });
        let savedTask: Task | null = null;

        try {
            if (taskData.id) {
                savedTask = await updateTask(taskData as Task);
            } else {
                savedTask = await createTask(taskData as Omit<Task, 'id' | 'createdAt'>);
            }
            logger.debug('[App] Task saved successfully', { savedTask });
        } catch (error) {
            console.error('[App] Error saving task:', error);
        }

        if (savedTask && savedTask.tags) {
            setSelectedCalendarTags(prev => {
                const newTags = savedTask!.tags.filter(t => !prev.includes(t));
                return [...prev, ...newTags];
            });
        }
    }, [updateTask, createTask]);

    // ΓÜí Performance Optimization: Memoized handler to prevent re-renders of TaskEditor
    const handleDeleteTask = useCallback(async (id: string) => {
        const success = await deleteTask(id);
        if (success) {
            setIsEditorOpen(false);
        }
    }, [deleteTask]);

    // ΓÜí Performance Optimization: Memoized handler to prevent re-renders of TaskCard and CalendarView
    const handleToggleStatus = useCallback(async (task: Task) => {
        await toggleStatus(task);
    }, [toggleStatus]);

    // ΓÜí Performance Optimization: Memoized handler to prevent re-renders of TaskCard
    const handleAIAnalysis = useCallback(async (task: Task) => {
        const enhanced = await enhanceTaskWithAI(task.title, allTags);
        if (enhanced && enhanced.subtasks) {
            const subtasks = enhanced.subtasks.map(s => ({
                id: crypto.randomUUID(),
                title: s.title,
                isCompleted: false
            }));
            await updateTask({ ...task, subtasks: [...task.subtasks, ...subtasks] });
        }
    }, [allTags, updateTask]);

    // Focus Mode Handlers
    const handleStartFocus = useCallback((task: Task) => {
        setFocusedTask(task);
        setIsFocusModeOpen(true);
    }, []);

    const handleCompleteFocus = useCallback(async (task: Task) => {
        await toggleStatus(task);
        setIsFocusModeOpen(false);
        setFocusedTask(undefined);
    }, [toggleStatus]);

    const handleAutoCreatedTask = useCallback(async (taskData: Partial<Task>) => {
        const newTask = await createTask(taskData as Omit<Task, 'id' | 'createdAt'>);
        if (newTask && newTask.tags && Array.isArray(newTask.tags)) {
            setSelectedCalendarTags(prev => {
                const newTags = newTask.tags.filter(t => !prev.includes(t));
                return [...prev, ...newTags];
            });
        }
    }, [createTask]);

    const handleToggleCalendarTag = useCallback((tag: string) => {
        setSelectedCalendarTags(prev =>
            prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
        );
    }, []);

    const handleRenameTag = useCallback(async (oldTag: string, newTag: string) => {
        if (!newTag.trim() || oldTag === newTag) return;
        const finalTag = newTag.trim();

        logger.debug(`Renaming tag "${oldTag}" to "${finalTag}"`);
        const tasksToUpdate = tasks.filter(t => t.tags.includes(oldTag));
        logger.debug(`Found ${tasksToUpdate.length} tasks with tag "${oldTag}"`);

        // Server Update using the hook's updateTask
        for (const t of tasksToUpdate) {
            const newTags = t.tags.map(tag => tag === oldTag ? finalTag : tag);
            const uniqueTags = [...new Set(newTags)];
            try {
                await updateTask({ ...t, tags: uniqueTags });
                logger.debug(`Γ£ô Updated task "${t.title}" tags`, { tags: uniqueTags });
            } catch (error) {
                console.error(`Γ£ù Failed to update task "${t.title}":`, error);
            }
        }

        setSelectedCalendarTags(prev => {
            if (prev.includes(oldTag)) {
                const others = prev.filter(t => t !== oldTag);
                return [...others, finalTag];
            }
            return prev;
        });
        
        logger.debug(`Tag rename complete: "${oldTag}" -> "${finalTag}"`);
    }, [tasks, updateTask]);

    const handleSignOut = useCallback(async () => {
        await signOut();
    }, [signOut]);

    const filteredTasks = useMemo(() => {
        return visibleTasks
            .filter(t => {
                if (currentView === 'tasks' && t.type !== 'TASK') return false;
                if (currentView === 'events' && t.type !== 'EVENT') return false;
                if (currentView === 'appointments' && t.type !== 'APPOINTMENT') return false;
                if (currentView === 'reminders' && t.type !== 'REMINDER') return false;

                const matchesSearch = t.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    t.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()));
                const matchesStatus = filterStatus === 'ALL' || t.status === filterStatus;
                return matchesSearch && matchesStatus;
            })
            .sort((a, b) => getUrgencyScore(b) - getUrgencyScore(a)); // Higher urgency first
    }, [visibleTasks, searchQuery, filterStatus, currentView]);

    const calendarFilteredTasks = useMemo(() => {
        return visibleTasks.filter(t => {
            if (t.tags.length === 0) {
                return selectedCalendarTags.includes('Untagged');
            }
            return t.tags.some(tag => selectedCalendarTags.includes(tag));
        });
    }, [visibleTasks, selectedCalendarTags]);

    const sortedTodoTasks = useMemo(() => {
        return tasks
            .filter(t => t.status !== TaskStatus.DONE)
            .sort((a, b) => getUrgencyScore(b) - getUrgencyScore(a));
    }, [tasks]);

    const getTopItem = (type: TaskType) => {
        return tasks
            .filter(t => t.type === type && t.status !== TaskStatus.DONE)
            .sort((a, b) => {
                const pWeight = { [TaskPriority.HIGH]: 3, [TaskPriority.MEDIUM]: 2, [TaskPriority.LOW]: 1 };
                if (pWeight[a.priority] !== pWeight[b.priority]) return pWeight[b.priority] - pWeight[a.priority];

                const dateA = a.dueDate || a.reminderTime || (Number.MAX_SAFE_INTEGER + '');
                const dateB = b.dueDate || b.reminderTime || (Number.MAX_SAFE_INTEGER + '');
                return new Date(dateA).getTime() - new Date(dateB).getTime();
            })[0];
    }

    // Calculate tasks due today
    const todaysPendingTasks = useMemo(() => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);
        
        return visibleTasks.filter(t => {
            if (t.status === TaskStatus.DONE) return false;
            
            const dateStr = t.dueDate || t.reminderTime;
            if (!dateStr) return false;
            
            const taskDate = new Date(dateStr);
            return taskDate >= today && taskDate < tomorrow;
        });
    }, [visibleTasks]);

    // Budget Calculations
    const totalExpenses = budget.transactions.filter(t => t.type === 'expense').reduce((acc, curr) => acc + curr.amount, 0);
    const budgetRemaining = budget.limit - totalExpenses;

    const userStats = {
        userName: username,
        pendingTasks: todaysPendingTasks.length,
        totalTasks: tasks.length,
        budgetRemaining: budgetRemaining,
        partnerName: partner?.name
    };

    const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });

    const getHeaderInfo = () => {
        switch (currentView) {
            case 'reminders': return { title: t(theme, 'reminders'), subtitle: 'Don\'t forget these important items', icon: Bell };
            case 'events': return { title: t(theme, 'events'), subtitle: 'Upcoming social and work gatherings', icon: CalendarDays };
            case 'appointments': return { title: t(theme, 'appointments'), subtitle: 'Scheduled meetings and visits', icon: Clock };
            case 'tasks': return { title: t(theme, 'tasks'), subtitle: 'Manage and track your daily activities', icon: CheckSquare };
            case 'all-activities': return { title: 'All Activities', subtitle: 'Tasks, Reminders, Events & Appointments', icon: Activity };
            default: return { title: 'Items', subtitle: 'List View', icon: CheckSquare };
        }
    };

    const headerInfo = getHeaderInfo();
    const HeaderIcon = headerInfo.icon;

    // -- RENDER STATES --

    if (isAuthLoading) {
        return (
            <div className="h-screen w-screen flex items-center justify-center bg-slate-900 text-brand-500">
                <Loader2 size={48} className="animate-spin" />
            </div>
        );
    }

    if (!session) {
        return <Auth />;
    }

    if (isTasksLoading && tasks.length === 0) { // Only show full loader on initial fetch
        return (
            <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-brand-500 gap-4">
                <Loader2 size={48} className="animate-spin" />
                <p className="text-slate-400 text-sm animate-pulse">Syncing your ChronoDeX...</p>
            </div>
        );
    }

    return (
        <Layout
            currentView={currentView}
            onNavigate={(view) => navigate(viewModeToPath[view])}
            onAddTask={(type) => handleCreateTask(undefined, type)}
            userStats={userStats}
            currentTheme={theme}
            onThemeChange={(t) => setTheme(t, true)}
            calendarTags={currentView === 'calendar' && calendarVisibleTags.length > 0 ? calendarVisibleTags : allTags}
            selectedTags={selectedCalendarTags}
            onToggleTag={handleToggleCalendarTag}
            onRenameTag={handleRenameTag}
            viewSourceMode={viewSourceMode}
            onViewSourceModeChange={handleViewSourceModeChange}
            hasConnectedPartners={hasConnectedPartners}
            onCreateRoutine={handleCreateRoutine}
            onOpenAI={() => setIsAIChatOpen(true)}
            onCalendarDateSelect={(date) => setCalendarNavigateDate(date)}
        >
            {/* Offline Indicator */}
            {!isOnline && (
                 <div className="fixed top-0 left-0 right-0 z-[100] bg-red-500 text-white text-center py-1 text-xs font-bold shadow-md animate-slide-down">
                     You are offline. Changes will rely on cache and retry when online.
                 </div>
            )}

            {/* SMS Notification Toast */}
            {lastSmsTransaction && (
                <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[60] bg-white dark:bg-slate-800 shadow-2xl rounded-2xl p-4 flex items-center gap-4 border border-brand-500 animate-slide-up max-w-sm w-full">
                    <div className={`p-2 rounded-full ${lastSmsTransaction.type === 'expense' ? 'bg-red-500/10 text-red-500' : 'bg-emerald-500/10 text-emerald-500'}`}>
                        <MessageSquare size={20} />
                    </div>
                    <div className="flex-1">
                        <p className="text-xs font-bold uppercase text-slate-400">New {lastSmsTransaction.type} Detected</p>
                        <p className="text-sm font-bold text-slate-800 dark:text-slate-100">{lastSmsTransaction.description}</p>
                        <p className={`text-lg font-bold ${lastSmsTransaction.type === 'expense' ? 'text-red-500' : 'text-emerald-500'}`}>
                            {lastSmsTransaction.type === 'expense' ? '-' : '+'}{lastSmsTransaction.amount.toLocaleString('en-IN', { style: 'currency', currency: 'INR' })}
                        </p>
                    </div>
                    <button onClick={() => setLastSmsTransaction(null)} className="text-slate-400 hover:text-slate-600">
                        <ArrowRight size={18} />
                    </button>
                </div>
            )}

            {/* Recurring Transactions Modal */}
            {showRecurringModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white dark:bg-slate-900 rounded-2xl max-w-lg w-full overflow-hidden shadow-2xl border border-slate-200 dark:border-white/10 animate-scale-in">
                        <div className="p-6 bg-brand-500 text-white">
                            <div className="flex items-center gap-3">
                                <Repeat size={24} />
                                <h3 className="text-xl font-bold">Recurring Items Due</h3>
                            </div>
                            <p className="opacity-90 mt-1 text-sm">The following items are due for processing.</p>
                        </div>
                        <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
                            {dueRecurringItems.map(item => (
                                <div key={item.id} className="flex items-center justify-between p-4 rounded-xl bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/5">
                                    <div>
                                        <p className="font-bold text-slate-800 dark:text-white">{item.description}</p>
                                        <p className="text-xs text-slate-500 flex items-center gap-1 mt-1">
                                            <span className={item.type === 'income' ? 'text-emerald-500' : 'text-red-500'}>
                                                {item.type === 'income' ? '+' : '-'}{item.amount.toLocaleString('en-IN', { style: 'currency', currency: 'INR' })}
                                            </span>
                                            <span>ΓÇó {item.frequency}</span>
                                        </p>
                                    </div>
                                    <Button size="sm" onClick={() => handleProcessRecurring(item.id)}>
                                        Confirm
                                    </Button>
                                </div>
                            ))}
                        </div>
                        <div className="p-4 border-t border-slate-200 dark:border-white/10 flex justify-end">
                            <Button variant="ghost" onClick={handleDismissRecurring}>Close</Button>
                        </div>
                    </div>
                </div>
            )}

            {/* VIEW: ACTIVITIES (Home) */}
            {(currentView === 'dashboard' || currentView === 'activities') && (
                <ActivitiesPage username={username} onEditTask={handleEditTask} />
            )}

            {/* VIEW: LISTS */}
            {(currentView === 'tasks' || currentView === 'reminders' || currentView === 'events' || currentView === 'appointments' || currentView === 'all-activities') && (
                <div className="space-y-6 h-full flex flex-col animate-fade-in">
                    <div className="flex flex-col md:flex-row gap-5 justify-between items-start md:items-center border-b border-slate-200 dark:border-white/5 pb-6">
                        <div>
                            <h2 className="text-3xl font-bold text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-3">
                                <HeaderIcon className="text-brand-500" size={32} />
                                {headerInfo.title}
                            </h2>
                            <p className="text-slate-500 dark:text-slate-400 mt-1">
                                {headerInfo.subtitle}
                            </p>
                        </div>

                        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                            <div className="relative flex-1 md:w-72">
                                <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                                <input
                                    type="text"
                                    placeholder="Search..."
                                    value={searchQuery}
                                    onChange={e => setSearchQuery(e.target.value)}
                                    className="w-full bg-slate-100 dark:bg-dark-surface border border-slate-200 dark:border-dark-border rounded-xl pl-10 pr-4 py-2.5 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 transition-all placeholder-slate-400 dark:placeholder-slate-500 shadow-sm"
                                />
                            </div>
                            <Select
                                value={filterStatus}
                                onChange={(value) => setFilterStatus(value)}
                                options={[
                                    { value: 'ALL', label: 'All Status' },
                                    { value: TaskStatus.TODO, label: 'To Do' },
                                    { value: TaskStatus.IN_PROGRESS, label: 'In Progress' },
                                    { value: TaskStatus.DONE, label: 'Done' }
                                ]}
                                currentTheme={theme}
                                className="w-40"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-4 pb-20">
                        {filteredTasks.map(task => (
                            <TaskCard
                                key={task.id}
                                task={task}
                                allTasks={tasks}
                                onEdit={handleEditTask}
                                onToggleStatus={handleToggleStatus}
                                onAIAnalysis={handleAIAnalysis}
                                onFocus={handleStartFocus}
                            />
                        ))}
                        {filteredTasks.length === 0 && (
                            <div className="flex flex-col items-center justify-center py-24 text-slate-500 dark:text-slate-400 glass-panel rounded-2xl border border-dashed border-slate-200 dark:border-white/10">
                                <div className="w-16 h-16 bg-brand-500/10 rounded-2xl flex items-center justify-center mb-4">
                                    <Filter size={32} className="text-brand-500" />
                                </div>
                                <p className="font-medium text-slate-600 dark:text-slate-300">No {currentView} found matching your filters.</p>
                                <Button variant="ghost" onClick={() => { setSearchQuery(''); setFilterStatus('ALL') }} className="mt-3 text-brand-500">Clear Filters</Button>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* VIEW: CALENDAR */}
            {currentView === 'calendar' && (
                <Suspense fallback={<div className="flex items-center justify-center h-64"><Loader2 className="animate-spin text-brand-500" size={32} /></div>}>
                    <CalendarView
                        tasks={calendarFilteredTasks}
                        recurringTransactions={budget.recurring}
                        externalEvents={externalEvents}
                        onDateClick={handleCreateTask}
                        onEditTask={handleEditTask}
                        onUpdateTask={updateTask}
                        onToggleStatus={handleToggleStatus}
                        selectedDate={calendarNavigateDate}
                        onVisibleTagsChange={setCalendarVisibleTags}
                        unfilteredTasks={visibleTasks}
                        currentTheme={theme}
                    />
                </Suspense>
            )}

            {/* VIEW: BUDGET */}
            {currentView === 'budget' && (
                <Suspense fallback={<div className="flex items-center justify-center h-64"><Loader2 className="animate-spin text-brand-500" size={32} /></div>}>
                    <BudgetPlanner currentTheme={theme} />
                </Suspense>
            )}

            {/* VIEW: NOTES */}
            {currentView === 'notes' && (
                <Suspense fallback={<div className="flex items-center justify-center h-64"><Loader2 className="animate-spin text-brand-500" size={32} /></div>}>
                    <NotesManager currentTheme={theme} />
                </Suspense>
            )}

            {/* AI CHAT MODAL */}
            {(currentView === 'ai-chat' || isAIChatOpen) && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
                    <div className="relative w-full max-w-4xl h-[85vh] rounded-2xl overflow-hidden border border-slate-200 dark:border-white/10 shadow-2xl bg-white dark:bg-slate-900 animate-scale-in">
                        <button
                            onClick={() => {
                                setIsAIChatOpen(false);
                                if (currentView === 'ai-chat') {
                                    navigate('/activities');
                                }
                            }}
                            className="absolute top-4 right-4 z-10 p-2 rounded-xl bg-slate-100 dark:bg-white/10 hover:bg-slate-200 dark:hover:bg-white/20 transition-colors text-slate-600 dark:text-slate-300"
                        >
                            <X size={20} />
                        </button>
                        <Suspense fallback={<div className="flex items-center justify-center h-64"><Loader2 className="animate-spin text-brand-500" size={32} /></div>}>
                            <AIChat
                                onConfirmTask={handleAutoCreatedTask}
                                onEditTask={handleEditDraft}
                                userName={username}
                                existingTags={allTags}
                            />
                        </Suspense>
                    </div>
                </div>
            )}

            {/* VIEW: ROUTINES */}
            {currentView === 'routines' && (
                <RoutineList
                    routines={routines}
                    onEdit={handleEditRoutine}
                    onDelete={handleDeleteRoutine}
                    onToggle={handleToggleRoutine}
                    onCreate={handleCreateRoutine}
                />
            )}

            {/* VIEW: DAY PLANNER */}
            {currentView === 'day-planner' && (
                <DayPlannerPage
                    tasks={visibleTasks}
                    onCreateTask={handleCreateTask}
                    onEditTask={handleEditTask}
                    createTask={createTask}
                />
            )}

            {/* VIEW: SETTINGS */}
            {currentView === 'settings' && (
                <SettingsPage
                    session={session}
                    username={username}
                    onUsernameChange={handleUsernameChange}
                    onSignOut={handleSignOut}
                    notificationSettings={notificationSettings}
                    notificationPermission={notificationPermission}
                    onNotificationToggle={handleNotificationToggle}
                    onNotificationPreferenceChange={handleNotificationPreferenceChange}
                    onNavigate={(path) => navigate(path)}
                    googleCalendarEnabled={googleCalendarEnabled}
                    hasGoogleToken={hasGoogleToken}
                    onGoogleCalendarToggle={handleGoogleCalendarToggle}
                />
            )}

            <TaskEditor
                isOpen={isEditorOpen}
                onClose={() => setIsEditorOpen(false)}
                onSave={handleSaveTask}
                onDelete={handleDeleteTask}
                task={editingTask}
                availableTasks={tasks}
                initialDate={calendarSelectedDate}
                initialType={editorInitialType}
                globalNotificationSettings={notificationSettings}
                onStartFocus={editingTask ? () => handleStartFocus(editingTask) : undefined}
            />

            {/* Routine Editor Modal */}
            <RoutineEditor
                isOpen={isRoutineEditorOpen}
                onClose={() => setIsRoutineEditorOpen(false)}
                onSave={handleSaveRoutine}
                onDelete={handleDeleteRoutine}
                routine={editingRoutine}
            />

            {/* Command Bar (Cmd+K Quick Add) */}
            <CommandBar
                isOpen={isCommandBarOpen}
                onClose={() => setIsCommandBarOpen(false)}
                onTaskParsed={handleCommandBarTask}
            />

            {/* Focus Mode Overlay */}
            {focusedTask && (
                <FocusSession
                    task={focusedTask}
                    isOpen={isFocusModeOpen}
                    onClose={() => {
                        setIsFocusModeOpen(false);
                        setFocusedTask(undefined);
                    }}
                    onComplete={handleCompleteFocus}
                />
            )}

            {/* Morning Briefing Modal */}
            <MorningBriefingModal
                isOpen={showBriefing}
                onClose={dismissBriefing}
                tasks={overdueTasks}
                username={username}
                onMoveToToday={async (taskIds) => {
                    const today = new Date().toISOString();
                    for (const id of taskIds) {
                        const task = tasks.find(t => t.id === id);
                        if (task) {
                            await updateTask({ ...task, dueDate: today });
                        }
                    }
                    dismissBriefing();
                }}
                onDelete={async (taskIds) => {
                    for (const id of taskIds) {
                        await deleteTask(id);
                    }
                    dismissBriefing();
                }}
            />


        </Layout>
    );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Send, Bot, User, Sparkles, PlusCircle, XCircle, Calendar, Bell, Edit2, Check, Clock, DollarSign, Wallet, TrendingDown, TrendingUp, Pencil, Trash2, RefreshCw, Copy, CheckCheck, ImagePlus, X, Image } from 'lucide-react';
import { chatWithAI, parseTransactionScreenshot } from '../services/geminiService';
import { ChatMessage, Task, TaskPriority, TaskStatus, TaskType, SuggestedPrompt } from '../types';
import * as BudgetService from '../services/budgetService';
import { saveChatHistory, loadChatHistory, clearChatHistory } from '../utils/aiChatStorage';
import Button from './Button';

interface AIChatProps {
  onConfirmTask?: (task: Partial<Task>) => void;
  onEditTask?: (task: Partial<Task>) => void;
  userName: string;
  existingTags: string[];
}

interface AIDraftItem {
    category: 'TASK' | 'EVENT' | 'APPOINTMENT' | 'REMINDER' | 'TRANSACTION' | 'BUDGET_UPDATE';
    data: any;
}

const SUGGESTED_PROMPTS: SuggestedPrompt[] = [
  { label: 'Create a task', prompt: 'Create a task to ', icon: 'Γ£ô' },
  { label: 'Schedule meeting', prompt: 'Schedule a meeting ', icon: '≡ƒôà' },
  { label: 'Add transaction', prompt: 'I spent ', icon: '≡ƒÆ░' },
  { label: 'Set reminder', prompt: 'Remind me to ', icon: '≡ƒöö' },
];

const AIChat: React.FC<AIChatProps> = ({ onConfirmTask, onEditTask, userName, existingTags }) => {
  const WELCOME_MESSAGE: ChatMessage = {
    id: 'welcome',
    role: 'model',
    text: "Hi! I'm ChronoDeX AI. I can create Tasks, Reminders, Events, Appointments, or help manage your Budget. Just tell me what you need.",
    timestamp: Date.now(),
    status: 'sent'
  };

  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    const loaded = loadChatHistory();
    return loaded && loaded.length > 0 ? loaded : [WELCOME_MESSAGE];
  });
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [draftGroups, setDraftGroups] = useState<Record<string, AIDraftItem[]>>({});
  const [copiedMsgId, setCopiedMsgId] = useState<string | null>(null);
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  // Save conversation to localStorage whenever messages change
  useEffect(() => {
    if (messages.length > 0) {
      saveChatHistory(messages);
    }
  }, [messages]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, draftGroups]);

  const getRelativeTime = (timestamp: number): string => {
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) return 'just now';
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  };

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = {
      id: crypto.randomUUID(),
      role: 'user',
      text: input,
      timestamp: Date.now(),
      status: 'sending'
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    // If there's an attached image, process it for transaction extraction
    if (selectedImage) {
      try {
        const transactions = await parseTransactionScreenshot(selectedImage);

        // Update user message status
        setMessages(prev => prev.map(m => m.id === userMsg.id ? { ...m, status: 'sent' as const } : m));

        // Create AI response with extracted transactions
        const aiMsg: ChatMessage = {
          id: crypto.randomUUID(),
          role: 'model',
          text: `I found ${transactions.length} transaction(s) in your image. Please review and confirm:`,
          timestamp: Date.now(),
          status: 'sent'
        };

        setMessages(prev => [...prev, aiMsg]);

        // Create drafts for each transaction
        const drafts: AIDraftItem[] = transactions.map(t => ({
          category: 'TRANSACTION' as const,
          data: {
            description: t.description,
            amount: t.amount,
            type: t.type,
            date: t.date
          }
        }));

        if (drafts.length > 0) {
          setDraftGroups(prev => ({ ...prev, [aiMsg.id]: drafts }));
        }
      } catch (error) {
        // Update user message status to error
        setMessages(prev => prev.map(m => m.id === userMsg.id ? { ...m, status: 'error' as const } : m));

        const errorMsg: ChatMessage = {
          id: crypto.randomUUID(),
          role: 'model',
          text: error instanceof Error ? error.message : 'Failed to process image. Please try again.',
          timestamp: Date.now(),
          status: 'error'
        };
        setMessages(prev => [...prev, errorMsg]);
      } finally {
        setIsLoading(false);
        handleRemoveImage();
      }
      return;
    }

    try {
        const history = messages
          .filter(m => m.status !== 'error') // Exclude error messages from history
          .map(m => ({
            role: m.role,
            parts: [{ text: m.text }] as [{ text: string }]
          }));

        const responseText = await chatWithAI(userMsg.text, history, userName, existingTags);

        // Update user message status to sent
        setMessages(prev => prev.map(m => m.id === userMsg.id ? { ...m, status: 'sent' as const } : m));

        const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/);

        let displayText = responseText;
        let newDrafts: AIDraftItem[] = [];

        if (jsonMatch) {
            try {
                const jsonStr = jsonMatch[1];
                const parsed = JSON.parse(jsonStr);
                const parsedArray = Array.isArray(parsed) ? parsed : [parsed];
                displayText = responseText.replace(jsonMatch[0], '').trim();
                newDrafts = parsedArray.map((p: any) => ({
                    category: p.category || (p.title ? 'TASK' : 'UNKNOWN'),
                    data: p.data || p
                }));
            } catch (e) {
                console.error("Failed to parse AI JSON", e);
            }
        }

        const aiMsg: ChatMessage = {
            id: crypto.randomUUID(),
            role: 'model',
            text: displayText,
            timestamp: Date.now(),
            status: 'sent'
        };

        setMessages(prev => [...prev, aiMsg]);
        if (newDrafts.length > 0) {
            setDraftGroups(prev => ({ ...prev, [aiMsg.id]: newDrafts }));
        }
    } catch (error) {
        console.error(error);
        // Mark user message as error
        setMessages(prev => prev.map(m => 
          m.id === userMsg.id 
            ? { ...m, status: 'error' as const, error: 'Failed to send' } 
            : m
        ));

        const errorMsg: ChatMessage = {
            id: crypto.randomUUID(),
            role: 'model',
            text: error instanceof Error ? error.message : "Sorry, I encountered a connection error. Please try again.",
            timestamp: Date.now(),
            status: 'error'
        };
        setMessages(prev => [...prev, errorMsg]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleRetry = (msgId: string) => {
    const msg = messages.find(m => m.id === msgId);
    if (!msg || msg.role !== 'user') return;

    // Remove error message and retry
    setMessages(prev => prev.filter(m => m.id !== msgId && !(m.timestamp > msg.timestamp && m.status === 'error')));
    setInput(msg.text);
    setTimeout(() => handleSend(), 100);
  };

  const handleCopyMessage = async (text: string, msgId: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedMsgId(msgId);
      setTimeout(() => setCopiedMsgId(null), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const handleClearChat = useCallback(() => {
    if (confirm('Are you sure you want to clear the chat history? This cannot be undone.')) {
      setMessages([WELCOME_MESSAGE]);
      setDraftGroups({});
      clearChatHistory();
    }
  }, [WELCOME_MESSAGE]);

  const handleSuggestedPrompt = useCallback((prompt: string) => {
    setInput(prompt);
    inputRef.current?.focus();
  }, []);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith('image/')) {
        alert('Please select an image file');
        return;
      }
      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        alert('Image must be less than 5MB');
        return;
      }
      setSelectedImage(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleRemoveImage = useCallback(() => {
    setSelectedImage(null);
    if (imagePreview) {
      URL.revokeObjectURL(imagePreview);
      setImagePreview(null);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  }, [imagePreview]);

  // Helper to ensure AI dates are treated as local time if they lack time component
  const normalizeDraftData = (data: any) => {
    const newData = { ...data };

    const fixDate = (dateStr: string) => {
        if (dateStr && typeof dateStr === 'string' && dateStr.length === 10 && !dateStr.includes('T')) {
            return `${dateStr}T09:00:00`;
        }
        return dateStr;
    };

    if (newData.dueDate) newData.dueDate = fixDate(newData.dueDate);
    if (newData.reminderTime) newData.reminderTime = fixDate(newData.reminderTime);

    return newData;
  };

  const confirmSingleDraft = (msgId: string, index: number) => {
      const draft = draftGroups[msgId][index];
      if (['TASK', 'EVENT', 'APPOINTMENT', 'REMINDER'].includes(draft.category)) {
          const normalizedData = normalizeDraftData(draft.data);
          onConfirmTask?.({
              ...normalizedData,
              type: draft.category as TaskType,
              status: TaskStatus.TODO,
              subtasks: normalizedData.subtasks || [],
              tags: normalizedData.tags || ['AI-Created'],
          });
      } else if (draft.category === 'TRANSACTION') {
          BudgetService.addTransaction(draft.data.description, Number(draft.data.amount), draft.data.type || 'expense');
      } else if (draft.category === 'BUDGET_UPDATE') {
          BudgetService.updateBudgetSettings(Number(draft.data.limit), draft.data.duration || 'Monthly');
      }
      discardSingleDraft(msgId, index);
  };

  const editSingleDraft = (msgId: string, index: number) => {
    const draft = draftGroups[msgId][index];
    if (['TASK', 'EVENT', 'APPOINTMENT', 'REMINDER'].includes(draft.category)) {
        const normalizedData = normalizeDraftData(draft.data);
        onEditTask?.({
            ...normalizedData,
            type: draft.category as TaskType,
            status: TaskStatus.TODO,
            subtasks: normalizedData.subtasks || [],
            tags: normalizedData.tags || ['AI-Created'],
        });
        discardSingleDraft(msgId, index);
    }
  };

  const discardSingleDraft = (msgId: string, index: number) => {
      setDraftGroups(prev => {
          const group = [...(prev[msgId] || [])];
          group.splice(index, 1);
          if (group.length === 0) {
              const { [msgId]: _, ...rest } = prev;
              return rest;
          }
          return { ...prev, [msgId]: group };
      });
  };

  const renderMessageText = (text: string) => {
    const parts = text.split(/(\*\*[^*]+\*\*)/g);
    return parts.map((part, index) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold text-slate-900 dark:text-brand-300">{part.substring(2, part.length - 2)}</strong>;
      }
      return part;
    });
  };

