import React, { memo, useState } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { format } from 'date-fns';
import { Task, RecurringTransaction } from '../types';
import DraggableTask, { TYPE_COLORS } from './DraggableTask';
import { DollarSign, X } from 'lucide-react';

interface CalendarDayCellProps {
  day: number | null;
  date: Date | null;
  tasks: Task[];
  financialItems?: RecurringTransaction[];
  isToday: boolean;
  onClick: () => void;
}

const CalendarDayCell = memo(({ day, date, tasks, financialItems = [], isToday, onClick }: CalendarDayCellProps) => {
  const [showFinancialPopup, setShowFinancialPopup] = useState(false);

  const droppableId = date ? format(date, 'yyyy-MM-dd') : `empty-${day}`;
  const { setNodeRef, isOver } = useDroppable({
    id: droppableId,
    data: { date },
    disabled: !date,
  });

  const handleFinancialClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowFinancialPopup(true);
  };

  return (
    <div
      ref={setNodeRef}
      onClick={onClick}
      className={`
        relative border rounded-xl p-2 flex flex-col transition-all cursor-pointer overflow-hidden
        ${!day ? 'border-transparent cursor-default' : 'glass border-slate-200 dark:border-white/5 hover:border-brand-500/30 hover:shadow-lg'}
        ${isToday ? 'bg-brand-500/5 border-brand-500/30' : ''}
        ${isOver ? 'ring-2 ring-brand-500 bg-brand-500/10' : ''}
      `}
    >
      {day && (
        <>
          <div className="flex items-center justify-between mb-1">
            <span className={`text-sm font-semibold ${isToday ? 'text-brand-500' : 'text-slate-400'}`}>
              {day}
            </span>
            {/* Financial Indicator */}
            {financialItems.length > 0 && (
              <button
                onClick={handleFinancialClick}
                className="flex items-center gap-0.5 px-1.5 py-0.5 rounded-full bg-emerald-500/10 hover:bg-emerald-500/20 transition-colors group"
                title="Financial items due"
              >
                <DollarSign size={10} className="text-emerald-500" />
                <span className="text-[9px] font-bold text-emerald-600 dark:text-emerald-400">
                  {financialItems.length}
                </span>
              </button>
            )}
          </div>
          <div className="flex-1 flex flex-col gap-1 overflow-hidden">
            {tasks.slice(0, 3).map(task => {
              // Check if this is a recurring task
              const isRecurring = task.recurrence && task.recurrence.frequency !== 'none';

              // If recurring, check if this date is the most recent/relevant occurrence
              let isMostRecentOccurrence = true;
              if (isRecurring && date && (task.dueDate || task.reminderTime)) {
                const taskDateStr = task.dueDate || task.reminderTime;
                const taskDate = new Date(taskDateStr);

                // Normalize dates to compare only date parts
                const taskDateOnly = new Date(taskDate.getFullYear(), taskDate.getMonth(), taskDate.getDate());
                const currentDateOnly = new Date(date.getFullYear(), date.getMonth(), date.getDate());
                const today = new Date();
                const todayOnly = new Date(today.getFullYear(), today.getMonth(), today.getDate());

                // Calculate days from today for both the task's original date and the current occurrence
                const daysFromTodayOriginal = Math.abs(todayOnly.getTime() - taskDateOnly.getTime());
                const daysFromTodayCurrent = Math.abs(todayOnly.getTime() - currentDateOnly.getTime());

                // The most recent occurrence is the one closest to today
                // If the current cell's date is farther from today than the original date, dull it
                isMostRecentOccurrence = daysFromTodayCurrent <= daysFromTodayOriginal;
              }

              // Apply opacity if it's a recurring task but not the most recent occurrence
              const shouldDull = isRecurring && !isMostRecentOccurrence;

              return (
                <div key={task.id} className={shouldDull ? 'opacity-50' : ''}>
                  <DraggableTask task={task} variant="chip" />
                </div>
              );
            })}
            {tasks.length > 3 && (
              <div className="text-[10px] text-slate-500 pl-1">
                +{tasks.length - 3} more
              </div>
            )}
          </div>
        </>
      )}

      {/* Financial Items Popup */}
      {showFinancialPopup && financialItems.length > 0 && (
        <div 
          className="absolute inset-0 z-30 flex items-center justify-center"
          onClick={(e) => e.stopPropagation()}
        >
          <div 
            className="absolute inset-0 bg-black/40 backdrop-blur-sm rounded-xl"
            onClick={() => setShowFinancialPopup(false)}
          />
          <div className="relative bg-white dark:bg-slate-800 rounded-lg shadow-xl border border-slate-200 dark:border-white/10 p-3 m-1 w-full max-h-full overflow-y-auto">
            <button
              onClick={() => setShowFinancialPopup(false)}
              className="absolute top-1 right-1 p-0.5 rounded-full hover:bg-black/5 dark:hover:bg-white/5 text-slate-400"
            >
              <X size={12} />
            </button>
            <div className="flex items-center gap-1.5 mb-2">
              <DollarSign size={12} className="text-emerald-500" />
              <span className="text-[10px] font-bold uppercase tracking-wide text-slate-500">Bills Due</span>
            </div>
            <div className="space-y-1.5">
              {financialItems.map(item => (
                <div 
                  key={item.id}
                  className={`p-1.5 rounded-md text-[10px] ${
                    item.type === 'expense' 
                      ? 'bg-red-50 dark:bg-red-500/10 border border-red-100 dark:border-red-500/20' 
                      : 'bg-emerald-50 dark:bg-emerald-500/10 border border-emerald-100 dark:border-emerald-500/20'
                  }`}
                >
                  <p className="font-medium text-slate-700 dark:text-slate-200 truncate">{item.description}</p>
                  <p className={`font-bold ${item.type === 'expense' ? 'text-red-500' : 'text-emerald-500'}`}>
                    {item.type === 'expense' ? '-' : '+'}Γé╣{item.amount.toLocaleString()}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}, (prev, next) => {
  if (prev.day !== next.day) return false;
  if (prev.isToday !== next.isToday) return false;
  if (prev.date?.getTime() !== next.date?.getTime()) return false;
  if (prev.financialItems?.length !== next.financialItems?.length) return false;
  if (prev.tasks === next.tasks && prev.financialItems === next.financialItems) return true;
  if (prev.tasks.length !== next.tasks.length) return false;

  for (let i = 0; i < prev.tasks.length; i++) {
    const t1 = prev.tasks[i];
    const t2 = next.tasks[i];
    if (t1.id !== t2.id || t1.title !== t2.title || t1.priority !== t2.priority || t1.type !== t2.type || t1.status !== t2.status) return false;
  }

  return true;
});

export default CalendarDayCell;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { ChevronLeft, ChevronRight, Plus, X, Clock, Repeat, Calendar, CalendarDays, CalendarClock, Settings2, CheckCircle2, Circle, ExternalLink, MapPin } from 'lucide-react';
import { DndContext, DragEndEvent, DragOverlay, pointerWithin } from '@dnd-kit/core';
import { format, addWeeks, subWeeks, startOfWeek, endOfWeek, addMonths, subMonths, isSameDay, addDays, subDays, startOfMonth, endOfMonth } from 'date-fns';
import { formatDateWithWeekday } from '../utils/date';
import { Task, TaskPriority, TaskStatus, RecurringTransaction, ThemeOption } from '../types';
import { CalendarEvent, formatEventTime, doesEventOccurOnDate } from '../services/googleCalendarService';
import Button from './Button';
import CalendarDayCell from './CalendarDayCell';
import WeekView from './WeekView';
import DayView from './DayView';
import CustomIntervalView from './CustomIntervalView';
import DraggableTask, { TYPE_COLORS } from './DraggableTask';
import Select from './Select';

interface CalendarViewProps {
    tasks: Task[];
    recurringTransactions?: RecurringTransaction[];
    externalEvents?: CalendarEvent[]; // Google Calendar events
    onDateClick: (date: Date) => void;
    onEditTask: (task: Task) => void;
    onUpdateTask?: (task: Task) => void;
    onToggleStatus?: (task: Task) => void;
    selectedDate?: Date; // Jump to this date when provided
    onVisibleTagsChange?: (tags: string[]) => void; // Report tags visible in current view
    unfilteredTasks?: Task[]; // Tasks before filtering by selected tags (for computing available tags)
    currentTheme?: ThemeOption;
}

type ViewMode = 'month' | 'week' | 'day' | 'custom';
type IntervalUnit = 'day' | 'week' | 'month';

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, recurringTransactions = [], externalEvents = [], onDateClick, onEditTask, onUpdateTask, onToggleStatus, selectedDate: propSelectedDate, onVisibleTagsChange, unfilteredTasks, currentTheme = 'dark' }) => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);
    const [viewMode, setViewMode] = useState<ViewMode>('month');
    const [activeTask, setActiveTask] = useState<Task | null>(null);
    const [customIntervalValue, setCustomIntervalValue] = useState(3); // Numeric value
    const [customIntervalUnit, setCustomIntervalUnit] = useState<IntervalUnit>('day'); // Unit
    const [showIntervalDropdown, setShowIntervalDropdown] = useState(false);
    const intervalDropdownRef = useRef<HTMLDivElement>(null);
    const [selectedGoogleEvent, setSelectedGoogleEvent] = useState<CalendarEvent | null>(null); // Google event detail modal

    // Handle selectedDate prop - jump to that date when it changes
    useEffect(() => {
        if (propSelectedDate) {
            setCurrentDate(propSelectedDate);
            setViewMode('day'); // Switch to day view when a specific date is selected
        }
    }, [propSelectedDate]);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (intervalDropdownRef.current && !intervalDropdownRef.current.contains(event.target as Node)) {
                setShowIntervalDropdown(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);


    const currentMonth = useMemo(() => new Date(currentDate.getFullYear(), currentDate.getMonth(), 1), [currentDate]);

    const getDaysInMonth = (year: number, month: number) => {
        return new Date(year, month + 1, 0).getDate();
    };

    const getFirstDayOfMonth = (year: number, month: number) => {
        return new Date(year, month, 1).getDay();
    };

    // Calculate custom interval in days based on value and unit
    const customIntervalDays = useMemo(() => {
        switch (customIntervalUnit) {
            case 'week': return customIntervalValue * 7;
            case 'month': return customIntervalValue * 30; // Approximate
            default: return customIntervalValue;
        }
    }, [customIntervalValue, customIntervalUnit]);

    // Compute tags visible in the current view period
    const visibleTags = useMemo(() => {
        const tags = new Set<string>();
        
        // Determine date range based on view mode
        let rangeStart: Date;
        let rangeEnd: Date;
        
        if (viewMode === 'month') {
            rangeStart = startOfMonth(currentDate);
            rangeEnd = endOfMonth(currentDate);
        } else if (viewMode === 'week') {
            rangeStart = startOfWeek(currentDate, { weekStartsOn: 0 });
            rangeEnd = endOfWeek(currentDate, { weekStartsOn: 0 });
        } else if (viewMode === 'day') {
            rangeStart = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate());
            rangeEnd = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate(), 23, 59, 59);
        } else {
            // Custom interval
            rangeStart = new Date(currentDate.getFullYear(), currentDate.getMonth(), currentDate.getDate());
            rangeEnd = addDays(rangeStart, customIntervalDays - 1);
            rangeEnd.setHours(23, 59, 59);
        }

        // Check each task to see if it falls within the range
        // Use unfilteredTasks if available to show ALL possible tags for this view, otherwise fall back to tasks
        (unfilteredTasks || tasks).forEach(task => {
            const taskDateStr = task.dueDate || task.reminderTime;
            if (!taskDateStr) return;
            
            const taskDate = new Date(taskDateStr);
            
            // Check if task is within range (including recurrence)
            const isInRange = taskDate >= rangeStart && taskDate <= rangeEnd;
            
            // For recurring tasks, we need to check if any occurrence is in range
            let hasOccurrenceInRange = isInRange;
            if (!isInRange && task.recurrence && task.recurrence.frequency !== 'none') {
                // Simple check: iterate through the range days to see if task recurs
                let checkDate = new Date(rangeStart);
                while (checkDate <= rangeEnd && !hasOccurrenceInRange) {
                    if (taskDate <= checkDate) {
                        const diffTime = checkDate.getTime() - taskDate.getTime();
                        const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
                        
                        if (task.recurrence.frequency === 'daily' && diffDays % task.recurrence.interval === 0) {
                            hasOccurrenceInRange = true;
                        } else if (task.recurrence.frequency === 'weekly' && 
                                   checkDate.getDay() === taskDate.getDay() && 
                                   Math.floor(diffDays / 7) % task.recurrence.interval === 0) {
                            hasOccurrenceInRange = true;
                        } else if (task.recurrence.frequency === 'monthly' && 
                                   checkDate.getDate() === taskDate.getDate()) {
                            hasOccurrenceInRange = true;
                        } else if (task.recurrence.frequency === 'yearly' && 
                                   checkDate.getMonth() === taskDate.getMonth() && 
                                   checkDate.getDate() === taskDate.getDate()) {
                            hasOccurrenceInRange = true;
                        }
                    }
                    checkDate = addDays(checkDate, 1);
                }
            }
            
            if (hasOccurrenceInRange) {
                if (task.tags.length === 0) {
                    tags.add('Untagged');
                } else {
                    task.tags.forEach(tag => tags.add(tag));
                }
            }
        });

        return Array.from(tags).sort((a, b) => {
            if (a === 'Untagged') return -1;
            if (b === 'Untagged') return 1;
            return a.localeCompare(b);
        });
    }, [tasks, unfilteredTasks, currentDate, viewMode, customIntervalDays]);

    // Report visible tags to parent component
    useEffect(() => {
        if (onVisibleTagsChange) {
            onVisibleTagsChange(visibleTags);
        }
    }, [visibleTags, onVisibleTagsChange]);
    // Get display label for custom interval
    const getCustomIntervalLabel = () => {
        const unitLabels: Record<IntervalUnit, string> = { day: 'D', week: 'W', month: 'M' };
        return `${customIntervalValue}${unitLabels[customIntervalUnit]}`;
    };

    // Validate and clamp interval value
    const handleIntervalValueChange = (value: number) => {
        // Calculate max value based on unit (12 months max = 365 days)
        let maxValue: number;
        switch (customIntervalUnit) {
            case 'month': maxValue = 12; break;
            case 'week': maxValue = 52; break; // ~12 months
            default: maxValue = 365; break; // 12 months in days
        }
        const clampedValue = Math.max(1, Math.min(maxValue, value));
        setCustomIntervalValue(clampedValue);
    };

    // Handle unit change and adjust value if needed
    const handleIntervalUnitChange = (unit: IntervalUnit) => {
        setCustomIntervalUnit(unit);
        // Clamp value to new unit's max
        let maxValue: number;
        switch (unit) {
            case 'month': maxValue = 12; break;
            case 'week': maxValue = 52; break;
            default: maxValue = 365; break;
        }
        if (customIntervalValue > maxValue) {
            setCustomIntervalValue(maxValue);
        }
    };

    const navigate = (direction: number) => {
        if (viewMode === 'month') {
            setCurrentDate(direction > 0 ? addMonths(currentDate, 1) : subMonths(currentDate, 1));
        } else if (viewMode === 'week') {
            setCurrentDate(direction > 0 ? addWeeks(currentDate, 1) : subWeeks(currentDate, 1));
        } else if (viewMode === 'day') {
            setCurrentDate(direction > 0 ? addDays(currentDate, 1) : subDays(currentDate, 1));
        } else if (viewMode === 'custom') {
            setCurrentDate(direction > 0 ? addDays(currentDate, customIntervalDays) : subDays(currentDate, customIntervalDays));
        }
    };


    // Optimized helper to check if a recurring task happens on a specific date without re-parsing dates
    const checkRecurrence = useCallback((task: Task, taskDate: Date, date: Date): boolean => {
        const isSameDay = taskDate.getDate() === date.getDate() &&
            taskDate.getMonth() === date.getMonth() &&
            taskDate.getFullYear() === date.getFullYear();

        if (isSameDay) return true;

        if (!task.recurrence || task.recurrence.frequency === 'none') return false;
        if (date < taskDate) return false;
        if (task.recurrence.endDate && date > new Date(task.recurrence.endDate)) return false;

        const diffTime = Math.abs(date.getTime() - taskDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        const { frequency, interval } = task.recurrence;

        if (frequency === 'daily') {
            return diffDays % interval === 0;
        }

        if (frequency === 'weekly') {
            if (date.getDay() !== taskDate.getDay()) return false;
            const diffWeeks = Math.floor(diffDays / 7);
            return diffWeeks % interval === 0;
        }

        if (frequency === 'monthly') {
            if (date.getDate() !== taskDate.getDate()) return false;
            const monthDiff = (date.getFullYear() - taskDate.getFullYear()) * 12 + (date.getMonth() - taskDate.getMonth());
            return monthDiff > 0 && monthDiff % interval === 0;
        }

        if (frequency === 'yearly') {
            return date.getMonth() === taskDate.getMonth() && date.getDate() === taskDate.getDate();
        }

        return false;
    }, []);

    // Wrapper for single date checks (legacy support)
    const doesTaskOccurOnDate = useCallback((task: Task, date: Date): boolean => {
        let taskDateStr = task.dueDate || task.reminderTime;
        if (!taskDateStr) return false;

        if (taskDateStr.length === 10 && !taskDateStr.includes('T')) {
            taskDateStr += 'T00:00:00';
        }

        const taskDate = new Date(taskDateStr);
        return checkRecurrence(task, taskDate, date);
    }, [checkRecurrence]);

    // Helper to check if a recurring transaction is due on a specific date
    const getFinancialItemsForDate = useCallback((date: Date): RecurringTransaction[] => {
        return recurringTransactions.filter(transaction => {
            const dueDate = new Date(transaction.nextDueDate);
            return isSameDay(dueDate, date);
        });
    }, [recurringTransactions]);

    // Optimized calendar generation: O(Tasks + Days) instead of O(Tasks * Days)
    const calendarDays = useMemo(() => {
        const year = currentMonth.getFullYear();
        const month = currentMonth.getMonth();
        const daysInMonth = getDaysInMonth(year, month);
        const firstDay = getFirstDayOfMonth(year, month);

        // 1. Initialize Map for tasks
        const tasksByDay = new Map<number, Task[]>();
        for (let i = 1; i <= daysInMonth; i++) tasksByDay.set(i, []);

        // 2. Iterate Tasks Once
        tasks.forEach(task => {
            let taskDateStr = task.dueDate || task.reminderTime;
            if (!taskDateStr) return;

            if (taskDateStr.length === 10 && !taskDateStr.includes('T')) {
                taskDateStr += 'T00:00:00';
            }

            const taskDate = new Date(taskDateStr);

            // Optimization for non-recurring (O(1) insertion)
            if (!task.recurrence || task.recurrence.frequency === 'none') {
                if (taskDate.getMonth() === month && taskDate.getFullYear() === year) {
                    const day = taskDate.getDate();
                    if (tasksByDay.has(day)) {
                        tasksByDay.get(day)!.push(task);
                    }
                }
            } else {
                // Recurring: Check against days in month
                // This is still iterated, but only for recurring tasks (minority)
                for (let day = 1; day <= daysInMonth; day++) {
                    const currentDayDate = new Date(year, month, day);
                    if (checkRecurrence(task, taskDate, currentDayDate)) {
                        tasksByDay.get(day)!.push(task);
                    }
                }
            }
        });

        // 3. Build Result Array
        const days: Array<{ day: number | null; date?: Date; tasks?: Task[]; financialItems?: RecurringTransaction[] }> = [];

        for (let i = 0; i < firstDay; i++) {
            days.push({ day: null });
        }

        for (let i = 1; i <= daysInMonth; i++) {
            const date = new Date(year, month, i);
            const dayTasks = tasksByDay.get(i) || [];
            const financialItems = getFinancialItemsForDate(date);
            days.push({ day: i, date: date, tasks: dayTasks, financialItems });
        }

        return days;
    }, [currentMonth, tasks, checkRecurrence, getFinancialItemsForDate]);

    const handleDayClick = (date: Date) => {
        setSelectedDate(date);
    };

    const selectedDayTasks = selectedDate
        ? tasks.filter(task => doesTaskOccurOnDate(task, selectedDate))
        : [];

    // Filter Google Calendar events for the selected date
    const selectedDayGoogleEvents = selectedDate
        ? externalEvents.filter(event => doesEventOccurOnDate(event, selectedDate))
        : [];

    // Drag and Drop handlers
    const handleDragStart = (event: any) => {
        const { active } = event;
        const task = tasks.find(t => t.id === active.id);
        if (task) setActiveTask(task);
    };

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveTask(null);

        if (!over || !onUpdateTask) return;

        const task = tasks.find(t => t.id === active.id);
        if (!task) return;

        // Parse the droppable ID to get the new date/time
        const overId = over.id as string;
        let newDate: Date;

        if (overId.includes('-')) {
            // Week view: format is "yyyy-MM-dd-HH"
            const parts = overId.split('-');
            if (parts.length === 4) {
                // Week view hour cell
                const [year, month, day, hour] = parts;
                newDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), parseInt(hour));
            } else if (parts.length === 3) {
                // Month view day cell
                const [year, month, day] = parts;
                newDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
            } else {
                return;
            }
        } else {
            return;
        }

        // Update task with new date
        const updatedTask: Task = {
            ...task,
            dueDate: newDate.toISOString(),
            reminderTime: task.reminderTime 
                ? new Date(newDate.getFullYear(), newDate.getMonth(), newDate.getDate(), 
                    new Date(task.reminderTime).getHours(), new Date(task.reminderTime).getMinutes()
                  ).toISOString()
                : undefined
        };

        onUpdateTask(updatedTask);
    };

    const getHeaderTitle = () => {
        if (viewMode === 'month') {
            return currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' });
        } else if (viewMode === 'week') {
            const weekStart = startOfWeek(currentDate, { weekStartsOn: 0 });
            return format(weekStart, 'MMM d, yyyy');
        } else if (viewMode === 'day') {
            return format(currentDate, 'EEEE, MMMM d, yyyy');
        } else {
            // Custom interval
            const endDate = addDays(currentDate, customIntervalDays - 1);
            return `${format(currentDate, 'MMM d')} - ${format(endDate, 'MMM d, yyyy')}`;
        }
    };


    return (
        <DndContext
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
            collisionDetection={pointerWithin}
        >
            <div className="h-full flex flex-col animate-fade-in relative">
                {/* Header */}
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 mb-4 sm:mb-6 border-b border-slate-200 dark:border-white/5 pb-4">
                    <h2 className="text-xl sm:text-3xl font-bold text-slate-800 dark:text-slate-100">
                        {getHeaderTitle()}
                    </h2>
                    <div className="flex items-center gap-2 sm:gap-4 overflow-x-auto no-scrollbar">
                        {/* View Toggle */}
                        <div className="flex bg-slate-100 dark:bg-slate-800 rounded-lg p-0.5 sm:p-1 shrink-0">
                            <button
                                onClick={() => setViewMode('month')}
                                className={`flex items-center gap-1 px-2 sm:px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                                    viewMode === 'month'
                                        ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-sm'
                                        : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                }`}
                                aria-label="Month view"
                            >
                                <Calendar size={14} className="sm:w-4 sm:h-4" />
                                <span className="hidden sm:inline">Month</span>
                            </button>
                            <button
                                onClick={() => setViewMode('week')}
                                className={`flex items-center gap-1 px-2 sm:px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                                    viewMode === 'week'
                                        ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-sm'
                                        : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                }`}
                                aria-label="Week view"
                            >
                                <CalendarDays size={14} className="sm:w-4 sm:h-4" />
                                <span className="hidden sm:inline">Week</span>
                            </button>
                            <button
                                onClick={() => setViewMode('day')}
                                className={`flex items-center gap-1 px-2 sm:px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                                    viewMode === 'day'
                                        ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-sm'
                                        : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                }`}
                                aria-label="Day view"
                            >
                                <CalendarClock size={14} className="sm:w-4 sm:h-4" />
                                <span className="hidden sm:inline">Day</span>
                            </button>
                            
                            {/* Custom Interval Dropdown */}
                            <div className="relative" ref={intervalDropdownRef}>
                                <button
                                    onClick={() => {
                                        setShowIntervalDropdown(!showIntervalDropdown);
                                    }}
                                    className={`flex items-center gap-1 px-2 sm:px-3 py-1.5 rounded-md text-xs sm:text-sm font-medium transition-all ${
                                        viewMode === 'custom'
                                            ? 'bg-white dark:bg-slate-700 text-brand-500 shadow-sm'
                                            : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                    }`}
                                    aria-label="Custom interval view"
                                >
                                    <Settings2 size={14} className="sm:w-4 sm:h-4" />
                                    <span className="hidden sm:inline">{viewMode === 'custom' ? getCustomIntervalLabel() : 'Custom'}</span>
                                </button>
                                
                                {showIntervalDropdown && (
                                    <div className="absolute top-full right-0 mt-2 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border border-slate-200 dark:border-white/10 p-3 z-50 animate-scale-in">
                                        <p className="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2">Custom Interval</p>
                                        <div className="flex items-center gap-2">
                                            <input
                                                type="number"
                                                min="1"
                                                max={customIntervalUnit === 'month' ? 12 : customIntervalUnit === 'week' ? 52 : 365}
                                                value={customIntervalValue}
                                                onChange={(e) => handleIntervalValueChange(parseInt(e.target.value) || 1)}
                                                className="w-16 bg-slate-100 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-md px-2 py-1.5 text-sm text-center text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                                            />
                                            <Select
                                                value={customIntervalUnit}
                                                onChange={(value) => handleIntervalUnitChange(value as IntervalUnit)}
                                                options={[
                                                    { value: 'day', label: `Day${customIntervalValue !== 1 ? 's' : ''}` },
                                                    { value: 'week', label: `Week${customIntervalValue !== 1 ? 's' : ''}` },
                                                    { value: 'month', label: `Month${customIntervalValue !== 1 ? 's' : ''}` }
                                                ]}
                                                currentTheme={currentTheme}
                                                className="flex-1 min-w-[100px]"
                                            />
                                        </div>
                                        <p className="text-[10px] text-slate-400 dark:text-slate-500 mt-2">Min: 1 day ΓÇó Max: 12 months</p>
                                        <button
                                            onClick={() => {
                                                setViewMode('custom');
                                                setShowIntervalDropdown(false);
                                            }}
                                            className="w-full mt-3 px-3 py-1.5 bg-brand-500 text-white dark:text-slate-900 text-sm font-medium rounded-md hover:bg-brand-600 transition-colors"
                                        >
                                            Apply
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Today Button */}
                        <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => setCurrentDate(new Date())}
                            className="text-brand-500 hover:text-brand-600 text-xs sm:text-sm shrink-0"
                        >
                            Today
                        </Button>

                        {/* Navigation */}
                        <div className="flex gap-1 sm:gap-2 shrink-0">
                            <Button variant="secondary" size="icon" onClick={() => navigate(-1)} className="w-8 h-8 sm:w-10 sm:h-10" aria-label="Previous period">
                                <ChevronLeft size={18} className="sm:w-5 sm:h-5" />
                            </Button>
                            <Button variant="secondary" size="icon" onClick={() => navigate(1)} className="w-8 h-8 sm:w-10 sm:h-10" aria-label="Next period">
                                <ChevronRight size={18} className="sm:w-5 sm:h-5" />
                            </Button>
                        </div>
                    </div>
                </div>

                {/* Calendar Content */}
                {viewMode === 'month' && (
                    <div className="flex-1 min-h-0 flex flex-col">
                        {/* Day Names */}
                        <div className="grid grid-cols-7 mb-2">
                            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
                                <div key={day} className="text-center text-xs font-bold text-slate-500 uppercase tracking-wider py-2">
                                    {day}
                                </div>
                            ))}
                        </div>

                        {/* Days Grid */}
                        <div className="flex-1 grid grid-cols-7 grid-rows-6 gap-2 min-h-[600px]">
                            {calendarDays.map((cell, idx) => (
                                <CalendarDayCell
                                    key={idx}
                                    day={cell.day}
                                    date={cell.date || null}
                                    tasks={cell.tasks || []}
                                    financialItems={cell.financialItems || []}
                                    isToday={cell.date?.toDateString() === new Date().toDateString()}
                                    onClick={() => cell.date && handleDayClick(cell.date)}
                                />
                            ))}
                        </div>
                    </div>
                )}

                {viewMode === 'week' && (
                    <WeekView
                        tasks={tasks}
                        currentDate={currentDate}
                        onEditTask={onEditTask}
                    />
                )}

                {viewMode === 'day' && (
                    <DayView
                        tasks={tasks}
                        currentDate={currentDate}
                        onEditTask={onEditTask}
                    />
                )}

                {viewMode === 'custom' && (
                    <CustomIntervalView
                        tasks={tasks}
                        currentDate={currentDate}
                        intervalDays={customIntervalDays}
                        onEditTask={onEditTask}
                    />
                )}

                {/* Day Detail Modal */}
                {selectedDate && (
                    <div className="absolute inset-0 z-20 flex items-center justify-center p-4">
                        <div className="absolute inset-0 bg-black/60 dark:bg-black/60 backdrop-blur-sm" onClick={() => setSelectedDate(null)} />
                        <div className="relative w-full max-w-md glass rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[70vh]">
                            <div className="p-4 border-b border-slate-200 dark:border-white/5 flex items-center justify-between bg-white/50 dark:bg-slate-900/50">
                                <div>
                                    <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">
                                        {formatDateWithWeekday(selectedDate)}
                                    </h3>
                                    <p className="text-xs text-slate-500 font-medium">
                                        {selectedDayTasks.length + selectedDayGoogleEvents.length} activities scheduled
                                        {selectedDayGoogleEvents.length > 0 && (
                                            <span className="ml-1 text-blue-500">
                                                ({selectedDayGoogleEvents.length} from Google)
                                            </span>
                                        )}
                                    </p>
                                </div>
                                <button onClick={() => setSelectedDate(null)} className="p-1 rounded-full hover:bg-black/5 dark:hover:bg-white/5 text-slate-400 hover:text-slate-800 dark:hover:text-white" aria-label="Close">
                                    <X size={20} />
                                </button>
                            </div>

                            <div className="flex-1 overflow-y-auto p-4 space-y-3">
                                {selectedDayTasks.length === 0 && selectedDayGoogleEvents.length === 0 && (
                                    <p className="text-center text-slate-500 py-8 italic">No activities for this day.</p>
                                )}
                                
                                {/* App Tasks */}
                                {selectedDayTasks.map(task => {
                                    const colorClass = TYPE_COLORS[task.type] || TYPE_COLORS.TASK;
                                    const isDone = task.status === TaskStatus.DONE;
                                    return (
                                        <div
                                            key={task.id}
                                            className={`group p-3 rounded-xl border-l-4 cursor-pointer transition-all ${colorClass} hover:shadow-md ${isDone ? 'opacity-60' : ''}`}
                                        >
                                            <div className="flex items-start gap-3">
                                                {/* Toggle Status Button */}
                                                {onToggleStatus && (
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            onToggleStatus(task);
                                                        }}
                                                        className={`mt-0.5 flex-shrink-0 transition-all duration-200 hover:scale-110 active:scale-95 ${
                                                            isDone
                                                                ? 'text-emerald-500 drop-shadow-sm'
                                                                : 'text-slate-400 hover:text-brand-500'
                                                        }`}
                                                        aria-label={isDone ? "Mark as incomplete" : "Mark as complete"}
                                                    >
                                                        {isDone ? <CheckCircle2 size={20} /> : <Circle size={20} />}
                                                    </button>
                                                )}
                                                
                                                {/* Task Content */}
                                                <div className="flex-1 min-w-0" onClick={() => onEditTask(task)}>
                                                    <h4 className={`font-semibold text-sm ${isDone ? 'line-through text-slate-400 dark:text-slate-500' : ''}`}>{task.title}</h4>
                                                    <div className="flex items-center gap-3 text-xs opacity-75 mt-1">
                                                        {task.reminderTime && (
                                                            <span className="flex items-center gap-1">
                                                                <Clock size={10} />
                                                                {new Date(task.reminderTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                            </span>
                                                        )}
                                                        {task.recurrence && task.recurrence.frequency !== 'none' && (
                                                            <span className="flex items-center gap-1">
                                                                <Repeat size={10} /> {task.recurrence.frequency}
                                                            </span>
                                                        )}
                                                        {isDone && (
                                                            <span className="text-emerald-500 font-medium">Γ£ô Done</span>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}

                                {/* Google Calendar Events */}
                                {selectedDayGoogleEvents.map(event => (
                                    <div
                                        key={event.id}
                                        onClick={() => setSelectedGoogleEvent(event)}
                                        className="group p-3 rounded-xl border-l-4 border-l-blue-500 cursor-pointer transition-all bg-blue-50 dark:bg-blue-500/10 hover:shadow-md hover:bg-blue-100 dark:hover:bg-blue-500/20"
                                    >
                                        <div className="flex items-start gap-3">
                                            {/* Google Icon */}
                                            <div className="mt-0.5 flex-shrink-0 w-5 h-5 rounded-full bg-blue-500 flex items-center justify-center">
                                                <span className="text-white text-[10px] font-bold">G</span>
                                            </div>
                                            
                                            {/* Event Content */}
                                            <div className="flex-1 min-w-0">
                                                <h4 className="font-semibold text-sm text-slate-800 dark:text-slate-100">{event.title}</h4>
                                                <div className="flex items-center gap-3 text-xs text-blue-600 dark:text-blue-400 mt-1">
                                                    <span className="flex items-center gap-1">
                                                        <Clock size={10} />
                                                        {formatEventTime(event)}
                                                    </span>
                                                    {event.location && (
                                                        <span className="flex items-center gap-1 truncate">
                                                            <MapPin size={10} />
                                                            {event.location}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                            
                                            <ExternalLink size={14} className="text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity" />
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="p-4 border-t border-slate-200 dark:border-white/5 bg-white/50 dark:bg-slate-900/50">
                                <Button
                                    className="w-full"
                                    onClick={() => {
                                        onDateClick(selectedDate);
                                        setSelectedDate(null);
                                    }}
                                >
                                    <Plus size={16} className="mr-2" /> Add Activity for this Day
                                </Button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Google Event Detail Modal */}
                {selectedGoogleEvent && (
                    <div className="absolute inset-0 z-30 flex items-center justify-center p-4">
                        <div className="absolute inset-0 bg-black/60 dark:bg-black/60 backdrop-blur-sm" onClick={() => setSelectedGoogleEvent(null)} />
                        <div className="relative w-full max-w-md glass rounded-2xl shadow-2xl overflow-hidden animate-scale-in flex flex-col max-h-[70vh]">
                            {/* Header */}
                            <div className="p-4 border-b border-blue-200 dark:border-blue-500/20 bg-blue-50 dark:bg-blue-500/10 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full bg-blue-500 flex items-center justify-center">
                                        <span className="text-white text-lg font-bold">G</span>
                                    </div>
                                    <div>
                                        <p className="text-xs font-medium text-blue-600 dark:text-blue-400 uppercase tracking-wider">Google Calendar</p>
                                        <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100">{selectedGoogleEvent.title}</h3>
                                    </div>
                                </div>
                                <button onClick={() => setSelectedGoogleEvent(null)} className="p-1 rounded-full hover:bg-black/5 dark:hover:bg-white/5 text-slate-400 hover:text-slate-800 dark:hover:text-white" aria-label="Close">
                                    <X size={20} />
                                </button>
                            </div>

                            {/* Content */}
                            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                                {/* Time */}
                                <div className="flex items-start gap-3">
                                    <Clock size={18} className="text-blue-500 mt-0.5" />
                                    <div>
                                        <p className="text-xs font-medium text-slate-500 uppercase tracking-wider">Time</p>
                                        <p className="text-sm text-slate-800 dark:text-slate-100">{formatEventTime(selectedGoogleEvent)}</p>
                                        <p className="text-xs text-slate-500">
                                            {new Date(selectedGoogleEvent.start).toLocaleDateString(undefined, { 
                                                weekday: 'long', 
                                                year: 'numeric', 
                                                month: 'long', 
                                                day: 'numeric' 
                                            })}
                                        </p>
                                    </div>
                                </div>

                                {/* Location */}
                                {selectedGoogleEvent.location && (
                                    <div className="flex items-start gap-3">
                                        <MapPin size={18} className="text-blue-500 mt-0.5" />
                                        <div>
                                            <p className="text-xs font-medium text-slate-500 uppercase tracking-wider">Location</p>
                                            <p className="text-sm text-slate-800 dark:text-slate-100">{selectedGoogleEvent.location}</p>
                                        </div>
                                    </div>
                                )}

                                {/* Description */}
                                {selectedGoogleEvent.description && (
                                    <div className="p-3 bg-slate-50 dark:bg-white/5 rounded-xl">
                                        <p className="text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Description</p>
                                        <p className="text-sm text-slate-700 dark:text-slate-300 whitespace-pre-wrap">{selectedGoogleEvent.description}</p>
                                    </div>
                                )}
                            </div>

                            {/* Footer */}
                            <div className="p-4 border-t border-slate-200 dark:border-white/5 bg-white/50 dark:bg-slate-900/50">
                                <a
                                    href={selectedGoogleEvent.htmlLink}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="flex items-center justify-center gap-2 w-full px-4 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-medium transition-colors"
                                >
                                    <ExternalLink size={16} />
                                    View in Google Calendar
                                </a>
                            </div>
                        </div>
                    </div>
                )}

                {/* Drag Overlay */}
                <DragOverlay>
                    {activeTask && (
                        <div className={`px-3 py-2 rounded-lg shadow-lg border-l-4 ${TYPE_COLORS[activeTask.type]}`}>
                            <span className="text-sm font-medium">{activeTask.title}</span>
                        </div>
                    )}
                </DragOverlay>
            </div>
        </DndContext>
    );
};

export default React.memo(CalendarView);

import React, { useState } from 'react';
import { format, addDays } from 'date-fns';
import { Calendar as CalendarIcon, Clock, ArrowRight, Check, X } from 'lucide-react';
import Button from './Button';
import { DayPlan } from '../types';

interface CloneDayModalProps {
  isOpen: boolean;
  onClose: () => void;
  onClone: (targetDate: Date, adjustTime: boolean, timeOffsetMinutes: number) => void;
  sourceDate: Date;
  taskCount: number;
  selectedTaskCount: number;
}

const CloneDayModal: React.FC<CloneDayModalProps> = ({
  isOpen,
  onClose,
  onClone,
  sourceDate,
  taskCount,
  selectedTaskCount,
}) => {
  const [targetDate, setTargetDate] = useState<string>(
    format(addDays(sourceDate, 1), 'yyyy-MM-dd')
  );
  const [adjustTime, setAdjustTime] = useState(false);
  const [timeOffset, setTimeOffset] = useState(0); // Minutes

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onClone(new Date(targetDate), adjustTime, timeOffset);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl w-full max-w-md border border-slate-200 dark:border-white/10 overflow-hidden">
        {/* Header */}
        <div className="p-6 border-b border-slate-200 dark:border-white/10">
          <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <CalendarIcon className="text-brand-500" />
            Clone Day Plan
          </h2>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
            {selectedTaskCount > 0 
              ? `Copy ${selectedTaskCount} selected tasks to another day`
              : `Copy all ${taskCount} tasks from ${format(sourceDate, 'MMMM d')} to another day`
            }
          </p>
        </div>

        {/* content */}
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          {/* Target Date */}
          <div className="space-y-2">
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">
              Target Date
            </label>
            <input
              type="date"
              required
              value={targetDate}
              onChange={(e) => setTargetDate(e.target.value)}
              className="w-full px-4 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-500 text-slate-800 dark:text-slate-100"
            />
          </div>

          {/* Time Adjustment */}
          <div className="p-4 bg-slate-50 dark:bg-slate-900/50 rounded-xl border border-slate-200 dark:border-white/5 space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Clock size={18} className="text-slate-400" />
                <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                  Shift Times
                </span>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={adjustTime}
                  onChange={(e) => setAdjustTime(e.target.checked)}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-brand-300 dark:peer-focus:ring-brand-800 rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-slate-600 peer-checked:bg-brand-600"></div>
              </label>
            </div>

            {adjustTime && (
              <div className="animate-fade-in">
                <label className="block text-xs text-slate-500 dark:text-slate-400 mb-1.5">
                  Shift tasks by (minutes)
                </label>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    value={timeOffset}
                    onChange={(e) => setTimeOffset(Number(e.target.value))}
                    className="flex-1 px-3 py-1.5 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 text-sm"
                    placeholder="0"
                  />
                  <div className="text-xs text-slate-400">
                    Use negative for earlier
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Actions */}
          <div className="flex items-center gap-3 pt-2">
            <Button
              type="button"
              variant="secondary"
              className="flex-1"
              onClick={onClose}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="primary"
              className="flex-1"
            >
              <ArrowRight size={18} />
              Clone Plan
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CloneDayModal;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, UserPlus, UserMinus, Search, Check, X, 
  MoreVertical, Shield, User, Crown, Plus, 
  ChevronDown, ChevronUp, Trash2, Edit3, Loader2
} from 'lucide-react';
import Button from './Button';
import Input from './Input';
import * as PartnerService from '../services/partnerService';
import type { Partnership, Team, TeamMember, UserSearchResult } from '../types';

interface CollaborationSettingsProps {
  currentUserId?: string;
  currentUserEmail?: string;
}

export const CollaborationSettings: React.FC<CollaborationSettingsProps> = ({
  currentUserId,
  currentUserEmail
}) => {
  // Partner State
  const [partnerships, setPartnerships] = useState<Partnership[]>([]);
  const [isLoadingPartners, setIsLoadingPartners] = useState(true);
  
  // Team State
  const [teams, setTeams] = useState<Team[]>([]);
  const [teamInvites, setTeamInvites] = useState<Team[]>([]);
  const [isLoadingTeams, setIsLoadingTeams] = useState(true);
  const [expandedTeam, setExpandedTeam] = useState<string | null>(null);
  const [teamMembers, setTeamMembers] = useState<Record<string, TeamMember[]>>({});
  
  // User Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<UserSearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showSearchDropdown, setShowSearchDropdown] = useState(false);
  const [searchContext, setSearchContext] = useState<'partner' | { type: 'team'; teamId: string } | null>(null);
  const searchRef = useRef<HTMLDivElement>(null);
  
  // Create Team Modal
  const [showCreateTeam, setShowCreateTeam] = useState(false);
  const [newTeamName, setNewTeamName] = useState('');
  const [newTeamDesc, setNewTeamDesc] = useState('');
  const [isCreatingTeam, setIsCreatingTeam] = useState(false);

  // Load data on mount
  useEffect(() => {
    loadPartnerships();
    loadTeams();
  }, []);

  // Click outside to close search dropdown
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSearchDropdown(false);
        setSearchContext(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Debounced search
  useEffect(() => {
    if (!searchQuery || searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    const timer = setTimeout(async () => {
      setIsSearching(true);
      const results = await PartnerService.searchUsersByEmail(searchQuery);
      
      // Filter out existing partners if searching for partners
      if (searchContext === 'partner') {
        const partnerIds = new Set(partnerships.map(p => p.partnerId));
        setSearchResults(results.filter(r => !partnerIds.has(r.id)));
      } else if (searchContext && typeof searchContext === 'object' && searchContext.type === 'team') {
        // Filter out existing team members
        const memberIds = new Set((teamMembers[searchContext.teamId] || []).map(m => m.userId));
        setSearchResults(results.filter(r => !memberIds.has(r.id)));
      } else {
        setSearchResults(results);
      }
      setIsSearching(false);
    }, 300);

    return () => clearTimeout(timer);
  }, [searchQuery, searchContext, partnerships, teamMembers]);

  const loadPartnerships = async () => {
    setIsLoadingPartners(true);
    const data = await PartnerService.getPartnerships();
    setPartnerships(data);
    setIsLoadingPartners(false);
  };

  const loadTeams = async () => {
    setIsLoadingTeams(true);
    const [teamsData, invitesData] = await Promise.all([
      PartnerService.getTeams(),
      PartnerService.getTeamInvites()
    ]);
    setTeams(teamsData);
    setTeamInvites(invitesData);
    setIsLoadingTeams(false);
  };

  const loadTeamMembers = async (teamId: string) => {
    const members = await PartnerService.getTeamMembers(teamId);
    setTeamMembers(prev => ({ ...prev, [teamId]: members }));
  };

  // Partner Actions
  const handleAddPartner = async (user: UserSearchResult) => {
    const success = await PartnerService.sendPartnerRequest(user.id);
    if (success) {
      await loadPartnerships();
      setSearchQuery('');
      setShowSearchDropdown(false);
      setSearchContext(null);
    }
  };

  const handleAcceptPartner = async (partnershipId: string) => {
    const success = await PartnerService.acceptPartnerRequest(partnershipId);
    if (success) await loadPartnerships();
  };

  const handleRejectPartner = async (partnershipId: string) => {
    const success = await PartnerService.rejectPartnerRequest(partnershipId);
    if (success) await loadPartnerships();
  };

  const handleRemovePartner = async (partnershipId: string) => {
    const success = await PartnerService.removePartner(partnershipId);
    if (success) await loadPartnerships();
  };

  // Team Actions
  const handleCreateTeam = async () => {
    if (!newTeamName.trim()) return;
    setIsCreatingTeam(true);
    const team = await PartnerService.createTeam(newTeamName.trim(), newTeamDesc.trim() || undefined);
    if (team) {
      setTeams(prev => [...prev, team]);
      setNewTeamName('');
      setNewTeamDesc('');
      setShowCreateTeam(false);
    }
    setIsCreatingTeam(false);
  };

  const handleDeleteTeam = async (teamId: string) => {
    const success = await PartnerService.deleteTeam(teamId);
    if (success) {
      setTeams(prev => prev.filter(t => t.id !== teamId));
      if (expandedTeam === teamId) setExpandedTeam(null);
    }
  };

  const handleToggleTeam = async (teamId: string) => {
    if (expandedTeam === teamId) {
      setExpandedTeam(null);
    } else {
      setExpandedTeam(teamId);
      if (!teamMembers[teamId]) {
        await loadTeamMembers(teamId);
      }
    }
  };

  const handleAddTeamMember = async (teamId: string, user: UserSearchResult) => {
    const success = await PartnerService.addTeamMember(teamId, user.id);
    if (success) {
      await loadTeamMembers(teamId);
      await loadTeams();
      setSearchQuery('');
      setShowSearchDropdown(false);
      setSearchContext(null);
    }
  };

  const handleRemoveTeamMember = async (teamId: string, memberId: string) => {
    const success = await PartnerService.removeTeamMember(memberId);
    if (success) {
      await loadTeamMembers(teamId);
      await loadTeams();
    }
  };

  const handleUpdateMemberRole = async (memberId: string, role: 'admin' | 'member', teamId: string) => {
    const success = await PartnerService.updateMemberRole(memberId, role);
    if (success) await loadTeamMembers(teamId);
  };

  const handleAcceptTeamInvite = async (teamId: string) => {
    const success = await PartnerService.acceptTeamInvite(teamId);
    if (success) {
      await loadTeams();
    }
  };

  const handleRejectTeamInvite = async (teamId: string) => {
    const success = await PartnerService.rejectTeamInvite(teamId);
    if (success) {
      setTeamInvites(prev => prev.filter(t => t.id !== teamId));
    }
  };

  // Render User Search Dropdown
  const renderSearchDropdown = (onSelect: (user: UserSearchResult) => void) => (
    <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-white/10 shadow-xl z-50 max-h-64 overflow-y-auto">
      {isSearching ? (
        <div className="p-4 flex items-center justify-center text-slate-400">
          <Loader2 className="animate-spin mr-2" size={16} />
          Searching...
        </div>
      ) : searchResults.length === 0 ? (
        <div className="p-4 text-center text-slate-400 text-sm">
          {searchQuery.length < 2 ? 'Type at least 2 characters' : 'No users found'}
        </div>
      ) : (
        searchResults.map(user => (
          <button
            key={user.id}
            onClick={() => onSelect(user)}
            className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors text-left"
          >
            <div className="w-8 h-8 shrink-0 rounded-full bg-brand-500/10 flex items-center justify-center text-brand-500">
              <User size={16} />
            </div>
            <div className="flex-1 min-w-0 overflow-hidden">
              <p className="text-sm font-medium text-slate-800 dark:text-slate-200 truncate">
                {user.fullName || user.email}
              </p>
              <p className="text-xs text-slate-500 truncate">{user.email}</p>
            </div>
            <span className="shrink-0 text-xs font-medium text-brand-500 bg-brand-500/10 px-2 py-1 rounded-lg">
              Connect
            </span>
          </button>
        ))
      )}
    </div>
  );

  return (
    <div className="col-span-1 lg:col-span-2 space-y-6">
      {/* Section Header */}
      <div className="flex items-center gap-2 text-xl font-bold text-slate-800 dark:text-slate-200">
        <Users className="text-brand-500" />
        <h3>Collaboration</h3>
      </div>

      {/* Partners Section */}
      <div className="bg-white/40 dark:bg-dark-surface/30 border border-slate-200 dark:border-white/5 rounded-2xl p-6 backdrop-blur-sm">
        <div className="flex items-center justify-between mb-4">
          <h4 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <UserPlus size={20} className="text-brand-500" />
            Partners
          </h4>
        </div>
        
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
          Add partners to share specific tasks with them. Search by email to find registered users.
        </p>

        {/* Add Partner Search */}
        <div className="relative mb-4" ref={searchRef}>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input
              type="text"
              placeholder="Search by email..."
              value={searchContext === 'partner' ? searchQuery : ''}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setSearchContext('partner');
                setShowSearchDropdown(true);
              }}
              onFocus={() => {
                setSearchContext('partner');
                setShowSearchDropdown(true);
              }}
              className="w-full bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-dark-border rounded-xl pl-10 pr-4 py-2.5 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 transition-all placeholder-slate-400 dark:placeholder-slate-500"
            />
          </div>
          {showSearchDropdown && searchContext === 'partner' && renderSearchDropdown(handleAddPartner)}
        </div>

        {/* Partners List */}
        {isLoadingPartners ? (
          <div className="py-8 flex items-center justify-center text-slate-400">
            <Loader2 className="animate-spin mr-2" size={20} />
            Loading partners...
          </div>
        ) : partnerships.length === 0 ? (
          <div className="py-8 text-center text-slate-400 text-sm">
            No partners yet. Search by email to add your first partner.
          </div>
        ) : (
          <div className="space-y-2">
            {partnerships.map(p => (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-white/10"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-brand-500/10 flex items-center justify-center text-brand-500">
                    <User size={20} />
                  </div>
                  <div>
                    <p className="font-medium text-slate-800 dark:text-slate-200">
                      {p.partnerName || p.partnerEmail}
                    </p>
                    <p className="text-xs text-slate-500">{p.partnerEmail}</p>
                  </div>
                </div>
                
                <div className="flex items-center gap-2">
                  {p.status === 'pending' ? (
                    p.isIncoming ? (
                      <>
                        <button 
                          onClick={() => handleAcceptPartner(p.id)}
                          className="p-1.5 rounded-lg bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/20 dark:hover:bg-emerald-500/30 transition-colors"
                          title="Accept"
                          aria-label="Accept partner request"
                        >
                          <Check size={16} />
                        </button>
                        <button 
                          onClick={() => handleRejectPartner(p.id)}
                          className="p-1.5 rounded-lg bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 hover:bg-red-500/20 dark:hover:bg-red-500/30 transition-colors"
                          title="Reject"
                          aria-label="Reject partner request"
                        >
                          <X size={16} />
                        </button>
                      </>
                    ) : (
                      <span className="text-xs px-2 py-1 rounded-full bg-yellow-500/10 text-yellow-600 dark:text-yellow-400 font-medium">
                        Pending
                      </span>
                    )
                  ) : (
                    <>
                      <span className="text-xs px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 font-medium">
                        Connected
                      </span>
                      <button 
                        onClick={() => handleRemovePartner(p.id)}
                        className="p-1.5 rounded-lg text-slate-400 hover:bg-red-500/10 dark:hover:bg-red-500/20 hover:text-red-600 dark:hover:text-red-400 transition-colors"
                        title="Remove"
                        aria-label="Remove partner"
                      >
                        <UserMinus size={16} />
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Teams Section */}
      <div className="bg-white/40 dark:bg-dark-surface/30 border border-slate-200 dark:border-white/5 rounded-2xl p-6 backdrop-blur-sm">
        <div className="flex items-center justify-between mb-4">
          <h4 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <Users size={20} className="text-brand-500" />
            Teams
          </h4>
          <Button size="sm" onClick={() => setShowCreateTeam(true)}>
            <Plus size={16} className="mr-1" /> Create Team
          </Button>
        </div>
        
        <p className="text-sm text-slate-500 dark:text-slate-400 mb-4">
          Create teams to collaborate with multiple people on shared tasks.
        </p>

        {/* Team Invites */}
        {teamInvites.length > 0 && (
          <div className="mb-4 p-3 rounded-xl bg-brand-500/5 border border-brand-500/20">
            <p className="text-sm font-medium text-brand-500 mb-2">Team Invites</p>
            <div className="space-y-2">
              {teamInvites.map(team => (
                <div 
                  key={team.id} 
                  className="flex items-center justify-between p-2 rounded-lg bg-white/50 dark:bg-black/20"
                >
                  <span className="text-sm font-medium text-slate-800 dark:text-slate-200">{team.name}</span>
                  <div className="flex gap-2">
                    <button 
                      onClick={() => handleAcceptTeamInvite(team.id)}
                      className="p-1.5 rounded-lg bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/20 dark:hover:bg-emerald-500/30"
                      aria-label="Accept team invite"
                    >
                      <Check size={14} />
                    </button>
                    <button 
                      onClick={() => handleRejectTeamInvite(team.id)}
                      className="p-1.5 rounded-lg bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 hover:bg-red-500/20 dark:hover:bg-red-500/30"
                      aria-label="Reject team invite"
                    >
                      <X size={14} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Create Team Modal */}
        {showCreateTeam && (
          <div className="mb-4 p-4 rounded-xl bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10">
            <h5 className="font-medium text-slate-800 dark:text-slate-200 mb-3">Create New Team</h5>
            <Input
              label="Team Name"
              value={newTeamName}
              onChange={(e) => setNewTeamName(e.target.value)}
              placeholder="e.g., Work Projects"
            />
            <div className="mt-3">
              <Input
                label="Description (optional)"
                value={newTeamDesc}
                onChange={(e) => setNewTeamDesc(e.target.value)}
                placeholder="Brief team description"
              />
            </div>
            <div className="flex gap-2 mt-4">
              <Button size="sm" onClick={handleCreateTeam} disabled={!newTeamName.trim() || isCreatingTeam}>
                {isCreatingTeam ? <Loader2 className="animate-spin mr-1" size={14} /> : null}
                Create
              </Button>
              <Button size="sm" variant="ghost" onClick={() => setShowCreateTeam(false)}>
                Cancel
              </Button>
            </div>
          </div>
        )}

        {/* Teams List */}
        {isLoadingTeams ? (
          <div className="py-8 flex items-center justify-center text-slate-400">
            <Loader2 className="animate-spin mr-2" size={20} />
            Loading teams...
          </div>
        ) : teams.length === 0 ? (
          <div className="py-8 text-center text-slate-400 text-sm">
            No teams yet. Create a team to start collaborating.
          </div>
        ) : (
          <div className="space-y-3">
            {teams.map(team => (
              <div 
                key={team.id} 
                className="rounded-xl bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-white/10 overflow-hidden"
              >
                {/* Team Header */}
                <div 
                  className="flex items-center justify-between p-4 cursor-pointer hover:bg-slate-100 dark:hover:bg-white/5 transition-colors"
                  onClick={() => handleToggleTeam(team.id)}
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-brand-500/10 flex items-center justify-center text-brand-500">
                      <Users size={20} />
                    </div>
                    <div>
                      <p className="font-medium text-slate-800 dark:text-slate-200 flex items-center gap-2">
                        {team.name}
                        {team.isOwner && (
                          <Crown size={14} className="text-yellow-500" title="You own this team" />
                        )}
                      </p>
                      <p className="text-xs text-slate-500">{team.memberCount} member{team.memberCount !== 1 ? 's' : ''}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    {team.isOwner && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); handleDeleteTeam(team.id); }}
                        className="p-1.5 rounded-lg text-slate-400 hover:bg-red-500/10 dark:hover:bg-red-500/20 hover:text-red-600 dark:hover:text-red-400 transition-colors"
                        title="Delete Team"
                        aria-label="Delete team"
                      >
                        <Trash2 size={16} />
                      </button>
                    )}
                    {expandedTeam === team.id ? (
                      <ChevronUp size={18} className="text-slate-400" />
                    ) : (
                      <ChevronDown size={18} className="text-slate-400" />
                    )}
                  </div>
                </div>

                {/* Expanded Team Content */}
                {expandedTeam === team.id && (
                  <div className="px-4 pb-4 border-t border-slate-200 dark:border-white/5">
                    {team.description && (
                      <p className="text-sm text-slate-500 dark:text-slate-400 py-3">
                        {team.description}
                      </p>
                    )}

                    {/* Add Member (only for owners/admins) */}
                    {team.isOwner && (
                      <div className="relative py-3" ref={searchContext && typeof searchContext === 'object' && searchContext.teamId === team.id ? searchRef : undefined}>
                        <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                          <input
                            type="text"
                            placeholder="Add member by email..."
                            value={searchContext && typeof searchContext === 'object' && searchContext.teamId === team.id ? searchQuery : ''}
                            onChange={(e) => {
                              setSearchQuery(e.target.value);
                              setSearchContext({ type: 'team', teamId: team.id });
                              setShowSearchDropdown(true);
                            }}
                            onFocus={() => {
                              setSearchContext({ type: 'team', teamId: team.id });
                              setShowSearchDropdown(true);
                            }}
                            className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-dark-border rounded-lg pl-9 pr-3 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 placeholder-slate-400"
                          />
                        </div>
                        {showSearchDropdown && searchContext && typeof searchContext === 'object' && searchContext.teamId === team.id && 
                          renderSearchDropdown((user) => handleAddTeamMember(team.id, user))
                        }
                      </div>
                    )}

                    {/* Members List */}
                    <div className="space-y-2 pt-2">
                      <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">Members</p>
                      {!teamMembers[team.id] ? (
                        <div className="py-4 text-center text-slate-400 text-sm">
                          <Loader2 className="animate-spin inline mr-2" size={14} />
                          Loading members...
                        </div>
                      ) : teamMembers[team.id].length === 0 ? (
                        <div className="py-4 text-center text-slate-400 text-sm">
                          No members yet
                        </div>
                      ) : (
                        teamMembers[team.id].map(member => (
                          <div 
                            key={member.id}
                            className="flex items-center justify-between p-2 rounded-lg bg-white/50 dark:bg-slate-800/50"
                          >
                            <div className="flex items-center gap-2">
                              <div className="w-7 h-7 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center">
                                <User size={14} className="text-slate-500" />
                              </div>
                              <div>
                                <p className="text-sm font-medium text-slate-800 dark:text-slate-200">
                                  {member.name || member.email}
                                </p>
                                {member.name && (
                                  <p className="text-xs text-slate-500">{member.email}</p>
                                )}
                              </div>
                            </div>
                            <div className="flex items-center gap-2">
                              {member.status === 'pending' ? (
                                <span className="text-xs px-2 py-0.5 rounded-full bg-yellow-500/10 text-yellow-600 dark:text-yellow-400">
                                  Pending
                                </span>
                              ) : (
                                <span className={`text-xs px-2 py-0.5 rounded-full flex items-center gap-1 ${
                                  member.role === 'admin' 
                                    ? 'bg-purple-500/10 text-purple-600 dark:text-purple-400' 
                                    : 'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400'
                                }`}>
                                  {member.role === 'admin' && <Shield size={10} />}
                                  {member.role}
                                </span>
                              )}
                              {team.isOwner && (
                                <button 
                                  onClick={() => handleRemoveTeamMember(team.id, member.id)}
                                  className="p-1 rounded text-slate-400 hover:text-red-500 hover:bg-red-500/10 transition-colors"
                                  title="Remove member"
                                  aria-label="Remove team member"
                                >
                                  <X size={14} />
                                </button>
                              )}
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default React.memo(CollaborationSettings);

import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import Button from './Button';
import Input from './Input';
import { AlertTriangle, Loader2, Eye, EyeOff, Trash2, X, CheckCircle2 } from 'lucide-react';

interface DeleteAccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onDeleted: () => void;
  userEmail: string;
}

const DeleteAccountModal: React.FC<DeleteAccountModalProps> = ({ 
  isOpen, 
  onClose, 
  onDeleted,
  userEmail 
}) => {
  const [password, setPassword] = useState('');
  const [confirmText, setConfirmText] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDeleted, setIsDeleted] = useState(false);

  const handleDelete = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validate confirmation text
    if (confirmText !== 'DELETE') {
      setError('Please type DELETE to confirm.');
      return;
    }

    // Validate password
    if (!password) {
      setError('Please enter your password.');
      return;
    }

    setIsLoading(true);

    try {
      const { data, error: fnError } = await supabase.functions.invoke('account-deletion', {
        body: { action: 'delete-with-password', password }
      });

      if (fnError) {
        throw new Error(fnError.message || 'Failed to delete account');
      }

      if (!data?.success) {
        throw new Error(data?.error || 'Failed to delete account');
      }

      // Success - show success state
      setIsDeleted(true);
      
      // Sign out and notify parent
      setTimeout(async () => {
        await supabase.auth.signOut();
        onDeleted();
      }, 2000);

    } catch (err: any) {
      console.error('Delete account error:', err);
      setError(err.message || 'Failed to delete account. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading && !isDeleted) {
      setPassword('');
      setConfirmText('');
      setError('');
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in">
      <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-2xl shadow-2xl overflow-hidden animate-scale-in border border-slate-200 dark:border-white/10">
        
        {/* Header */}
        <div className="bg-gradient-to-r from-red-500 to-red-600 p-5 text-white">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <AlertTriangle size={24} />
              <div>
                <h2 className="text-xl font-bold">Delete Account</h2>
                <p className="text-red-100 text-sm">This action is permanent</p>
              </div>
            </div>
            {!isLoading && !isDeleted && (
              <button
                onClick={handleClose}
                className="p-2 hover:bg-white/20 rounded-lg transition-colors"
                aria-label="Close modal"
              >
                <X size={20} />
              </button>
            )}
          </div>
        </div>

        {/* Content */}
        <div className="p-6">
          {isDeleted ? (
            <div className="text-center py-6">
              <CheckCircle2 size={64} className="text-green-500 mx-auto mb-4" />
              <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-2">
                Account Deleted
              </h3>
              <p className="text-slate-600 dark:text-slate-300">
                Your account has been permanently deleted. Redirecting...
              </p>
            </div>
          ) : (
            <form onSubmit={handleDelete} className="space-y-5">
              {/* Warning Box */}
              <div className="bg-red-50 dark:bg-red-500/10 rounded-xl p-4 border border-red-200 dark:border-red-500/20">
                <p className="text-sm text-red-600/80 dark:text-red-300/80 space-y-1">
                  <strong className="block text-red-700 dark:text-red-400">ΓÜá∩╕Å Warning:</strong>
                  ΓÇó All your tasks, events, and reminders will be deleted<br />
                  ΓÇó All your budget data will be erased<br />
                  ΓÇó All settings and partnerships will be removed<br />
                  ΓÇó <strong>This cannot be undone</strong>
                </p>
              </div>

              {/* Email Display */}
              <div className="bg-slate-100 dark:bg-slate-800 rounded-xl p-3 text-center">
                <p className="text-xs text-slate-500 mb-1">Deleting account for</p>
                <p className="font-medium text-slate-800 dark:text-white">{userEmail}</p>
              </div>

              {/* Password Input */}
              <div className="relative">
                <Input
                  label="Enter your password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                  required
                  className="pr-12"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-[35px] text-slate-400 hover:text-slate-600 transition-colors p-1 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>

              {/* Confirmation Text */}
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                  Type <span className="font-bold text-red-500">DELETE</span> to confirm
                </label>
                <input
                  type="text"
                  value={confirmText}
                  onChange={(e) => setConfirmText(e.target.value.toUpperCase())}
                  placeholder="Type DELETE"
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-2.5 text-slate-800 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-red-500/50"
                  required
                />
              </div>

              {/* Error Message */}
              {error && (
                <div
                  role="alert"
                  aria-live="assertive"
                  className="p-3 rounded-lg bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 text-red-600 dark:text-red-400 text-sm"
                >
                  {error}
                </div>
              )}

              {/* Action Buttons */}
              <div className="flex gap-3 pt-2">
                <Button
                  type="button"
                  variant="secondary"
                  onClick={handleClose}
                  className="flex-1"
                  disabled={isLoading}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  variant="danger"
                  className="flex-1 flex items-center justify-center gap-2"
                  disabled={isLoading || confirmText !== 'DELETE' || !password}
                >
                  {isLoading ? (
                    <Loader2 className="animate-spin" size={18} />
                  ) : (
                    <>
                      <Trash2 size={16} />
                      Delete Forever
                    </>
                  )}
                </Button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default DeleteAccountModal;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw } from 'lucide-react';
import Button from './Button';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

/**
 * React Error Boundary component for graceful error handling.
 * Catches JavaScript errors in child component tree and displays
 * a fallback UI instead of crashing the whole app.
 */
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  public static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    (this as any).setState({ errorInfo });
  }

  private handleReload = (): void => {
    window.location.reload();
  };

  private handleReset = (): void => {
    (this as any).setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  public render(): ReactNode {
    if ((this as any).state.hasError) {
      // Custom fallback UI
      if ((this as any).props.fallback) {
        return (this as any).props.fallback;
      }

      // Default error UI
      return (
        <div className="min-h-[400px] flex items-center justify-center p-8">
          <div className="max-w-md w-full text-center">
            <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-red-500/10 flex items-center justify-center">
              <AlertCircle className="text-red-500" size={32} />
            </div>
            
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 mb-2">
              Something went wrong
            </h2>
            
            <p className="text-slate-500 dark:text-slate-400 mb-6">
              We're sorry, but something unexpected happened. Please try refreshing the page.
            </p>

            {import.meta.env.DEV && (this as any).state.error && (
              <details className="mb-6 text-left bg-slate-100 dark:bg-slate-800 rounded-xl p-4 text-sm">
                <summary className="cursor-pointer font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Error Details (Development Only)
                </summary>
                <pre className="whitespace-pre-wrap text-red-600 dark:text-red-400 overflow-auto max-h-40 font-mono text-xs">
                  {(this as any).state.error.toString()}
                  {(this as any).state.errorInfo?.componentStack}
                </pre>
              </details>
            )}

            <div className="flex gap-3 justify-center">
              <Button variant="secondary" onClick={this.handleReset}>
                Try Again
              </Button>
              <Button variant="primary" onClick={this.handleReload}>
                <RefreshCw size={16} className="mr-2" />
                Reload Page
              </Button>
            </div>
          </div>
        </div>
      );
    }

    return (this as any).props.children;
  }
}

export default ErrorBoundary;

import React, { useCallback, useMemo } from 'react';
import {
  ReactFlow,
  Node,
  Edge,
  Background,
  Controls,
  MiniMap,
  ConnectionMode,
  useNodesState,
  useEdgesState,
  Connection,
  BackgroundVariant,
  Panel,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { Task, TaskLink } from '../types';
import TaskNode from './TaskNode';
import DeletableEdge from './DeletableEdge';

interface FlowchartCanvasProps {
  tasks: Task[];
  links: TaskLink[];
  layout: { taskId: string; x: number; y: number }[];
  onTaskMove: (taskId: string, x: number, y: number) => void;
  onLinkCreate: (fromTaskId: string, toTaskId: string, sourceHandle?: string, targetHandle?: string) => void;
  onLinkDelete: (linkId: string) => void;
  onTaskClick: (task: Task) => void;
  onAutoArrange?: () => void;
  onSelectionChange?: (selectedTaskIds: string[]) => void;
  onAddTaskBetween?: (sourceTaskId: string, targetTaskId: string) => void;
  onCreateFromHandle?: (taskId: string, position: 'top' | 'bottom' | 'left' | 'right') => void;
}

const nodeTypes = {
  taskNode: TaskNode,
};

const edgeTypes = {
  deletable: DeletableEdge,
};

const FlowchartCanvas: React.FC<FlowchartCanvasProps> = ({
  tasks,
  links,
  layout,
  onTaskMove,
  onLinkCreate,
  onLinkDelete,
  onTaskClick,
  onAutoArrange,
  onSelectionChange,
  onAddTaskBetween,
  onCreateFromHandle,
}) => {
  // Handle selection change
  const handleSelectionChange = useCallback(({ nodes }: { nodes: Node[] }) => {
    if (onSelectionChange) {
      onSelectionChange(nodes.map(node => node.id));
    }
  }, [onSelectionChange]);
  
  // Convert tasks to React Flow nodes
  const initialNodes: Node[] = useMemo(() => {
    return tasks.map(task => {
      const position = layout.find(l => l.taskId === task.id);
      return {
        id: task.id,
        type: 'taskNode',
        position: position ? { x: position.x, y: position.y } : { x: Math.random() * 500, y: Math.random() * 500 },
        data: { 
          task, 
          onClick: () => onTaskClick(task),
          onCreateFromHandle,
        },
      };
    });
  }, [tasks, layout, onTaskClick, onCreateFromHandle]);

  // Convert links to React Flow edges
  const initialEdges: Edge[] = useMemo(() => {
    return links.map(link => {
      // Find the source and target tasks to calculate time gap
      const sourceTask = tasks.find(t => t.id === link.fromTaskId);
      const targetTask = tasks.find(t => t.id === link.toTaskId);
      
      let timeGap: number | null = null;
      
      if (sourceTask?.dueDate && targetTask?.dueDate) {
        const sourceStart = new Date(sourceTask.dueDate).getTime();
        const sourceDuration = (sourceTask.duration || 30) * 60 * 1000; // Convert minutes to ms
        const sourceEnd = sourceStart + sourceDuration;
        const targetStart = new Date(targetTask.dueDate).getTime();
        
        // Time gap in minutes (can be negative if tasks overlap)
        timeGap = Math.round((targetStart - sourceEnd) / (60 * 1000));
      }

      return {
        id: link.id,
        source: link.fromTaskId,
        target: link.toTaskId,
        sourceHandle: link.sourceHandle || 'bottom',
        targetHandle: link.targetHandle || 'top',
        animated: link.linkType === 'flow',
        deletable: true,
        selectable: true,
        type: 'deletable',
        data: {
          onDelete: onLinkDelete,
          onAddTask: onAddTaskBetween,
          timeGap,
        },
        style: {
          stroke: link.linkType === 'flow' ? '#6366f1' : '#ef4444',
          strokeWidth: 3,
          cursor: 'pointer',
        },
        markerEnd: {
          type: 'arrowclosed' as const,
          color: link.linkType === 'flow' ? '#6366f1' : '#ef4444',
        },
      };
    });
  }, [links, onLinkDelete, onAddTaskBetween, tasks]);

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  // Update nodes when tasks or layout change
  React.useEffect(() => {
    setNodes(initialNodes);
  }, [initialNodes, setNodes]);

  // Update edges when links change
  React.useEffect(() => {
    setEdges(initialEdges);
  }, [initialEdges, setEdges]);

  // Handle connection creation
  const onConnect = useCallback(
    (connection: Connection) => {
      if (connection.source && connection.target) {
        onLinkCreate(
          connection.source, 
          connection.target,
          connection.sourceHandle || undefined,
          connection.targetHandle || undefined
        );
      }
    },
    [onLinkCreate]
  );

  // Handle node drag end
  const onNodeDragStop = useCallback(
    (event: React.MouseEvent, node: Node) => {
      onTaskMove(node.id, node.position.x, node.position.y);
    },
    [onTaskMove]
  );

  // Handle edge deletion
  const onEdgesDelete = useCallback(
    (edgesToDelete: Edge[]) => {
      edgesToDelete.forEach(edge => {
        onLinkDelete(edge.id);
      });
    },
    [onLinkDelete]
  );

  return (
    <div className="w-full h-full">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        onSelectionChange={handleSelectionChange}
        onNodeDragStop={onNodeDragStop}
        onEdgesDelete={onEdgesDelete}
        nodeTypes={nodeTypes}
        edgeTypes={edgeTypes}
        connectionMode={ConnectionMode.Loose}
        selectionKeyCode="Shift"
        multiSelectionKeyCode="Control"
        edgesUpdatable={true}
        edgesFocusable={true}
        snapToGrid={true}
        snapGrid={[20, 20]}
        defaultEdgeOptions={{
          deletable: true,
          selectable: true,
        }}
        fitView
        fitViewOptions={{
          padding: 0.2,
          maxZoom: 1,
        }}
        proOptions={{ hideAttribution: true }}
        attributionPosition="bottom-left"
        className="bg-slate-50 dark:bg-black/20"
      >
        <Background 
          variant={BackgroundVariant.Dots} 
          gap={16} 
          size={1}
          className="bg-slate-50 dark:bg-black/20"
        />
        <Controls 
          className="!bg-white/80 dark:!bg-slate-800/90 !border !border-slate-200/50 dark:!border-white/10 !rounded-xl !shadow-xl backdrop-blur-sm [&>button]:!bg-transparent [&>button]:!border-none [&>button]:!text-slate-600 dark:[&>button]:!text-slate-300 [&>button:hover]:!bg-slate-100 dark:[&>button:hover]:!bg-slate-700 [&>button]:!rounded-lg [&>button]:!m-1 [&>button>svg]:!fill-current"
          showInteractive={false}
        />
        <MiniMap 
          className="!bg-white/80 dark:!bg-slate-800/90 !border !border-slate-200/50 dark:!border-white/10 !rounded-xl !shadow-xl backdrop-blur-sm"
          nodeColor={(node) => {
            const task = tasks.find(t => t.id === node.id);
            if (!task) return '#94a3b8';
            switch (task.priority) {
              case 'HIGH': return '#ef4444';
              case 'MEDIUM': return '#f59e0b';
              case 'LOW': return '#10b981';
              default: return '#94a3b8';
            }
          }}
          maskColor="rgba(0, 0, 0, 0.2)"
          nodeBorderRadius={8}
        />
        
        {/* Instructions Panel */}
        {tasks.length === 0 && (
          <Panel position="top-center" className="pointer-events-none">
            <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-sm px-6 py-4 rounded-xl shadow-lg border border-slate-200 dark:border-white/10">
              <p className="text-sm text-slate-600 dark:text-slate-400 text-center">
                Drag tasks from the sidebar to create your daily flow
              </p>
            </div>
          </Panel>
        )}
      </ReactFlow>
    </div>
  );
};

export default FlowchartCanvas;

import React, { useState, useEffect, useCallback } from 'react';
import { Task } from '../types';
import { X, Play, Pause, Plus, CheckCircle2, Target } from 'lucide-react';
import Button from './Button';

interface FocusSessionProps {
  task: Task;
  isOpen: boolean;
  onClose: () => void;
  onComplete: (task: Task) => void;
}

const DEFAULT_FOCUS_TIME = 25 * 60; // 25 minutes in seconds

const FocusSession: React.FC<FocusSessionProps> = ({ task, isOpen, onClose, onComplete }) => {
  const [timeRemaining, setTimeRemaining] = useState(DEFAULT_FOCUS_TIME);
  const [isRunning, setIsRunning] = useState(true);
  const [isTimerComplete, setIsTimerComplete] = useState(false);

  // Reset timer when opening with a new task
  useEffect(() => {
    if (isOpen) {
      setTimeRemaining(DEFAULT_FOCUS_TIME);
      setIsRunning(true);
      setIsTimerComplete(false);
    }
  }, [isOpen, task?.id]);

  // Countdown logic
  useEffect(() => {
    if (!isOpen || !isRunning || timeRemaining <= 0) return;

    const interval = setInterval(() => {
      setTimeRemaining(prev => {
        if (prev <= 1) {
          setIsRunning(false);
          setIsTimerComplete(true);
          // Play notification sound (using Web Audio API for a simple beep)
          try {
            const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
            const oscillator = audioContext.createOscillator();
            const gainNode = audioContext.createGain();
            oscillator.connect(gainNode);
            gainNode.connect(audioContext.destination);
            oscillator.frequency.value = 800;
            oscillator.type = 'sine';
            gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.5);
            oscillator.start(audioContext.currentTime);
            oscillator.stop(audioContext.currentTime + 0.5);
          } catch (e) {
            // Audio not supported, silently fail
          }
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isOpen, isRunning, timeRemaining]);

  const togglePause = useCallback(() => {
    if (isTimerComplete) {
      // Restart timer if complete
      setTimeRemaining(DEFAULT_FOCUS_TIME);
      setIsTimerComplete(false);
    }
    setIsRunning(prev => !prev);
  }, [isTimerComplete]);

  const addFiveMinutes = useCallback(() => {
    setTimeRemaining(prev => prev + 5 * 60);
    if (isTimerComplete) {
      setIsTimerComplete(false);
      setIsRunning(true);
    }
  }, [isTimerComplete]);

  const handleComplete = useCallback(() => {
    onComplete(task);
    onClose();
  }, [task, onComplete, onClose]);

  // Format time as MM:SS
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Calculate progress percentage for visual indicator
  const progressPercent = ((DEFAULT_FOCUS_TIME - timeRemaining) / DEFAULT_FOCUS_TIME) * 100;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 bg-slate-900 flex flex-col items-center justify-center p-6 animate-fade-in">
      {/* Exit Button */}
      <button
        onClick={onClose}
        className="absolute top-6 right-6 p-3 rounded-full text-slate-400 hover:text-white hover:bg-white/10 transition-all duration-200"
        aria-label="Exit Focus Mode"
      >
        <X size={28} />
      </button>

      {/* Focus Mode Header */}
      <div className="absolute top-6 left-6 flex items-center gap-3 text-slate-400">
        <Target size={24} className="text-brand-500" />
        <span className="text-sm font-medium uppercase tracking-wider">Focus Mode</span>
      </div>

      {/* Progress Ring Background */}
      <div className="relative mb-8">
        {/* Circular progress indicator */}
        <svg className="w-80 h-80 -rotate-90" viewBox="0 0 100 100">
          <circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke="rgba(255,255,255,0.1)"
            strokeWidth="2"
          />
          <circle
            cx="50"
            cy="50"
            r="45"
            fill="none"
            stroke={isTimerComplete ? '#10b981' : '#6366f1'}
            strokeWidth="3"
            strokeLinecap="round"
            strokeDasharray={`${progressPercent * 2.83} 283`}
            className="transition-all duration-1000"
          />
        </svg>

        {/* Timer Display */}
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span 
            className={`font-mono font-bold tracking-tight transition-all duration-300 ${
              isTimerComplete 
                ? 'text-6xl sm:text-7xl text-emerald-400 animate-pulse' 
                : 'text-7xl sm:text-9xl text-white'
            }`}
          >
            {isTimerComplete ? "Time's Up!" : formatTime(timeRemaining)}
          </span>
          {!isTimerComplete && (
            <span className="text-slate-500 text-sm mt-2">
              {isRunning ? 'Stay focused...' : 'Paused'}
            </span>
          )}
        </div>
      </div>

      {/* Task Info */}
      <div className="text-center max-w-xl mb-12">
        <h1 className="text-2xl sm:text-3xl font-bold text-white mb-3 leading-tight">
          {task.title}
        </h1>
        {task.description && (
          <p className="text-slate-400 text-base sm:text-lg line-clamp-3">
            {task.description}
          </p>
        )}
      </div>

      {/* Controls */}
      <div className="flex flex-wrap items-center justify-center gap-4">
        {/* Pause/Resume Button */}
        <Button
          onClick={togglePause}
          className={`px-8 py-4 text-lg rounded-2xl transition-all duration-200 ${
            isRunning
              ? 'bg-white/10 hover:bg-white/20 text-white border border-white/20'
              : 'bg-brand-500 hover:bg-brand-600 text-white shadow-lg shadow-brand-500/30'
          }`}
        >
          {isRunning ? (
            <>
              <Pause size={22} className="mr-2" /> Pause
            </>
          ) : (
            <>
              <Play size={22} className="mr-2" /> Resume
            </>
          )}
        </Button>

        {/* +5 Minutes Button */}
        <Button
          onClick={addFiveMinutes}
          variant="secondary"
          className="px-6 py-4 text-lg rounded-2xl bg-white/5 hover:bg-white/10 text-slate-300 border border-white/10"
        >
          <Plus size={20} className="mr-2" /> 5 min
        </Button>

        {/* Complete Task Button */}
        <Button
          onClick={handleComplete}
          className="px-8 py-4 text-lg rounded-2xl bg-emerald-500 hover:bg-emerald-600 text-white shadow-lg shadow-emerald-500/30 transition-all duration-200"
        >
          <CheckCircle2 size={22} className="mr-2" /> Complete Task
        </Button>
      </div>

      {/* Keyboard Shortcuts Hint */}
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 text-slate-600 text-xs">
        Press <kbd className="px-2 py-1 bg-white/10 rounded mx-1">Esc</kbd> to exit
      </div>
    </div>
  );
};

export default React.memo(FocusSession);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { NAVIGATION_ITEMS, APP_NAME } from '../constants';
import { ViewMode, TaskType, ThemeOption, ViewSourceMode } from '../types';
import { Plus, Settings, X, Wallet, CheckCircle2, User, ChevronDown, Calendar, CheckSquare, Clock, Moon, Sun, ChevronLeft, ChevronRight, Menu, PanelLeft, PanelLeftClose, Bell, ChevronUp, Check, Pencil, Repeat, Bot, ArrowRight } from 'lucide-react';
import { t, ThemeText } from '../themeText';
import MiniCalendar from './MiniCalendar';

// Map navigation IDs to themeText keys
const navIdToTextKey: Record<string, keyof Omit<ThemeText, 'greeting'>> = {
    'dashboard': 'dashboard',
    'activities': 'activities',
    'tasks': 'tasks',
    'reminders': 'reminders',
    'events': 'events',
    'appointments': 'appointments',
    'calendar': 'calendar',
    'budget': 'budgetPlan',
    'notes': 'notes',
    'ai-chat': 'aiAssistant',
    'settings': 'settings',
};

export interface UserStats {
    userName: string;
    pendingTasks: number;
    totalTasks: number;
    budgetRemaining: number;
    partnerName?: string;
}

interface LayoutProps {
    children: React.ReactNode;
    currentView: ViewMode;
    onNavigate: (view: ViewMode) => void;
    onAddTask: (type?: TaskType) => void;
    userStats: UserStats;
    currentTheme: ThemeOption;
    onThemeChange: (theme: ThemeOption) => void;
    // New props for Calendar Tag Filtering
    calendarTags: string[];
    selectedTags: string[];
    onToggleTag: (tag: string) => void;
    // Rename Tag functionality
    onRenameTag?: (oldTag: string, newTag: string) => void;
    // View Source Mode for Personal/Partners/Combined views
    viewSourceMode: ViewSourceMode;
    onViewSourceModeChange: (mode: ViewSourceMode) => void;
    hasConnectedPartners?: boolean;
    // Routine creation callback
    onCreateRoutine?: () => void;
    // AI Assistant callback
    onOpenAI?: () => void;
    // Calendar date selection callback
    onCalendarDateSelect?: (date: Date) => void;
}

export const Layout: React.FC<LayoutProps> = ({
    children,
    currentView,
    onNavigate,
    onAddTask,
    userStats,
    currentTheme,
    onThemeChange,
    calendarTags,
    selectedTags,
    onToggleTag,
    onRenameTag,
    viewSourceMode,
    onViewSourceModeChange,
    hasConnectedPartners = false,
    onCreateRoutine,
    onOpenAI,
    onCalendarDateSelect
}) => {
    const [showProfileStats, setShowProfileStats] = useState(false);
    const [showCreateMenu, setShowCreateMenu] = useState(false);
    const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
    const [isSidebarHovered, setIsSidebarHovered] = useState(false);
    const [ignoreHover, setIgnoreHover] = useState(false);
    const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

    // Helper function to get theme-specific navigation label
    const getNavLabel = (id: string, defaultLabel: string): string => {
        const textKey = navIdToTextKey[id];
        return textKey ? t(currentTheme, textKey) : defaultLabel;
    };


    // Tag Editing State
    const [editingTag, setEditingTag] = useState<string | null>(null);
    const [editTagValue, setEditTagValue] = useState('');

    // State for expanded nested menus
    const [expandedMenus, setExpandedMenus] = useState<Record<string, boolean>>(() => {
        const initial: Record<string, boolean> = {};
        NAVIGATION_ITEMS.forEach(item => {
            const hasChildren = ('children' in item && !!item.children) || item.id === 'calendar';
            if (hasChildren) {
                const isChildActive = 'children' in item && item.children?.some(c => c.id === currentView);
                if (item.id === currentView || isChildActive) {
                    initial[item.id] = true;
                }
            }
        });
        return initial;
    });

    const profileRef = useRef<HTMLDivElement>(null);
    const createMenuRef = useRef<HTMLDivElement>(null);
    const editInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
                setShowProfileStats(false);
            }
            if (createMenuRef.current && !createMenuRef.current.contains(event.target as Node)) {
                setShowCreateMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (editingTag && editInputRef.current) {
            editInputRef.current.focus();
        }
    }, [editingTag]);

    const toggleTheme = useCallback(() => {
        if (currentTheme === 'light') {
            onThemeChange('dark');
        } else {
            onThemeChange('light');
        }
    }, [currentTheme, onThemeChange]);

    const handleParentClick = useCallback((itemId: string, hasChildren: boolean) => {
        onNavigate(itemId as ViewMode);

        if (hasChildren) {
            // Accordion behavior: Open clicked, close others
            setExpandedMenus({ [itemId]: true });
        } else {
            // Close all dropdowns if clicking a non-expandable item
            setExpandedMenus({});
        }
    }, [onNavigate]);

    const handleArrowClick = useCallback((e: React.MouseEvent, itemId: string) => {
        e.stopPropagation();

        if (itemId === 'calendar') {
            if (currentView === 'calendar') {
                // If already on calendar view, toggle the menu
                setExpandedMenus(prev => ({ ...prev, [itemId]: !prev[itemId] }));
            } else {
                // Navigate to calendar and ensure expanded, close others
                onNavigate(itemId as ViewMode);
                setExpandedMenus({ [itemId]: true });
            }
        } else {
            // Standard behavior for others (like Activities): Toggle only
            setExpandedMenus(prev => ({ ...prev, [itemId]: !prev[itemId] }));
        }
    }, [currentView, onNavigate]);

    const handleWrapperEnter = (itemId: string) => {
        // Calendar: Click only (per previous request)
        if (itemId === 'calendar') return;

        // Activities/Others: Open on Hover
        setExpandedMenus(prev => ({ ...prev, [itemId]: true }));
    };

    const handleWrapperLeave = (itemId: string) => {
        // Calendar: Maintain state (Click to toggle)
        if (itemId === 'calendar') return;

        // Activities/Others: Close on Mouse Leave
        setExpandedMenus(prev => ({ ...prev, [itemId]: false }));
    };

    const handleChildClick = useCallback((parentId: string, childId: string) => {
        onNavigate(childId as ViewMode);
        // Keep parent open when clicking a child, close others
        setExpandedMenus({ [parentId]: true });
    }, [onNavigate]);

    // Logic to allow immediate collapse even if hovered
    const handleToggleSidebar = useCallback(() => {
        if (isSidebarCollapsed) {
            setIsSidebarCollapsed(false);
        } else {
            setIsSidebarCollapsed(true);
            setIgnoreHover(true);
        }
    }, [isSidebarCollapsed]);

    const handleSidebarEnter = () => {
        setIsSidebarHovered(true);
    };

    const handleSidebarLeave = () => {
        setIsSidebarHovered(false);
        setIgnoreHover(false);
    };

    const startEditingTag = (tag: string, e: React.MouseEvent) => {
        e.stopPropagation();
        setEditingTag(tag);
        setEditTagValue(tag);
    };

    const submitEditTag = () => {
        if (editingTag && onRenameTag) {
            onRenameTag(editingTag, editTagValue);
        }
        setEditingTag(null);
        setEditTagValue('');
    };

    const handleEditKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            e.stopPropagation();
            submitEditTag();
        } else if (e.key === 'Escape') {
            setEditingTag(null);
        }
    };

    const isExpanded = !isSidebarCollapsed || (isSidebarHovered && !ignoreHover);
    const sidebarWidth = isExpanded ? 'w-72' : 'w-20';

    const userInitials = userStats.userName
        ? userStats.userName.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2)
        : 'U';

    return (
        <div className={`h-screen w-screen overflow-hidden font-sans transition-colors duration-500`}>
            {/* Global Background */}
            <div className="flex h-full w-full bg-gradient-main text-slate-800 dark:text-slate-200">

                {/* Sidebar */}
                <aside
                    className={`hidden md:flex flex-col glass z-40 shadow-2xl transition-all duration-300 ease-in-out border-r border-slate-200 dark:border-white/5 relative ${sidebarWidth}`}
                    onMouseEnter={handleSidebarEnter}
                    onMouseLeave={handleSidebarLeave}
                >

                    {/* Sidebar Header */}
                    <div className="h-20 flex items-center justify-between px-6 border-b border-slate-200 dark:border-white/5 shrink-0">
                        <div className={`transition-opacity duration-300 ${isExpanded ? 'opacity-100' : 'opacity-0 w-0 overflow-hidden'}`}>
                            {/* Theme-specific logo + text */}
                            <div 
                                className="flex items-center gap-2 cursor-pointer hover:opacity-80 transition-opacity"
                                onClick={() => onNavigate('calendar')}
                                title="Go to Calendar"
                            >
                                <img
                                    src={currentTheme === 'cyberpunk' ? '/logo-cyberpunk.jpg' : currentTheme === 'onepiece' ? '/logo-onepiece.png' : currentTheme === 'dark' ? '/logo-dark.jpg' : '/logo-light.jpg'}
                                    alt={APP_NAME}
                                    className="h-9 w-auto rounded-lg"
                                />
                                <span className={`text-lg font-bold tracking-wide font-display ${currentTheme === 'light' ? 'text-slate-800' : currentTheme === 'onepiece' ? 'text-[#E8DCD0]' : currentTheme === 'cyberpunk' ? 'text-[#E0FFFF]' : 'text-white'}`}>
                                    {APP_NAME}
                                </span>
                            </div>
                        </div>

                        <button
                            onClick={handleToggleSidebar}
                            className={`p-2 rounded-lg text-slate-400 hover:text-slate-700 dark:hover:text-white transition-colors ${!isExpanded ? 'mx-auto' : ''}`}
                            title={isSidebarCollapsed ? "Pin Sidebar Open" : "Collapse Sidebar"}
                            aria-label={isSidebarCollapsed ? "Pin sidebar open" : "Collapse sidebar"}
                        >
                            {isSidebarCollapsed ? <PanelLeft size={20} /> : <PanelLeftClose size={20} />}
                        </button>
                    </div>

                    {/* Mini Calendar */}
                    <MiniCalendar 
                        currentTheme={currentTheme} 
                        isExpanded={isExpanded}
                        onDateSelect={(date) => {
                            // Navigate to calendar view and pass selected date
                            onNavigate('calendar');
                            onCalendarDateSelect?.(date);
                        }}
                    />

                    {/* Nav Links */}
                    <nav className="flex-1 px-3 py-4 space-y-2 overflow-y-auto overflow-x-hidden no-scrollbar">
                        {NAVIGATION_ITEMS.map((item) => {
                            const Icon = item.icon;

                            // Dynamic Children Handling
                            const hasChildren = ('children' in item && !!item.children) || (item.id === 'calendar' && calendarTags.length > 0);

                            const isParentActive = (hasChildren && item.children?.some(child => child.id === currentView)) || (item.id === currentView);
                            const isActive = currentView === item.id;
                            const isMenuExpanded = expandedMenus[item.id];

                            return (
                                <div
                                    key={item.id}
                                    onMouseEnter={() => handleWrapperEnter(item.id)}
                                    onMouseLeave={() => handleWrapperLeave(item.id)}
                                >
                                    {/* Parent Item */}
                                    <button
                                        onClick={() => handleParentClick(item.id, hasChildren)}
                                        className={`group w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all duration-200 font-medium whitespace-nowrap relative ${isActive || isParentActive
                                            ? 'bg-brand-500/5 text-brand-600 dark:text-brand-300 border border-brand-500/10'
                                            : 'text-slate-600 dark:text-slate-400 hover:bg-black/5 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-slate-100'
                                            }`}
                                        title={!isExpanded ? item.label : undefined}
                                    >
                                        <div className="flex items-center justify-center w-6 h-6 shrink-0">
                                            <Icon size={20} className={`transition-colors ${isActive || isParentActive ? 'text-brand-500 dark:text-brand-400' : 'text-slate-400 dark:text-slate-500 group-hover:text-slate-600 dark:group-hover:text-slate-300'}`} />
                                        </div>

                                        <span className={`transition-all duration-300 flex-1 text-left ${!isExpanded ? 'opacity-0 w-0 overflow-hidden' : 'opacity-100 ml-1'}`}>
                                            {getNavLabel(item.id, item.label)}
                                        </span>

                                        {hasChildren && isExpanded && (
                                            <div
                                                className="text-slate-400 p-1 hover:text-brand-500 dark:hover:text-brand-400 z-10"
                                                onClick={(e) => handleArrowClick(e, item.id)}
                                            >
                                                {isMenuExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                                            </div>
                                        )}

                                        {isActive && isExpanded && !hasChildren && (
                                            <div className="ml-auto w-1.5 h-1.5 rounded-full bg-brand-500 shadow-[0_0_8px_rgba(14,165,233,0.6)]" />
                                        )}
                                    </button>

                                    {/* Children Items */}
                                    {hasChildren && isMenuExpanded && isExpanded && (
                                        <div className="mt-1 ml-4 pl-3 border-l border-slate-200 dark:border-white/10 space-y-1 animate-slide-up">
                                            {item.id === 'calendar' ? (
                                                // Special Calendar Filters
                                                calendarTags.map(tag => {
                                                    const isSelected = selectedTags.includes(tag);
                                                    const isEditing = editingTag === tag;

                                                    return (
                                                        <div
                                                            key={tag}
                                                            onClick={(e) => { e.stopPropagation(); if (!isEditing) onToggleTag(tag); }}
                                                            className="group w-full flex items-center gap-3 px-3 py-2 cursor-pointer rounded-lg hover:bg-black/5 dark:hover:bg-white/5 transition-colors relative"
                                                        >
                                                            {isEditing ? (
                                                                <div className="flex items-center gap-2 w-full">
                                                                    <input
                                                                        ref={editInputRef}
                                                                        type="text"
                                                                        value={editTagValue}
                                                                        onChange={(e) => setEditTagValue(e.target.value)}
                                                                        onKeyDown={handleEditKeyDown}
                                                                        onBlur={submitEditTag}
                                                                        className="flex-1 bg-white dark:bg-slate-800 border border-brand-500 rounded px-2 py-0.5 text-xs text-slate-800 dark:text-slate-200 focus:outline-none min-w-0"
                                                                        onClick={(e) => e.stopPropagation()}
                                                                    />
                                                                </div>
                                                            ) : (
                                                                <>
                                                                    <div
                                                                        className={`w-4 h-4 rounded flex items-center justify-center transition-all flex-shrink-0 ${isSelected
                                                                            ? 'bg-brand-500 border-brand-500 text-white'
                                                                            : 'border-2 border-slate-300 dark:border-slate-600 text-transparent hover:border-brand-400'
                                                                            }`}
                                                                    >
                                                                        <Check size={10} strokeWidth={4} />
                                                                    </div>
                                                                    <span className={`text-sm truncate transition-colors flex-1 ${isSelected ? 'text-slate-700 dark:text-slate-200 font-medium' : 'text-slate-500 dark:text-slate-500'}`}>
                                                                        {tag}
                                                                    </span>

                                                                    {onRenameTag && tag !== 'Untagged' && (
                                                                        <button
                                                                            onClick={(e) => startEditingTag(tag, e)}
                                                                            className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-brand-500 p-1 transition-opacity"
                                                                            title="Rename Tag"
                                                                            aria-label={`Rename tag ${tag}`}
                                                                        >
                                                                            <Pencil size={12} />
                                                                        </button>
                                                                    )}
                                                                </>
                                                            )}
                                                        </div>
                                                    );
                                                })
                                            ) : (
                                                // Standard Nested Items
                                                item.children?.map(child => {
                                                    const ChildIcon = child.icon;
                                                    const isChildActive = currentView === child.id;
                                                    return (
                                                        <button
                                                            key={child.id}
                                                            onClick={(e) => { e.stopPropagation(); handleChildClick(item.id, child.id); }}
                                                            className={`group w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 text-sm font-medium whitespace-nowrap ${isChildActive
                                                                ? 'bg-brand-500/10 text-brand-600 dark:text-brand-300 shadow-sm'
                                                                : 'text-slate-500 dark:text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 hover:bg-black/5 dark:hover:bg-white/5'
                                                                }`}
                                                        >
                                                            <div className="flex items-center justify-center w-5 h-5 shrink-0">
                                                                <ChildIcon size={18} strokeWidth={isChildActive ? 2.5 : 2} className={isChildActive ? 'text-brand-500 dark:text-brand-400' : 'text-current'} />
                                                            </div>
                                                            <span>{getNavLabel(child.id, child.label)}</span>
                                                        </button>
                                                    )
                                                })
                                            )}
                                        </div>
                                    )}

                                    {/* Collapsed Parent Indicator dot if nested child is active */}
                                    {hasChildren && !isExpanded && isParentActive && (
                                        <div className="mx-auto mt-1 w-1 h-1 rounded-full bg-brand-500" />
                                    )}
                                </div>
                            );
                        })}
                    </nav>

                    {/* Bottom Actions */}
                    <div className="p-3 border-t border-slate-200 dark:border-white/5 bg-slate-50/50 dark:bg-black/20">

                        <div className={`flex items-center ${isExpanded ? 'justify-between' : 'justify-center flex-col gap-4'}`}>

                            {/* User Profile */}
                            <div
                                className={`flex items-center gap-2 p-1 rounded-xl transition-colors relative cursor-pointer hover:bg-black/5 dark:hover:bg-white/5`}
                                ref={profileRef}
                                onClick={() => setShowProfileStats(!showProfileStats)}
                                title="Profile"
                            >
                                <div className="w-9 h-9 shrink-0 rounded-full bg-gradient-to-br from-brand-500 to-indigo-600 flex items-center justify-center text-white text-sm font-bold shadow-md ring-2 ring-white/20">
                                    {userInitials}
                                </div>
                                {isExpanded && (
                                    <div className="min-w-0 pr-2">
                                        <p className="text-sm font-semibold text-slate-700 dark:text-slate-200 truncate">{userStats.userName}</p>
                                        <p className="text-xs text-slate-500 dark:text-slate-400 truncate">Pro Plan</p>
                                    </div>
                                )}
                            </div>

                            {/* Icons Group */}
                            <div className={`flex ${isExpanded ? 'gap-1' : 'flex-col gap-2'}`}>
                                {/* Quick Theme Toggle */}
                                <button
                                    onClick={toggleTheme}
                                    className="p-2 rounded-lg text-slate-400 hover:text-slate-700 dark:hover:text-white hover:bg-black/5 dark:hover:bg-white/5 transition-colors"
                                    title="Toggle Theme"
                                    aria-label="Toggle theme"
                                >
                                    {currentTheme === 'light' ? <Sun size={20} /> : <Moon size={20} />}
                                </button>

                                {/* Settings Icon */}
                                <button
                                    onClick={() => { onNavigate('settings'); setExpandedMenus({}); }}
                                    className="p-2 text-slate-400 hover:text-slate-700 dark:hover:text-white transition-colors rounded-lg hover:bg-black/5 dark:hover:bg-white/5"
                                    title="Settings"
                                    aria-label="Settings"
                                >
                                    <Settings size={20} />
                                </button>
                            </div>

                        </div>

                        {/* Profile Popover */}
                        {showProfileStats && (
                            <div className="absolute bottom-4 left-full ml-4 w-72 glass-panel rounded-2xl shadow-2xl p-5 animate-scale-in z-50 bg-white/90 dark:bg-slate-900/90">
                                <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-200 dark:border-white/5">
                                    <h3 className="font-bold text-slate-800 dark:text-slate-200">Account Overview</h3>
                                    <button onClick={(e) => { e.stopPropagation(); setShowProfileStats(false) }} className="text-slate-500 hover:text-slate-800 dark:hover:text-white" aria-label="Close profile menu">
                                        <X size={16} />
                                    </button>
                                </div>

                                <div className="space-y-4">
                                    <button 
                                        onClick={() => {
                                            onNavigate('calendar');
                                            onCalendarDateSelect?.(new Date());
                                            setShowProfileStats(false);
                                        }}
                                        className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-white/5 transition-colors group cursor-pointer"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 group-hover:bg-emerald-500/20 transition-colors">
                                                <CheckCircle2 size={16} />
                                            </div>
                                            <div>
                                                <p className="text-xs text-slate-500 font-bold uppercase">Today's Load</p>
                                                <p className="text-sm text-slate-700 dark:text-slate-200 font-semibold">{userStats.pendingTasks} Pending</p>
                                            </div>
                                        </div>
                                        <ArrowRight size={16} className="text-slate-400 opacity-0 group-hover:opacity-100 transition-opacity" />
                                    </button>

                                    <button 
                                        onClick={() => {
                                            onNavigate('settings');
                                            setShowProfileStats(false);
                                        }}
                                        className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-white/5 transition-colors group cursor-pointer"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400 group-hover:bg-blue-500/20 transition-colors">
                                                <User size={16} />
                                            </div>
                                            <div>
                                                <p className="text-xs text-slate-500 font-bold uppercase">Partner</p>
                                                <p className="text-sm text-slate-700 dark:text-slate-200 font-semibold">{userStats.partnerName || 'Not Connected'}</p>
                                            </div>
                                        </div>
                                        <ArrowRight size={16} className="text-slate-400 opacity-0 group-hover:opacity-100 transition-opacity" />
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                </aside>

                {/* Main Content Area */}
                <div className="flex-1 flex flex-col h-full overflow-hidden relative">

                    {/* TOP Header */}
                    <header className="h-20 glass border-b border-slate-200 dark:border-white/5 flex items-center justify-between px-6 z-30 shrink-0">
                        {/* Brand */}
                        <div className="flex items-center gap-6">
                            {/* Mobile Menu Trigger (Visible only on mobile) */}
                            <button
                                className="md:hidden text-slate-500 hover:text-slate-700 dark:hover:text-white transition-colors"
                                onClick={() => setIsMobileSidebarOpen(true)}
                                aria-label="Open navigation menu"
                            >
                                <Menu size={24} />
                            </button>

                            {/* Theme-specific logo + text (mobile) */}
                            <div 
                                className="flex md:hidden items-center gap-2 cursor-pointer hover:opacity-80 transition-opacity"
                                onClick={() => onNavigate('calendar')}
                            >
                                <img
                                    src={currentTheme === 'cyberpunk' ? '/logo-cyberpunk.jpg' : currentTheme === 'onepiece' ? '/logo-onepiece.png' : currentTheme === 'dark' ? '/logo-dark.jpg' : '/logo-light.jpg'}
                                    alt={APP_NAME}
                                    className="h-8 w-auto rounded-lg"
                                />
                                <span className={`text-lg font-bold tracking-wide font-display ${currentTheme === 'light' ? 'text-slate-800' : currentTheme === 'onepiece' ? 'text-[#E8DCD0]' : currentTheme === 'cyberpunk' ? 'text-[#E0FFFF]' : 'text-white'}`}>
                                    {APP_NAME}
                                </span>
                            </div>

                            {/* Create Button moved to Header */}
                            <div className="relative hidden md:block" ref={createMenuRef}>
                                {(() => {
                                    const getCreateThemeStyles = () => {
                                        switch (currentTheme) {
                                            case 'cyberpunk':
                                                return {
                                                    btn: 'bg-black border border-cyan-500 text-cyan-400 shadow-[0_0_15px_rgba(6,182,212,0.4)] hover:shadow-[0_0_20px_rgba(6,182,212,0.6)] hover:bg-cyan-950/30',
                                                    menu: 'bg-[#0a0014] border border-[#00FFFF]/30 shadow-[0_0_20px_rgba(0,255,255,0.2)]',
                                                    item: 'text-cyan-100 hover:bg-[#00FFFF]/10 hover:text-[#00FFFF]',
                                                    icon: 'text-cyan-400' // Override icon colors for cyberpunk consistency? varying colors is good though.
                                                };
                                            case 'onepiece':
                                                return {
                                                    btn: 'bg-[#8B4513] border border-[#D4A574] text-[#E8DCD0] shadow-md hover:bg-[#A0522D]',
                                                    menu: 'bg-[#14100c] border border-[#D4A574]/40 shadow-xl',
                                                    item: 'text-[#E8DCD0] hover:bg-[#D4A574]/10 hover:text-[#D4A574]'
                                                };
                                            case 'sunset':
                                                return {
                                                    btn: 'bg-gradient-to-r from-rose-500 to-orange-500 text-white shadow-lg shadow-rose-500/25 hover:shadow-rose-500/40',
                                                    menu: 'bg-[#2a1b20] border border-rose-400/30 shadow-xl',
                                                    item: 'text-rose-100 hover:bg-rose-500/10 hover:text-rose-50'
                                                };
                                            case 'light':
                                                return {
                                                    btn: 'bg-slate-900 text-white shadow-lg hover:bg-slate-800',
                                                    menu: 'bg-white border border-slate-200 shadow-xl',
                                                    item: 'text-slate-700 hover:bg-slate-50 hover:text-slate-900'
                                                };
                                            default: // dark
                                                return {
                                                    btn: 'bg-white text-slate-900 shadow-lg hover:bg-slate-100',
                                                    menu: 'bg-slate-900 border border-slate-700 shadow-xl',
                                                    item: 'text-slate-300 hover:bg-white/5 hover:text-white'
                                                };
                                        }
                                    };
                                    
                                    const themeStyles = getCreateThemeStyles();

                                    return (
                                        <>
                                            <button
                                                onClick={() => setShowCreateMenu(!showCreateMenu)}
                                                className={`flex items-center gap-2 px-4 py-2 rounded-xl font-semibold transition-all active:scale-95 ${themeStyles.btn}`}
                                            >
                                                <Plus size={18} strokeWidth={2.5} />
                                                <span>Create</span>
                                                <ChevronDown size={14} className={`opacity-60 transition-transform ${showCreateMenu ? 'rotate-180' : ''}`} />
