                        </div>
                    </main>

                    {/* Mobile Floating Action Button (FAB) */}
                    <div className="md:hidden absolute bottom-24 left-1/2 -translate-x-1/2 z-40 pointer-events-none">
                        <button
                            onClick={() => onAddTask('TASK')}
                            className="pointer-events-auto bg-brand-500 text-white w-14 h-14 rounded-full flex items-center justify-center shadow-[0_8px_30px_rgb(14,165,233,0.4)] active:scale-90 transition-transform border-4 border-slate-50 dark:border-slate-900"
                        >
                            <Plus size={28} />
                        </button>
                    </div>

                    {/* Mobile Bottom Nav */}
                    <div className="md:hidden absolute bottom-0 left-0 right-0 glass border-t border-slate-200 dark:border-white/10 pb-safe-area z-30">
                        <div className="flex justify-around items-center h-20 px-4 pb-2">
                            {NAVIGATION_ITEMS.map((item) => {
                                const Icon = item.icon;
                                const isActive = currentView === item.id;
                                return (
                                    <button
                                        key={item.id}
                                        onClick={() => onNavigate(item.id as ViewMode)}
                                        className={`flex flex-col items-center justify-center w-full h-full gap-1.5 transition-all ${isActive ? 'text-brand-500' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'
                                            }`}
                                    >
                                        <div className={`p-1.5 rounded-full transition-all ${isActive ? 'bg-brand-500/10' : ''}`}>
                                            <Icon size={24} strokeWidth={isActive ? 2.5 : 2} className={isActive ? 'scale-110 transition-transform' : ''} />
                                        </div>
                                        <span className={`text-[10px] font-medium ${isActive ? 'text-brand-500' : 'text-slate-500'}`}>{getNavLabel(item.id, item.label)}</span>
                                    </button>
                                )
                            })}
                            {/* AI Assistant Tab */}
                            {onOpenAI && (
                                <button
                                    onClick={onOpenAI}
                                    className={`flex flex-col items-center justify-center w-full h-full gap-1.5 transition-all ${currentView === 'ai-chat' ? 'text-brand-500' : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-300'}`}
                                >
                                    <div className={`p-1.5 rounded-full transition-all ${currentView === 'ai-chat' ? 'bg-brand-500/10' : ''}`}>
                                        <Bot size={24} strokeWidth={currentView === 'ai-chat' ? 2.5 : 2} className={currentView === 'ai-chat' ? 'scale-110 transition-transform' : ''} />
                                    </div>
                                    <span className={`text-[10px] font-medium ${currentView === 'ai-chat' ? 'text-brand-500' : 'text-slate-500'}`}>AI</span>
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Floating AI Assistant Widget - Desktop Only */}
                    {onOpenAI && (
                        <button
                            onClick={onOpenAI}
                            className={`hidden md:flex fixed z-50 items-center gap-2 rounded-2xl hover:scale-105 transition-all active:scale-95 group ${
                                currentTheme === 'cyberpunk'
                                    ? 'bg-gradient-to-r from-[#00FFFF] to-[#FF00FF] text-[#0a0014] shadow-[0_8px_30px_rgba(0,255,255,0.4)] hover:shadow-[0_12px_40px_rgba(0,255,255,0.6)]'
                                    : currentTheme === 'sunset'
                                    ? 'bg-gradient-to-r from-rose-500 via-orange-500 to-amber-500 text-white shadow-[0_8px_30px_rgba(244,63,94,0.4)] hover:shadow-[0_12px_40px_rgba(244,63,94,0.5)]'
                                    : currentTheme === 'onepiece'
                                    ? 'bg-gradient-to-r from-[#D4A574] via-[#E8C399] to-[#D4A574] text-[#0A0A0A] shadow-[0_8px_30px_rgba(212,165,116,0.4)] hover:shadow-[0_12px_40px_rgba(212,165,116,0.5)]'
                                    : currentTheme === 'light'
                                    ? 'bg-gradient-to-r from-slate-800 to-slate-900 text-white shadow-[0_8px_30px_rgba(30,58,95,0.3)] hover:shadow-[0_12px_40px_rgba(30,58,95,0.4)]'
                                    : 'bg-gradient-to-r from-white to-slate-200 text-slate-900 shadow-[0_8px_30px_rgba(255,255,255,0.2)] hover:shadow-[0_12px_40px_rgba(255,255,255,0.3)]'
