};

import React, { useState, useEffect, useMemo } from 'react';
import { ThemeOption, Note, ChecklistItem, NoteShare, Partnership } from '../types';
import { useNotes } from '../hooks/useNotes';
import * as NotesService from '../services/notesService';
import * as PartnerService from '../services/partnerService';
import { supabase } from '../services/supabaseClient'; 
import Button from './Button';
import Input from './Input';
import Select from './Select';
import { 
  FileText, Plus, Trash2, Share2, CheckSquare, 
  X, Loader2, UserPlus, User, Save, Search, StickyNote,
  Check
} from 'lucide-react';
import { t } from '../themeText';
import { logger } from '../utils/logger';

interface NotesManagerProps {
  currentTheme: ThemeOption;
}

const NotesManager: React.FC<NotesManagerProps> = ({ currentTheme }) => {
  const { notes, isLoading, createNote, updateNote, deleteNote, shareNote, unshareNote } = useNotes();
  
  // UI State
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editingNote, setEditingNote] = useState<Note | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  // Form State
  const [noteTitle, setNoteTitle] = useState('');
  const [noteContent, setNoteContent] = useState('');
  const [noteType, setNoteType] = useState<'note' | 'checklist'>('note');
  const [checklistItems, setChecklistItems] = useState<ChecklistItem[]>([]);
  const [newChecklistItem, setNewChecklistItem] = useState('');
  
  // Sharing State
  const [noteShares, setNoteShares] = useState<Record<string, NoteShare[]>>({});
  const [partnerships, setPartnerships] = useState<Partnership[]>([]);
  const [isLoadingShares, setIsLoadingShares] = useState(false);
  const [sharingNoteId, setSharingNoteId] = useState<string | null>(null);
  const [selectedPartnerId, setSelectedPartnerId] = useState('');
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  // Load user data on mount
  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      if (data.user) setCurrentUserId(data.user.id);
    });
    loadPartnerships();
  }, []);

  const loadPartnerships = async () => {
    const partners = await PartnerService.getPartnerships();
    setPartnerships(partners.filter(p => p.status === 'accepted'));
  };

  const loadNoteShares = async (noteId: string) => {
    setIsLoadingShares(true);
    const shares = await NotesService.getNoteShares(noteId);
    setNoteShares(prev => ({ ...prev, [noteId]: shares }));
    setIsLoadingShares(false);
  };

  const handleCreateNote = () => {
    setEditingNote(null);
    setNoteTitle('');
    setNoteContent('');
    setNoteType('note');
    setChecklistItems([]);
    setIsEditorOpen(true);
  };

  const handleEditNote = (note: Note) => {
    setEditingNote(note);
    setNoteTitle(note.title);
    setNoteContent(note.content);
    setNoteType(note.isChecklist ? 'checklist' : 'note');
    setChecklistItems(note.checklistItems || []);
    setIsEditorOpen(true);
    if (note.isShared) {
      loadNoteShares(note.id);
    }
  };

  const handleSaveNote = async () => {
    if (!noteTitle.trim()) {
      alert('Please enter a title for the note');
      return;
    }

    try {
      if (editingNote) {
        await updateNote(editingNote.id, {
          title: noteTitle,
          content: noteContent,
          isChecklist: noteType === 'checklist',
          checklistItems: noteType === 'checklist' ? checklistItems : [],
        });
      } else {
        await createNote(
          noteTitle,
          noteContent,
          noteType === 'checklist',
          noteType === 'checklist' ? checklistItems : []
        );
      }
      setIsEditorOpen(false);
      resetForm();
    } catch (error) {
      logger.error('Failed to save note', error);
      alert('Failed to save note. Please try again.');
    }
  };

  const handleDeleteNote = async (noteId: string) => {
    if (confirm('Are you sure you want to delete this note?')) {
      try {
        await deleteNote(noteId);
        setIsEditorOpen(false);
        resetForm();
      } catch (error) {
        logger.error('Failed to delete note', error);
        alert('Failed to delete note. Please try again.');
      }
    }
  };

  const handleAddChecklistItem = () => {
    if (newChecklistItem.trim()) {
      setChecklistItems([
        ...checklistItems,
        {
          id: crypto.randomUUID(),
          text: newChecklistItem.trim(),
          isCompleted: false,
        },
      ]);
      setNewChecklistItem('');
    }
  };

  const handleToggleChecklistItem = (itemId: string) => {
    setChecklistItems(checklistItems.map(item =>
      item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item
    ));
  };

  const handleRemoveChecklistItem = (itemId: string) => {
    setChecklistItems(checklistItems.filter(item => item.id !== itemId));
  };

  const handleShareNote = async () => {
    if (!editingNote || !selectedPartnerId) return;
    
    try {
      await shareNote(editingNote.id, selectedPartnerId);
      await loadNoteShares(editingNote.id);
      setSelectedPartnerId('');
    } catch (error) {
      logger.error('Failed to share note', error);
      alert('Failed to share note. Please try again.');
    }
  };


  const handleUnshareNote = async (shareId: string) => {
    if (!editingNote) return;
    
    try {
      await unshareNote(shareId);
      await loadNoteShares(editingNote.id);
    } catch (error) {
      logger.error('Failed to unshare note', error);
      alert('Failed to unshare note. Please try again.');
    }
  };

  const handleToggleQuickChecklist = async (e: React.MouseEvent, note: Note, itemId: string) => {
    e.stopPropagation(); // Prevent opening the modal
    
    // Optimistic update locally? 
    // Actually relying on React Query optimistic update in useNotes is better, 
    // but we need to pass the FULL new items list to updateNote.
    
    const updatedItems = note.checklistItems.map(item => 
        item.id === itemId ? { ...item, isCompleted: !item.isCompleted } : item
    );

    try {
        await updateNote(note.id, {
            checklistItems: updatedItems
        });
    } catch (error) {
        logger.error('Failed to toggle item', error);
    }
  };

  const resetForm = () => {
    setEditingNote(null);
    setNoteTitle('');
    setNoteContent('');
    setNoteType('note');
    setChecklistItems([]);
    setNewChecklistItem('');
    setSelectedPartnerId('');
  };

  const filteredNotes = useMemo(() => {
    if (!searchQuery.trim()) return notes;
    const query = searchQuery.toLowerCase();
    return notes.filter(note =>
      note.title.toLowerCase().includes(query) ||
      note.content.toLowerCase().includes(query)
    );
  }, [notes, searchQuery]);

  const availablePartners = useMemo(() => {
    if (!editingNote) return [];
    const currentShares = noteShares[editingNote.id] || [];
    return partnerships.filter(p =>
      !currentShares.some(s => s.sharedWithId === p.partnerId)
    );
  }, [partnerships, noteShares, editingNote]);

  return (
    <div className="space-y-8 animate-fade-in h-full flex flex-col">
      {/* Header */}
      <div className="border-b border-slate-200 dark:border-white/5 pb-6">
        <h2 className="text-3xl font-bold text-slate-800 dark:text-slate-100 mb-2 flex items-center gap-3">
          <StickyNote className="text-brand-500" /> {t(currentTheme, 'myNotes')}
        </h2>
        <p className="text-slate-500 dark:text-slate-400">Capture your thoughts, ideas, and checklists.</p>
      </div>

      {/* Search and Create */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            placeholder="Search notes..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-100 dark:bg-dark-surface border border-slate-200 dark:border-dark-border rounded-xl pl-10 pr-4 py-2.5 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 transition-all placeholder-slate-400 dark:placeholder-slate-500 shadow-sm"
          />
        </div>
        <Button variant="primary" onClick={handleCreateNote} className="flex-shrink-0">
          <Plus size={18} className="mr-2" />
          {t(currentTheme, 'addNote')}
        </Button>
      </div>

      {/* Notes Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 pb-20 overflow-y-auto">
        {isLoading ? (
          <div className="col-span-full flex items-center justify-center py-12">
            <Loader2 className="animate-spin text-brand-500" size={32} />
          </div>
        ) : filteredNotes.length === 0 ? (
          <div className="col-span-full glass-panel rounded-2xl p-12 text-center">
            <div className="w-16 h-16 bg-brand-500/10 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <FileText size={32} className="text-brand-500" />
            </div>
            <p className="text-slate-600 dark:text-slate-300 font-medium">
              {searchQuery ? 'No notes found matching your search.' : 'No notes yet. Create your first note!'}
            </p>
            {searchQuery && (
              <Button variant="ghost" onClick={() => setSearchQuery('')} className="mt-3 text-brand-500">
                Clear Search
              </Button>
            )}
          </div>
        ) : (
          filteredNotes.map((note) => (
            <div
              key={note.id}
              onClick={() => handleEditNote(note)}
              className="glass-panel p-5 rounded-2xl cursor-pointer hover:shadow-lg transition-all border-2 border-transparent hover:border-brand-500/20 group"
            >
              <div className="flex items-start justify-between mb-3">
                <h3 className="font-bold text-slate-800 dark:text-slate-100 text-lg group-hover:text-brand-500 transition-colors line-clamp-1 flex-1">
                  {note.title}
                </h3>
                <div className="flex gap-1 ml-2 flex-shrink-0">
                  {note.isChecklist && (
                    <div className="p-1.5 rounded-lg bg-brand-500/10 text-brand-500">
                      <CheckSquare size={14} />
                    </div>
                  )}
                  {note.isShared && (
                    <div className="p-1.5 rounded-lg bg-blue-500/10 text-blue-500">
                      <Share2 size={14} />
                    </div>
                  )}
                  {note.isShared && (
                    <div 
                        className={`p-1.5 rounded-lg ${note.user_id === currentUserId ? 'bg-blue-500/10 text-blue-500' : 'bg-purple-500/10 text-purple-500'}`}
                        title={note.user_id === currentUserId ? 'Shared by you' : 'Shared with you'}
                    >
                      {note.user_id === currentUserId ? <Share2 size={14} /> : <User size={14} />}
                    </div>
                  )}
                </div>
              </div>
              
              {note.isChecklist ? (
                <div className="space-y-1.5">
                  {note.checklistItems.slice(0, 3).map((item) => (
                    <div key={item.id} className="flex items-center gap-2 text-sm">
                      <div 
                        onClick={(e) => handleToggleQuickChecklist(e, note, item.id)}
                        className={`w-3.5 h-3.5 rounded border flex-shrink-0 cursor-pointer transition-colors flex items-center justify-center ${
                        item.isCompleted 
                          ? 'bg-brand-500 border-brand-500' 
                          : 'border-slate-300 dark:border-slate-600 hover:border-brand-500'
                      }`}>
                        {item.isCompleted && <Check size={10} className="text-white" />}
                      </div>
                      <span className={`line-clamp-1 ${
                        item.isCompleted 
                          ? 'line-through text-slate-400' 
                          : 'text-slate-600 dark:text-slate-300'
                      }`}>
                        {item.text}
                      </span>
                    </div>
                  ))}
                  {note.checklistItems.length > 3 && (
                    <p className="text-xs text-slate-400 ml-5">
                      +{note.checklistItems.length - 3} more items
                    </p>
                  )}
                </div>
              ) : (
                <p className="text-slate-600 dark:text-slate-300 text-sm line-clamp-3">
                  {note.content || 'No content'}
                </p>
              )}
              
              <div className="mt-4 pt-3 border-t border-slate-200 dark:border-white/10 text-xs text-slate-400">
                {new Date(note.updatedAt).toLocaleDateString('en-US', {
                  year: 'numeric',
                  month: 'short',
                  day: 'numeric',
                })}
                {note.isShared && currentUserId && note.user_id !== currentUserId && (
                    <span className="ml-2 px-1.5 py-0.5 rounded-md bg-purple-500/10 text-purple-600 dark:text-purple-400 text-[10px] font-semibold uppercase tracking-wider">
                        Shared
                    </span>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Editor Modal */}
      {isEditorOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white dark:bg-slate-900 rounded-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden shadow-2xl border border-slate-200 dark:border-white/10 animate-scale-in flex flex-col">
            {/* Editor Header */}
            <div className="p-6 border-b border-slate-200 dark:border-white/10 flex items-center justify-between bg-slate-50 dark:bg-slate-800/50">
              <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">
                {editingNote ? 'Edit Note' : 'Create New Note'}
              </h3>
              <button
                onClick={() => { setIsEditorOpen(false); resetForm(); }}
                className="p-2 rounded-xl hover:bg-slate-200 dark:hover:bg-white/10 transition-colors text-slate-600 dark:text-slate-300"
                aria-label="Close editor"
              >
                <X size={20} />
              </button>
            </div>

            {/* Editor Content */}
            <div className="p-6 overflow-y-auto flex-1 space-y-4">
              {/* Note Type Toggle */}
              <div className="flex gap-2">
                <button
                  onClick={() => setNoteType('note')}
                  className={`flex-1 py-2 px-4 rounded-xl font-medium transition-all ${
                    noteType === 'note'
                      ? 'bg-brand-500 text-white shadow-md'
                      : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
                  }`}
                >
                  <FileText size={16} className="inline mr-2" />
                  Note
                </button>
                <button
                  onClick={() => setNoteType('checklist')}
                  className={`flex-1 py-2 px-4 rounded-xl font-medium transition-all ${
                    noteType === 'checklist'
                      ? 'bg-brand-500 text-white shadow-md'
                      : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
                  }`}
                >
                  <CheckSquare size={16} className="inline mr-2" />
                  Checklist
                </button>
              </div>

              {/* Title Input */}
              <Input
                label="Title"
                value={noteTitle}
                onChange={(e) => setNoteTitle(e.target.value)}
                placeholder="Enter note title..."
              />

              {noteType === 'note' ? (
                // Plain Note Content
                <div>
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-2 ml-1 font-mono">
                    Content
                  </label>
                  <textarea
                    value={noteContent}
                    onChange={(e) => setNoteContent(e.target.value)}
                    placeholder={t(currentTheme, 'noteContent')}
                    rows={8}
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-3 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 transition-all placeholder-slate-400 dark:placeholder-slate-500 resize-none"
                  />
                </div>
              ) : (
                // Checklist Items
                <div className="space-y-3">
                  <label className="block text-[10px] font-bold uppercase text-slate-400 mb-2 ml-1 font-mono">
                    Checklist Items
                  </label>
                  
                  {/* Add New Item */}
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={newChecklistItem}
                      onChange={(e) => setNewChecklistItem(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && handleAddChecklistItem()}
                      placeholder="Add an item..."
                      className="flex-1 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl px-4 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50 transition-all placeholder-slate-400"
                    />
                    <Button variant="primary" onClick={handleAddChecklistItem}>
                      <Plus size={16} />
                    </Button>
                  </div>

                  {/* Checklist Items List */}
                  <div className="space-y-2 max-h-64 overflow-y-auto">
                    {checklistItems.map((item) => (
                      <div
                        key={item.id}
                        className="flex items-center gap-3 p-3 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10"
                      >
                        <button
                          onClick={() => handleToggleChecklistItem(item.id)}
                          className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all ${
                            item.isCompleted
                              ? 'bg-brand-500 border-brand-500'
                              : 'border-slate-300 dark:border-slate-600 hover:border-brand-500'
                          }`}
                          aria-label={item.isCompleted ? 'Mark item incomplete' : 'Mark item complete'}
                        >
                          {item.isCompleted && <Check size={14} className="text-white" />}
                        </button>
                        <span
                          className={`flex-1 text-sm ${
                            item.isCompleted
                              ? 'line-through text-slate-400'
                              : 'text-slate-700 dark:text-slate-200'
                          }`}
                        >
                          {item.text}
                        </span>
                        <button
                          onClick={() => handleRemoveChecklistItem(item.id)}
                          className="p-1 rounded-lg text-slate-400 hover:bg-red-500/10 hover:text-red-500 transition-colors"
                          aria-label="Remove item"
                        >
                          <X size={16} />
                        </button>
                      </div>
                    ))}
                    {checklistItems.length === 0 && (
                      <p className="text-sm text-slate-400 text-center py-4">
                        No items yet. Add your first item above.
                      </p>
                    )}
                  </div>
                </div>
              )}

              {/* Sharing Section (only for existing notes) */}
              {editingNote && (
                <div className="pt-4 border-t border-slate-200 dark:border-white/10 space-y-4">
                  <h4 className="text-sm font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2 font-mono">
                    <Share2 size={14} /> Share Note
                  </h4>
                  
                  {partnerships.length === 0 ? (
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      No partners connected. Add partners in Settings ΓåÆ Collaboration.
                    </p>
                  ) : availablePartners.length > 0 ? (
                    <div className="flex gap-2">
                      <Select
                        value={selectedPartnerId}
                        onChange={(value) => setSelectedPartnerId(value)}
                        options={[
                          { value: '', label: 'Choose a partner...' },
                          ...availablePartners.map(p => ({
                            value: p.partnerId,
                            label: p.partnerName || p.partnerEmail,
                          })),
                        ]}
                        currentTheme={currentTheme}
                        className="flex-1"
                      />
                      <Button
                        variant="primary"
                        onClick={handleShareNote}
                        disabled={!selectedPartnerId}
                      >
                        <UserPlus size={16} />
                      </Button>
                    </div>
                  ) : (
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      Shared with all connected partners.
                    </p>
                  )}

                  {/* Current Shares */}
                  {editingNote.isShared && noteShares[editingNote.id]?.length > 0 && (
                    <div className="space-y-2">
                      <p className="text-xs font-medium text-slate-500 uppercase tracking-wide">Shared With</p>
                      {noteShares[editingNote.id].map((share) => (
                        <div
                          key={share.id}
                          className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-white/10"
                        >
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-brand-500/10 flex items-center justify-center text-brand-500">
                              <User size={16} />
                            </div>
                            <div>
                              <p className="text-sm font-medium text-slate-800 dark:text-slate-200">
                                {share.sharedWithName || share.sharedWithEmail}
                              </p>
                              {share.sharedWithName && (
                                <p className="text-xs text-slate-500">{share.sharedWithEmail}</p>
                              )}
                            </div>
                          </div>
                          <button
                            onClick={() => handleUnshareNote(share.id)}
                            className="p-1.5 rounded-lg text-slate-400 hover:bg-red-500/10 hover:text-red-500 transition-colors"
                            aria-label="Remove share"
                          >
                            <X size={16} />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Editor Footer */}
            <div className="p-6 border-t border-slate-200 dark:border-white/10 flex items-center justify-between bg-slate-50 dark:bg-slate-800/50">
              <div>
                {editingNote && (
                  <Button
                    variant="danger"
                    onClick={() => handleDeleteNote(editingNote.id)}
                    className="flex items-center gap-2"
                  >
                    <Trash2 size={16} />
                    Delete
                  </Button>
                )}
              </div>
              <div className="flex gap-3">
                <Button variant="secondary" onClick={() => { setIsEditorOpen(false); resetForm(); }}>
                  Cancel
                </Button>
                <Button variant="primary" onClick={handleSaveNote}>
                  <Save size={16} className="mr-2" />
                  {editingNote ? 'Update' : 'Create'}
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default React.memo(NotesManager);

import React, { useState } from 'react';
import Button from './Button';
import { X, Calendar, RefreshCw } from 'lucide-react';
import { RecurrenceConfig } from '../types';

interface RecurringPlanModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (config: RecurrenceConfig) => void;
  initialConfig?: RecurrenceConfig;
}

const RecurringPlanModal: React.FC<RecurringPlanModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialConfig 
}) => {
  const [frequency, setFrequency] = useState<RecurrenceConfig['frequency']>(initialConfig?.frequency || 'weekly');
  const [interval, setInterval] = useState(initialConfig?.interval || 1);
  const [selectedDays, setSelectedDays] = useState<number[]>(initialConfig?.days || [1, 2, 3, 4, 5]); // Default Mon-Fri
  
  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      frequency,
      interval,
      days: frequency === 'weekly' ? selectedDays : undefined,
    });
    onClose();
  };

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) 
        ? prev.filter(d => d !== day)
        : [...prev, day].sort()
    );
  };

  const weekDays = [
    { label: 'S', value: 0 },
    { label: 'M', value: 1 },
    { label: 'T', value: 2 },
    { label: 'W', value: 3 },
    { label: 'T', value: 4 },
    { label: 'F', value: 5 },
    { label: 'S', value: 6 },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white dark:bg-slate-900 rounded-2xl w-full max-w-md shadow-xl border border-slate-200 dark:border-white/10 overflow-hidden">
        
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-200 dark:border-white/5">
          <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            <RefreshCw size={20} className="text-brand-500" />
            Recurring Plan Settings
          </h3>
          <button onClick={onClose} className="p-1 rounded-full hover:bg-slate-100 dark:hover:bg-white/5 transition-colors">
            <X size={20} className="text-slate-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          
          {/* Frequency */}
          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
              Repeat Frequency
            </label>
            <div className="grid grid-cols-3 gap-2">
              {['daily', 'weekly', 'monthly'].map((freq) => (
                <button
                  key={freq}
                  type="button"
                  onClick={() => setFrequency(freq as any)}
                  className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${
                    frequency === freq
                      ? 'bg-brand-500 text-white border-brand-500'
                      : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-white/10 hover:border-brand-500/50'
                  }`}
                >
                  {freq.charAt(0).toUpperCase() + freq.slice(1)}
                </button>
              ))}
            </div>
          </div>

          {/* Weekly Options */}
          {frequency === 'weekly' && (
            <div className="space-y-3 animate-fade-in">
              <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                Repeat On
              </label>
              <div className="flex justify-between gap-1">
                {weekDays.map((day) => (
                  <button
                    key={day.value}
                    type="button"
                    onClick={() => toggleDay(day.value)}
                    className={`w-10 h-10 rounded-full text-sm font-bold transition-all ${
                      selectedDays.includes(day.value)
                        ? 'bg-brand-500 text-white shadow-lg shadow-brand-500/25'
                        : 'bg-slate-100 dark:bg-white/5 text-slate-500 hover:bg-slate-200 dark:hover:bg-white/10'
                    }`}
                  >
                    {day.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Interval */}
          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
              Interval
            </label>
            <div className="flex items-center gap-2">
              <span className="text-slate-500">Every</span>
              <input
                type="number"
                min="1"
                max="99"
                value={interval}
                onChange={(e) => setInterval(parseInt(e.target.value) || 1)}
                className="w-16 px-3 py-2 rounded-lg border border-slate-200 dark:border-white/10 bg-white dark:bg-slate-800 text-center font-bold outline-none focus:border-brand-500"
              />
              <span className="text-slate-500">
                {frequency === 'daily' ? 'day(s)' : frequency === 'weekly' ? 'week(s)' : 'month(s)'}
              </span>
            </div>
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <Button variant="ghost" type="button" onClick={onClose}>
              Cancel
            </Button>
            <Button variant="primary" type="submit">
              Save Recurring Rule
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RecurringPlanModal;

import React, { useState, useEffect } from 'react';
import { Routine, RoutinePattern, WeekdayPattern, IntervalPattern, CyclePattern, CycleItem } from '../types';
import Button from './Button';
import Input from './Input';
import TimePickerDropdown from './TimePickerDropdown';
import { X, Plus, Trash2, GripVertical, Clock, Bell, Calendar, Repeat, CheckCircle2 } from 'lucide-react';
import * as RoutineService from '../services/routineService';

interface RoutineEditorProps {
  routine?: Routine;
  isOpen: boolean;
  onClose: () => void;
  onSave: (routine: Routine) => void;
  onDelete?: (id: string) => void;
}

const DAY_NAMES = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const FULL_DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const CYCLE_COLORS = [
  '#EF4444', '#F97316', '#F59E0B', '#84CC16', '#10B981', 
  '#06B6D4', '#3B82F6', '#8B5CF6', '#EC4899', '#6B7280'
];

const RoutineEditor: React.FC<RoutineEditorProps> = ({ routine, isOpen, onClose, onSave, onDelete }) => {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [patternType, setPatternType] = useState<'weekday' | 'interval' | 'cycle'>('weekday');
  
  // Weekday pattern state
  const [selectedDays, setSelectedDays] = useState<number[]>([1, 2, 3, 4, 5]);
  
  // Interval pattern state
  const [intervalEvery, setIntervalEvery] = useState(2);
  const [intervalStartDate, setIntervalStartDate] = useState(new Date().toISOString().slice(0, 10));
  
  // Cycle pattern state
  const [cycleItems, setCycleItems] = useState<CycleItem[]>([
    { name: 'Day 1', color: CYCLE_COLORS[0] },
    { name: 'Day 2', color: CYCLE_COLORS[1] }
  ]);
  const [cycleStartDate, setCycleStartDate] = useState(new Date().toISOString().slice(0, 10));
  const [newCycleItemName, setNewCycleItemName] = useState('');
  
  // Time and notification
  const [time, setTime] = useState('09:00');
  const [duration, setDuration] = useState<number | ''>(60);
  const [isActive, setIsActive] = useState(true);
  const [notificationEnabled, setNotificationEnabled] = useState<boolean | undefined>(undefined);
  const [notificationMinutesBefore, setNotificationMinutesBefore] = useState<number | undefined>(undefined);

  // Load routine data
  useEffect(() => {
    if (routine) {
      setName(routine.name);
      setDescription(routine.description || '');
      setPatternType(routine.pattern.type);
      setTime(routine.time || '09:00');
      setDuration(routine.duration || 60);
      setIsActive(routine.isActive);
      setNotificationEnabled(routine.notificationEnabled);
      setNotificationMinutesBefore(routine.notificationMinutesBefore);
      
      if (routine.pattern.type === 'weekday') {
        setSelectedDays((routine.pattern as WeekdayPattern).days);
      } else if (routine.pattern.type === 'interval') {
        const p = routine.pattern as IntervalPattern;
        setIntervalEvery(p.every);
        setIntervalStartDate(new Date(p.startDate).toISOString().slice(0, 10));
      } else if (routine.pattern.type === 'cycle') {
        const p = routine.pattern as CyclePattern;
        setCycleItems(p.items);
        setCycleStartDate(new Date(p.startDate).toISOString().slice(0, 10));
      }
    } else {
      // Reset to defaults
      setName('');
      setDescription('');
      setPatternType('weekday');
      setSelectedDays([1, 2, 3, 4, 5]);
      setIntervalEvery(2);
      setIntervalStartDate(new Date().toISOString().slice(0, 10));
      setCycleItems([
        { name: 'Day 1', color: CYCLE_COLORS[0] },
        { name: 'Day 2', color: CYCLE_COLORS[1] }
      ]);
      setCycleStartDate(new Date().toISOString().slice(0, 10));
      setTime('09:00');
      setDuration(60);
      setIsActive(true);
      setNotificationEnabled(undefined);
      setNotificationMinutesBefore(undefined);
    }
  }, [routine, isOpen]);

  if (!isOpen) return null;

  const toggleDay = (day: number) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day].sort()
    );
  };

  const addCycleItem = () => {
    if (newCycleItemName.trim()) {
      setCycleItems([...cycleItems, { 
        name: newCycleItemName.trim(), 
        color: CYCLE_COLORS[cycleItems.length % CYCLE_COLORS.length] 
      }]);
      setNewCycleItemName('');
    }
  };

  const removeCycleItem = (index: number) => {
    setCycleItems(cycleItems.filter((_, i) => i !== index));
  };

  const updateCycleItemName = (index: number, newName: string) => {
    setCycleItems(cycleItems.map((item, i) => 
      i === index ? { ...item, name: newName } : item
    ));
  };

  const updateCycleItemColor = (index: number, newColor: string) => {
    setCycleItems(cycleItems.map((item, i) => 
      i === index ? { ...item, color: newColor } : item
    ));
  };

  const applyPreset = (preset: { name: string; pattern: RoutinePattern }) => {
    setName(preset.name);
    setPatternType(preset.pattern.type);
    
    if (preset.pattern.type === 'weekday') {
      setSelectedDays((preset.pattern as WeekdayPattern).days);
    } else if (preset.pattern.type === 'interval') {
      setIntervalEvery((preset.pattern as IntervalPattern).every);
    } else if (preset.pattern.type === 'cycle') {
      setCycleItems((preset.pattern as CyclePattern).items);
    }
  };

  const handleSave = () => {
    if (!name.trim()) return;
    
    let pattern: RoutinePattern;
    
    if (patternType === 'weekday') {
      pattern = { type: 'weekday', days: selectedDays };
    } else if (patternType === 'interval') {
      pattern = { 
        type: 'interval', 
        every: intervalEvery, 
        startDate: new Date(intervalStartDate).toISOString() 
      };
    } else {
      pattern = { 
        type: 'cycle', 
        items: cycleItems, 
        startDate: new Date(cycleStartDate).toISOString() 
      };
    }
    
    const routineData: Routine = {
      id: routine?.id || crypto.randomUUID(),
      name: name.trim(),
      description: description.trim() || undefined,
      pattern,
      time,
      duration: duration === '' ? undefined : Number(duration),
      isActive,
      notificationEnabled,
      notificationMinutesBefore,
      createdAt: routine?.createdAt || new Date().toISOString()
    };
    
    onSave(routineData);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300">
      <div className="absolute inset-0 bg-black/60 dark:bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative glass rounded-2xl w-full max-w-xl max-h-[85vh] overflow-hidden flex flex-col shadow-2xl animate-scale-in">
        
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 dark:border-white/5 bg-white/50 dark:bg-slate-900/50">
          <div className="flex items-center gap-3">
            <Repeat className="text-emerald-500" size={20} />
            <h2 className="text-lg font-semibold text-slate-800 dark:text-slate-100 tracking-tight">
              {routine ? 'Edit Routine' : 'New Routine'}
            </h2>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-800 dark:hover:text-white transition-colors p-1 rounded-full hover:bg-black/5 dark:hover:bg-white/5" aria-label="Close editor">
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-6">
          
          {/* Presets */}
          {!routine && (
            <div className="space-y-2">
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 ml-1">Quick Presets</label>
              <div className="flex flex-wrap gap-2">
                {RoutineService.PRESET_PATTERNS.slice(0, 4).map((preset) => (
                  <button
                    key={preset.name}
                    onClick={() => applyPreset(preset)}
                    className="px-3 py-1.5 rounded-lg text-xs font-medium bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-emerald-100 dark:hover:bg-emerald-900/30 hover:text-emerald-700 dark:hover:text-emerald-300 transition-colors border border-transparent hover:border-emerald-300 dark:hover:border-emerald-700"
                  >
                    {preset.name}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Name */}
          <Input 
            label="ROUTINE NAME" 
            placeholder="E.g. Morning Workout, Work Hours" 
            value={name} 
            onChange={e => setName(e.target.value)} 
            autoFocus
          />

          {/* Description */}
          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-2 ml-1">Description (Optional)</label>
            <textarea 
              className="w-full bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 min-h-[60px] resize-none transition-all hover:border-slate-400 dark:hover:border-slate-500"
              placeholder="What's this routine for?"
              value={description}
              onChange={e => setDescription(e.target.value)}
            />
          </div>

          {/* Pattern Type Selector */}
          <div className="space-y-3">
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 ml-1">Pattern Type</label>
            <div className="flex bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-xl p-1">
              <button 
                onClick={() => setPatternType('weekday')}
                className={`flex-1 px-4 py-2.5 text-sm font-medium rounded-lg transition-all ${patternType === 'weekday' ? 'bg-emerald-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
              >
                Weekdays
              </button>
              <button 
                onClick={() => setPatternType('interval')}
                className={`flex-1 px-4 py-2.5 text-sm font-medium rounded-lg transition-all ${patternType === 'interval' ? 'bg-emerald-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
              >
                Interval
              </button>
              <button 
                onClick={() => setPatternType('cycle')}
                className={`flex-1 px-4 py-2.5 text-sm font-medium rounded-lg transition-all ${patternType === 'cycle' ? 'bg-emerald-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
              >
                Cycle
              </button>
            </div>
          </div>

          {/* Weekday Pattern */}
          {patternType === 'weekday' && (
            <div className="bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5 space-y-3">
              <label className="block text-sm font-medium text-slate-600 dark:text-slate-300">Select Days</label>
              <div className="flex gap-2">
                {DAY_NAMES.map((day, index) => (
                  <button
                    key={index}
                    onClick={() => toggleDay(index)}
                    title={FULL_DAY_NAMES[index]}
                    className={`w-10 h-10 rounded-lg text-sm font-bold transition-all ${
                      selectedDays.includes(index)
                        ? 'bg-emerald-500 text-white shadow-md'
                        : 'bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 border border-slate-200 dark:border-slate-600'
                    }`}
                  >
                    {day}
                  </button>
                ))}
              </div>
              <div className="flex gap-2 pt-2">
                <button
                  onClick={() => setSelectedDays([1, 2, 3, 4, 5])}
                  className="text-xs text-emerald-600 dark:text-emerald-400 hover:underline"
                >
                  Weekdays
                </button>
                <span className="text-slate-300 dark:text-slate-600">|</span>
                <button
                  onClick={() => setSelectedDays([0, 6])}
                  className="text-xs text-emerald-600 dark:text-emerald-400 hover:underline"
                >
                  Weekends
                </button>
                <span className="text-slate-300 dark:text-slate-600">|</span>
                <button
                  onClick={() => setSelectedDays([0, 1, 2, 3, 4, 5, 6])}
                  className="text-xs text-emerald-600 dark:text-emerald-400 hover:underline"
                >
                  All
                </button>
              </div>
            </div>
          )}

          {/* Interval Pattern */}
          {patternType === 'interval' && (
            <div className="bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5 space-y-4">
              <div className="flex items-center gap-3">
                <span className="text-sm text-slate-600 dark:text-slate-300">Every</span>
                <input
                  type="number"
                  min="1"
                  max="365"
                  value={intervalEvery}
                  onChange={e => setIntervalEvery(parseInt(e.target.value) || 1)}
                  className="w-20 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-center text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                />
                <span className="text-sm text-slate-600 dark:text-slate-300">day(s)</span>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">Starting from</label>
                <input
                  type="date"
                  value={intervalStartDate}
                  onChange={e => setIntervalStartDate(e.target.value)}
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50 [color-scheme:light] dark:[color-scheme:dark]"
                />
              </div>
            </div>
          )}

          {/* Cycle Pattern */}
          {patternType === 'cycle' && (
            <div className="bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5 space-y-4">
              <label className="block text-sm font-medium text-slate-600 dark:text-slate-300">Cycle Items (in order)</label>
              
              <div className="space-y-2">
                {cycleItems.map((item, index) => (
                  <div key={index} className="flex items-center gap-2 bg-white dark:bg-slate-800 p-2 rounded-lg border border-slate-200 dark:border-slate-600">
                    <GripVertical size={14} className="text-slate-400" />
                    <div 
                      className="w-6 h-6 rounded-full cursor-pointer border-2 border-white shadow"
                      style={{ backgroundColor: item.color || CYCLE_COLORS[0] }}
                      onClick={() => {
                        const currentIndex = CYCLE_COLORS.indexOf(item.color || CYCLE_COLORS[0]);
                        const nextColor = CYCLE_COLORS[(currentIndex + 1) % CYCLE_COLORS.length];
                        updateCycleItemColor(index, nextColor);
                      }}
                      title="Click to change color"
                    />
                    <input
                      type="text"
                      value={item.name}
                      onChange={e => updateCycleItemName(index, e.target.value)}
                      className="flex-1 bg-transparent border-none focus:ring-0 p-0 text-sm text-slate-800 dark:text-slate-200"
                      placeholder="Item name"
                    />
                    <span className="text-xs text-slate-400">Day {index + 1}</span>
                    {cycleItems.length > 2 && (
                      <button onClick={() => removeCycleItem(index)} className="text-slate-400 hover:text-red-500 p-1" aria-label="Remove cycle item">
                        <Trash2 size={14} />
                      </button>
                    )}
                  </div>
                ))}
              </div>

              <div className="flex gap-2">
                <input
                  type="text"
                  value={newCycleItemName}
                  onChange={e => setNewCycleItemName(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && addCycleItem()}
                  placeholder="Add cycle item..."
                  className="flex-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                />
                <Button variant="secondary" size="sm" onClick={addCycleItem}>
                  <Plus size={16} />
                </Button>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">Cycle starts from</label>
                <input
                  type="date"
                  value={cycleStartDate}
                  onChange={e => setCycleStartDate(e.target.value)}
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50 [color-scheme:light] dark:[color-scheme:dark]"
                />
              </div>

              {/* Preset cycles */}
              <div className="pt-2 border-t border-slate-200 dark:border-slate-700">
                <p className="text-xs text-slate-500 mb-2">Quick presets:</p>
                <div className="flex flex-wrap gap-2">
                  {RoutineService.PRESET_PATTERNS.filter(p => p.pattern.type === 'cycle').map((preset) => (
                    <button
                      key={preset.name}
                      onClick={() => {
                        const p = preset.pattern as CyclePattern;
                        setCycleItems(p.items);
                        setName(preset.name);
                      }}
                      className="px-2 py-1 rounded text-xs font-medium bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-100 dark:hover:bg-emerald-900/40 transition-colors"
                    >
                      {preset.name}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Time & Duration */}
          <div className="grid grid-cols-2 gap-4 bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5">
            <TimePickerDropdown
              label="Time"
              value={time}
              onChange={setTime}
            />
            <div>
              <label className="flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">
                Duration (min)
              </label>
              <input
                type="number"
                min="0"
                placeholder="60"
                value={duration}
                onChange={e => setDuration(e.target.value === '' ? '' : parseInt(e.target.value))}
                className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
              />
            </div>
          </div>

          {/* Active Toggle */}
          <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-black/20 rounded-2xl border border-slate-200 dark:border-white/5">
            <div className="flex items-center gap-3">
              <CheckCircle2 size={20} className={isActive ? 'text-emerald-500' : 'text-slate-400'} />
              <div>
                <p className="font-medium text-slate-800 dark:text-slate-200">Active</p>
                <p className="text-xs text-slate-500">Show this routine on calendar</p>
              </div>
            </div>
            <button
              onClick={() => setIsActive(!isActive)}
              className={`relative w-12 h-6 rounded-full transition-colors duration-200 ${isActive ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-600'}`}
              aria-label={isActive ? 'Deactivate routine' : 'Activate routine'}
            >
              <div className={`absolute top-1 left-1 w-4 h-4 rounded-full bg-white shadow-md transition-transform duration-200 ${isActive ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>

          {/* Notification */}
          <div className="bg-slate-50 dark:bg-black/20 rounded-2xl border border-slate-200 dark:border-white/5 overflow-hidden">
            <div className="flex items-center justify-between p-4">
              <div className="flex items-center gap-3">
                <Bell size={20} className={notificationEnabled ? 'text-amber-500' : 'text-slate-400'} />
                <div>
                  <p className="font-medium text-slate-800 dark:text-slate-200">Notification</p>
                  <p className="text-xs text-slate-500">
                    {notificationEnabled === undefined ? 'Use global settings' :
                     notificationEnabled ? 'Enabled' : 'Disabled'}
                  </p>
                </div>
              </div>
              <button
                onClick={() => {
                  const newValue = notificationEnabled === undefined ? true : notificationEnabled === true ? false : undefined;
                  setNotificationEnabled(newValue);
                }}
                className={`relative w-12 h-6 rounded-full transition-colors duration-200 ${
                  notificationEnabled === true ? 'bg-amber-500' : 
                  notificationEnabled === false ? 'bg-slate-300 dark:bg-slate-600' :
                  'bg-gradient-to-r from-slate-300 to-amber-400 dark:from-slate-600 dark:to-amber-500'
                }`}
                aria-label={notificationEnabled === true ? 'Disable notification' : notificationEnabled === false ? 'Use global settings' : 'Enable notification'}
              >
                <div className={`absolute top-1 left-1 w-4 h-4 rounded-full bg-white shadow-md transition-transform duration-200 ${
                  notificationEnabled === true ? 'translate-x-6' : 
                  notificationEnabled === false ? 'translate-x-0' :
                  'translate-x-3'
                }`} />
              </button>
            </div>

            {/* Notification Timing - Show when enabled or using global settings */}
            {notificationEnabled !== false && (
              <div className="px-4 pb-4 pt-2 border-t border-slate-200 dark:border-white/10">
                <label className="block text-xs font-medium text-slate-600 dark:text-slate-400 mb-2">
                  Notify me before routine starts
                </label>
                <select
                  value={notificationMinutesBefore ?? 15}
                  onChange={(e) => setNotificationMinutesBefore(parseInt(e.target.value))}
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-amber-500/50 cursor-pointer"
                >
                  <option value={5}>5 minutes</option>
                  <option value={10}>10 minutes</option>
                  <option value={15}>15 minutes</option>
                  <option value={30}>30 minutes</option>
                  <option value={60}>1 hour</option>
                </select>
              </div>
            )}
          </div>

        </div>

        {/* Footer */}
        <div className="p-6 border-t border-slate-200 dark:border-white/5 bg-white/80 dark:bg-slate-900/80 flex justify-between items-center z-10">
          {routine && onDelete ? (
            <Button variant="danger" size="icon" onClick={() => onDelete(routine.id)} className="bg-red-500/10 hover:bg-red-500/20 text-red-500 dark:text-red-400" aria-label="Delete routine">
              <Trash2 size={18} />
            </Button>
          ) : <div />}
          
          <div className="flex gap-3">
            <Button variant="ghost" onClick={onClose} className="hover:bg-slate-100 dark:hover:bg-white/5 text-slate-600 dark:text-slate-400">Cancel</Button>
            <Button variant="primary" onClick={handleSave} className="shadow-lg shadow-emerald-500/25 bg-emerald-500 hover:bg-emerald-600">Save Routine</Button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default React.memo(RoutineEditor);

import React from 'react';
import { Task, TaskPriority, TaskStatus } from '../types';
import { Calendar, CheckCircle2, Circle, MoreVertical, Sparkles, Bell, Users, Lock, Clock, MapPin, Play } from 'lucide-react';
import Button from './Button';
import { formatDateShort, formatTime, isPast, parseDate } from '../utils/date';

interface TaskCardProps {
  task: Task;
  allTasks?: Task[];
  onEdit: (task: Task) => void;
  onToggleStatus: (task: Task) => void;
  onAIAnalysis?: (task: Task) => void;
  onFocus?: (task: Task) => void;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, allTasks = [], onEdit, onToggleStatus, onAIAnalysis, onFocus }) => {
  const isDone = task.status === TaskStatus.DONE;

  // Check dependencies - early exit if no dependencies
  const hasDependencies = task.dependencyIds && task.dependencyIds.length > 0;
  const unfinishedDependencies = hasDependencies
    ? task.dependencyIds.map(id => allTasks.find(t => t.id === id)).filter(t => t && t.status !== TaskStatus.DONE)
    : [];
  const isBlocked = unfinishedDependencies.length > 0;
  const blockedBy = unfinishedDependencies?.[0]?.title;

  // Subtask progress
  const totalSub = task.subtasks.length;
  const doneSub = task.subtasks.filter(s => s.isCompleted).length;
  const progressPercent = totalSub > 0 ? (doneSub / totalSub) * 100 : 0;

  const typeLabel = task.type === 'EVENT' ? 'Event' : task.type === 'APPOINTMENT' ? 'Appt' : 'Task';

  return (
    <div
      className={`group relative glass-panel rounded-2xl p-5 transition-all duration-300 hover:shadow-xl hover:-translate-y-0.5 ${isDone ? 'opacity-60 grayscale-[0.5]' : ''} ${isBlocked ? 'border-red-500/30 bg-red-500/5' : ''}`}
      onClick={() => onEdit(task)}
    >
      <div className="flex items-start gap-4">
        {/* Checkbox Area */}
        <button
          onClick={(e) => {
            e.stopPropagation();
            if (!isBlocked) onToggleStatus(task);
          }}
          disabled={isBlocked && !isDone}
          aria-label={isBlocked ? "Task blocked" : isDone ? "Mark as incomplete" : "Mark as complete"}
          className={`mt-0.5 flex-shrink-0 transition-all duration-200 hover:scale-110 active:scale-95 ${isBlocked && !isDone
              ? 'text-red-400/50 cursor-not-allowed'
              : isDone
                ? 'text-emerald-500 drop-shadow-sm'
                : 'text-slate-400 hover:text-brand-500'
            }`}
        >
          {isBlocked && !isDone ? <Lock size={22} /> : (isDone ? <CheckCircle2 size={24} weight="fill" /> : <Circle size={24} />)}
        </button>

        {/* Content Area */}
        <div className="flex-1 min-w-0 pr-16 sm:pr-20">
          {/* Shared/Priority Indicators - Absolute positioned */}
          <div className="absolute top-4 right-4 flex items-center gap-1.5 sm:right-14">
            {task.type !== 'TASK' && (
              <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded uppercase ${task.type === 'EVENT' ? 'bg-brand-500/10 text-brand-600 dark:text-brand-300' : 'bg-purple-500/10 text-purple-600 dark:text-purple-300'
                }`}>
                {typeLabel}
              </span>
            )}
            {task.isShared && <Users size={14} className="text-blue-500 dark:text-blue-400" />}
            <div className={`w-2.5 h-2.5 rounded-full ${task.priority === TaskPriority.HIGH ? 'bg-red-500 shadow-sm' :
                task.priority === TaskPriority.MEDIUM ? 'bg-yellow-500' : 'bg-green-500'
              }`} />
          </div>

          <h3 className={`font-semibold text-[15px] truncate pr-16 sm:pr-0 ${isDone ? 'text-slate-400 dark:text-slate-500 line-through decoration-slate-400' : 'text-slate-800 dark:text-slate-100'} ${isBlocked && !isDone ? 'text-slate-500' : ''}`}>
            {task.title}
          </h3>

          <p className="text-sm text-slate-500 dark:text-slate-400 mb-3 line-clamp-2 leading-relaxed">
            {task.description || "No description"}
          </p>

          {isBlocked && (
            <div className="bg-red-500/5 border border-red-500/20 rounded-lg p-2 mb-3 flex items-start gap-2">
              <Lock size={12} className="text-red-400 mt-0.5" />
              <p className="text-xs text-red-500 dark:text-red-300">
                Waiting for: <span className="font-semibold">{blockedBy}</span>
                {unfinishedDependencies.length > 1 && ` +${unfinishedDependencies.length - 1}`}
              </p>
            </div>
          )}

          {/* Subtask Progress Bar */}
          {totalSub > 0 && !isDone && (
            <div className="mb-3">
              <div className="flex justify-between text-[10px] text-slate-400 dark:text-slate-500 mb-1 uppercase tracking-wider font-semibold">
                <span>Progress</span>
                <span>{Math.round(progressPercent)}%</span>
              </div>
              <div className="h-1.5 w-full bg-slate-200 dark:bg-slate-700/50 rounded-full overflow-hidden">
                <div
                  className="h-full bg-brand-500 rounded-full transition-all duration-500 ease-out"
                  style={{ width: `${progressPercent}%` }}
                />
              </div>
            </div>
          )}

          <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-slate-500 dark:text-slate-400 font-medium">
            {task.reminderTime && (
              <div className={`flex items-center gap-1.5 px-2 py-1 rounded-md border ${isPast(task.reminderTime) ? 'bg-red-500/5 border-red-500/20 text-red-500 dark:text-red-400' : 'bg-yellow-500/5 border-yellow-500/20 text-yellow-600 dark:text-yellow-500'}`}>
                <Bell size={12} />
                <span>{formatDateShort(task.reminderTime)} {formatTime(task.reminderTime)}</span>
              </div>
            )}

            {!task.reminderTime && task.dueDate && (
              <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/5">
                <Calendar size={12} />
                <span>{formatDateShort(task.dueDate)}</span>
              </div>
            )}

            {task.duration && (
              <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/5">
                <Clock size={12} />
                <span>{task.duration}m</span>
              </div>
            )}

            {task.location && (
              <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/5">
                <MapPin size={12} />
                <span className="truncate max-w-[100px]">{task.location}</span>
              </div>
            )}

            {task.tags.map(tag => (
              <span key={tag} className="bg-slate-100 dark:bg-white/5 px-2 py-1 rounded-md border border-slate-200 dark:border-white/5 hover:bg-slate-200 dark:hover:bg-white/10 transition-colors">#{tag}</span>
            ))}
          </div>
        </div>

        {/* Hover Actions - Visible on group hover */}
        <div className="absolute top-4 right-4 flex flex-col gap-1 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-all duration-200 translate-x-2 group-hover:translate-x-0 focus-within:translate-x-0">
          <Button
            variant="secondary"
            size="icon"
            className="h-8 w-8 bg-white/80 dark:bg-slate-800/80 backdrop-blur"
            onClick={(e) => { e.stopPropagation(); onEdit(task); }}
            aria-label="Edit task"
          >
            <MoreVertical size={14} />
          </Button>
          {onAIAnalysis && !isDone && (
            <Button
              variant="secondary"
              size="icon"
              className="h-8 w-8 text-purple-500 dark:text-purple-400 border-purple-200 dark:border-purple-500/20 hover:bg-purple-50 dark:hover:bg-purple-500/10"
              onClick={(e) => { e.stopPropagation(); onAIAnalysis(task); }}
              title="AI Breakdown"
              aria-label="AI Breakdown"
            >
              <Sparkles size={14} />
            </Button>
          )}
          {onFocus && !isDone && (
            <Button
              variant="secondary"
              size="icon"
              className="h-8 w-8 text-brand-500 dark:text-brand-400 border-brand-200 dark:border-brand-500/20 hover:bg-brand-50 dark:hover:bg-brand-500/10"
              onClick={(e) => { e.stopPropagation(); onFocus(task); }}
              title="Start Focus Session"
              aria-label="Start Focus Session"
            >
              <Play size={14} />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
};

export default React.memo(TaskCard);

import React, { useState, useEffect } from 'react';
import { Task, TaskPriority, TaskStatus, SubTask, RecurrenceConfig, TaskType, NotificationSettings } from '../types';
import Button from './Button';
import Input from './Input';
import { X, Plus, Trash2, Wand2, Bell, Link as LinkIcon, Users, Check, Repeat, Calendar, MapPin, Clock, Play } from 'lucide-react';
import { enhanceTaskWithAI } from '../services/geminiService';
import { logger } from '../utils/logger';
import DateTimePicker from './DateTimePicker';
import Select from './Select';
import { useTheme } from '../context/ThemeContext';

interface TaskEditorProps {
  task?: Task;
  availableTasks: Task[]; // For dependency selection
  isOpen: boolean;
  onClose: () => void;
  onSave: (task: Partial<Task>) => void;
  onDelete?: (id: string) => void;
  initialDate?: Date; // For opening from Calendar
  initialType?: TaskType;
  globalNotificationSettings?: NotificationSettings;
  onStartFocus?: () => void;
}

const TaskEditor: React.FC<TaskEditorProps> = ({ task, availableTasks, isOpen, onClose, onSave, onDelete, initialDate, initialType = 'TASK', globalNotificationSettings, onStartFocus }) => {
  const { theme } = useTheme();

  // Helper function to format minutes into a readable string
  const formatMinutesLabel = (minutes: number): string => {
    if (minutes >= 1440) {
      const days = Math.floor(minutes / 1440);
      return days === 1 ? '1 day before' : `${days} days before`;
    } else if (minutes >= 60) {
      const hours = Math.floor(minutes / 60);
      return hours === 1 ? '1 hr before' : `${hours} hrs before`;
    } else {
      return `${minutes} min before`;
    }
  };

  // Helper function to format date for datetime-local input (without timezone conversion)
  const formatDateTimeLocal = (date: Date | string): string => {
    const d = typeof date === 'string' ? new Date(date) : date;
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  };

  const [type, setType] = useState<TaskType>(initialType);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<TaskPriority>(TaskPriority.MEDIUM);
  const [status, setStatus] = useState<TaskStatus>(TaskStatus.TODO);
  const [subtasks, setSubtasks] = useState<SubTask[]>([]);
  const [newTag, setNewTag] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  
  // New Fields
  const [reminderTime, setReminderTime] = useState('');
  const [dependencyIds, setDependencyIds] = useState<string[]>([]);
  const [isShared, setIsShared] = useState(false);
  const [duration, setDuration] = useState<number | ''>('');
  const [location, setLocation] = useState('');
  
  // Recurrence Fields
  const [recurrenceFreq, setRecurrenceFreq] = useState<'none' | 'daily' | 'weekly' | 'monthly' | 'yearly'>('none');
  const [recurrenceInterval, setRecurrenceInterval] = useState(1);
  const [recurrenceEnd, setRecurrenceEnd] = useState('');

  // Per-task Notification Fields
  const [notificationEnabled, setNotificationEnabled] = useState<boolean | undefined>(undefined);
  const [notificationMode, setNotificationMode] = useState<'relative' | 'absolute'>('relative');
  const [notificationTime, setNotificationTime] = useState('');
  const [notificationMinutesBefore, setNotificationMinutesBefore] = useState<number | undefined>(undefined);
  const [showCustomNotification, setShowCustomNotification] = useState(false);
  const [customNotificationValue, setCustomNotificationValue] = useState(30);
  const [customNotificationUnit, setCustomNotificationUnit] = useState<'minutes' | 'hours' | 'days'>('minutes');

  const [isEnhancing, setIsEnhancing] = useState(false);
  
  // Tag autocomplete states
  const [showTagSuggestions, setShowTagSuggestions] = useState(false);
  const [selectedSuggestionIndex, setSelectedSuggestionIndex] = useState(0);
  
  // Extract all existing tags from available tasks
  const existingTags = React.useMemo(() => {
    const tagSet = new Set<string>();
    availableTasks.forEach(t => t.tags.forEach(tag => tagSet.add(tag)));
    return Array.from(tagSet).sort();
  }, [availableTasks]);
  
  // Filter tags based on input - case sensitive matching
  const suggestedTags = React.useMemo(() => {
    if (!newTag.trim()) return existingTags;
    return existingTags.filter(tag => 
      tag.includes(newTag.trim()) && !tags.includes(tag)
    );
  }, [newTag, existingTags, tags]);

  useEffect(() => {
    if (task) {
      setType(task.type || 'TASK');
      setTitle(task.title);
      setDescription(task.description || '');
      setPriority(task.priority);
      setStatus(task.status);
      setSubtasks(task.subtasks);
      setTags(task.tags);
      setReminderTime(task.reminderTime ? formatDateTimeLocal(task.reminderTime) : (task.dueDate ? formatDateTimeLocal(task.dueDate) : ''));
      setDependencyIds(task.dependencyIds || []);
      setIsShared(task.isShared || false);
      setDuration(task.duration || '');
      setLocation(task.location || '');
      
      if (task.recurrence) {
        setRecurrenceFreq(task.recurrence.frequency);
        setRecurrenceInterval(task.recurrence.interval);
        setRecurrenceEnd(task.recurrence.endDate ? new Date(task.recurrence.endDate).toISOString().slice(0, 10) : '');
      } else {
        setRecurrenceFreq('none');
        setRecurrenceInterval(1);
        setRecurrenceEnd('');
      }
      
      // Load notification settings
      // Load notification settings
      setNotificationEnabled(task.notificationEnabled);
      if (task.notificationTime) {
          setNotificationMode('absolute');
          setNotificationTime(formatDateTimeLocal(task.notificationTime));
          setNotificationMinutesBefore(undefined);
      } else {
          setNotificationMode('relative');
          setNotificationTime('');
          setNotificationMinutesBefore(task.notificationMinutesBefore);
          
          if (task.notificationMinutesBefore && ![5, 15, 60, 720, 1440].includes(task.notificationMinutesBefore)) {
            setShowCustomNotification(true);
            if (task.notificationMinutesBefore >= 1440) {
              setCustomNotificationValue(Math.floor(task.notificationMinutesBefore / 1440));
              setCustomNotificationUnit('days');
            } else if (task.notificationMinutesBefore >= 60) {
              setCustomNotificationValue(Math.floor(task.notificationMinutesBefore / 60));
              setCustomNotificationUnit('hours');
            } else {
              setCustomNotificationValue(task.notificationMinutesBefore);
              setCustomNotificationUnit('minutes');
            }
          } else {
            setShowCustomNotification(false);
          }
      }
    } else {
        // Reset for new task
        setType(initialType);
        setTitle('');
        setDescription('');
        setPriority(TaskPriority.MEDIUM);
        setStatus(TaskStatus.TODO);
        setSubtasks([]);
        setTags([]);
        // If initialDate provided (from Calendar), set it as default reminder/due date
        setReminderTime(initialDate ? formatDateTimeLocal(initialDate) : '');
        setDependencyIds([]);
        setIsShared(false);
        setDuration('');
        setLocation('');
        setRecurrenceFreq('none');
        setRecurrenceInterval(1);
        setRecurrenceEnd('');
        
        // Reset notification settings
        // Reset notification settings
        setNotificationEnabled(undefined);
        setNotificationMode('relative');
        setNotificationTime('');
        setNotificationMinutesBefore(undefined);
        setShowCustomNotification(false);
        setCustomNotificationValue(30);
        setCustomNotificationUnit('minutes');
    }
  }, [task, isOpen, initialDate, initialType]);

  if (!isOpen) return null;

  const handleSave = () => {
    logger.debug('[TaskEditor] Save clicked', { title });
    if (!title.trim()) {
      console.warn('[TaskEditor] Title is empty, cannot save');
      return;
    }
    
    const recurrence: RecurrenceConfig | undefined = recurrenceFreq !== 'none' ? {
      frequency: recurrenceFreq,
      interval: recurrenceInterval,
      endDate: recurrenceEnd ? new Date(recurrenceEnd).toISOString() : undefined
    } : undefined;

    onSave({
      id: task?.id,
      type,
      title,
      description,
      priority,
      status,
      subtasks,
      tags,
      dueDate: reminderTime ? new Date(reminderTime).toISOString() : undefined,
      reminderTime: reminderTime ? new Date(reminderTime).toISOString() : undefined,
      dependencyIds,
      isShared,
      recurrence,
      duration: duration === '' ? undefined : Number(duration),
      location,

      notificationEnabled,
      notificationMinutesBefore: notificationMode === 'relative' ? notificationMinutesBefore : undefined,
      notificationTime: notificationMode === 'absolute' && notificationTime ? new Date(notificationTime).toISOString() : undefined
    });
    onClose();
  };

  const handleAddSubtask = () => {
      setSubtasks([...subtasks, { id: crypto.randomUUID(), title: '', isCompleted: false }]);
  };

  const handleUpdateSubtask = (id: string, val: string) => {
      setSubtasks(subtasks.map(s => s.id === id ? { ...s, title: val } : s));
  };

  const handleDeleteSubtask = (id: string) => {
      setSubtasks(subtasks.filter(s => s.id !== id));
  };
  
  const handleToggleSubtask = (id: string) => {
      setSubtasks(subtasks.map(s => s.id === id ? { ...s, isCompleted: !s.isCompleted } : s));
  };

  const handleAddTag = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          e.preventDefault(); // Prevent form submission
          
          // If suggestions are shown and there's a selection, add the suggested tag
          if (showTagSuggestions && suggestedTags.length > 0 && selectedSuggestionIndex >= 0) {
              const selectedTag = suggestedTags[selectedSuggestionIndex];
              if (!tags.includes(selectedTag)) {
                  setTags([...tags, selectedTag]);
              }
              setNewTag('');
              setShowTagSuggestions(false);
              setSelectedSuggestionIndex(0);
          } else if (newTag.trim()) {
              // Otherwise add the typed tag
              if (!tags.includes(newTag.trim())) {
                  setTags([...tags, newTag.trim()]);
              }
              setNewTag('');
              setShowTagSuggestions(false);
          }
      } else if (e.key === 'ArrowDown') {
          e.preventDefault();
          if (suggestedTags.length > 0) {
              setShowTagSuggestions(true);
              setSelectedSuggestionIndex(prev => 
                  prev < suggestedTags.length - 1 ? prev + 1 : 0
              );
          }
      } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          if (suggestedTags.length > 0) {
              setShowTagSuggestions(true);
              setSelectedSuggestionIndex(prev => 
                  prev > 0 ? prev - 1 : suggestedTags.length - 1
              );
          }
      } else if (e.key === 'Escape') {
          setShowTagSuggestions(false);
          setSelectedSuggestionIndex(0);
      }
  };

  const selectSuggestedTag = (tag: string) => {
      if (!tags.includes(tag)) {
          setTags([...tags, tag]);
      }
      setNewTag('');
      setShowTagSuggestions(false);
      setSelectedSuggestionIndex(0);
  };

  const removeTag = (t: string) => {
      setTags(tags.filter(tag => tag !== t));
  };

  const toggleDependency = (id: string) => {
      if (dependencyIds.includes(id)) {
          setDependencyIds(dependencyIds.filter(d => d !== id));
      } else {
          setDependencyIds([...dependencyIds, id]);
      }
  };

  const handleAIEnhance = async () => {
      if (!title) return;
      setIsEnhancing(true);
      
      // Calculate all existing tags from available tasks
      const allExistingTags = Array.from(new Set(availableTasks.flatMap(t => t.tags))) as string[];
      
      const enhancedData = await enhanceTaskWithAI(title, allExistingTags);
      
      if (enhancedData) {
          setDescription(enhancedData.description || description);
          if (enhancedData.priority) setPriority(enhancedData.priority);
          if (enhancedData.tags) setTags([...new Set([...tags, ...enhancedData.tags])]);
          if (enhancedData.subtasks) {
              setSubtasks([...subtasks, ...enhancedData.subtasks]);
          }
      }
      setIsEnhancing(false);
  };

  const isEventOrAppointment = type === 'EVENT' || type === 'APPOINTMENT';

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 sm:p-6 transition-all duration-300">
      <div className="absolute inset-0 bg-black/60 dark:bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative glass rounded-2xl w-full max-w-xl max-h-[85vh] overflow-hidden flex flex-col shadow-2xl animate-scale-in">
        
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 dark:border-white/5 bg-white/50 dark:bg-slate-900/50">
          <div className="flex items-center gap-3">
             <h2 className="text-lg font-semibold text-slate-800 dark:text-slate-100 tracking-tight">{task ? 'Edit' : 'Create New'}</h2>
             <div className="flex bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-lg p-0.5">
                 <button 
                    onClick={() => setType('TASK')}
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${type === 'TASK' ? 'bg-blue-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                 >
                     Task
                 </button>
                 <button 
                    onClick={() => setType('REMINDER')}
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${type === 'REMINDER' ? 'bg-yellow-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                 >
                     Reminder
                 </button>
                 <button 
                    onClick={() => setType('EVENT')}
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${type === 'EVENT' ? 'bg-brand-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                 >
                     Event
                 </button>
                 <button 
                    onClick={() => setType('APPOINTMENT')}
                    className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${type === 'APPOINTMENT' ? 'bg-purple-500 text-white shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                 >
                     Appt
                 </button>
             </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-800 dark:hover:text-white transition-colors p-1 rounded-full hover:bg-black/5 dark:hover:bg-white/5"
            aria-label="Close modal"
          >
            <X size={20} />
          </button>
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto px-6 py-6 space-y-7">
            <div className="space-y-3">
                 <Input 
                    label="TITLE" 
                    placeholder={type === 'TASK' ? "E.g. Redesign homepage" : type === 'REMINDER' ? "E.g. Buy milk" : type === 'EVENT' ? "E.g. Birthday Party" : "E.g. Dentist"} 
                    value={title} 
                    onChange={e => setTitle(e.target.value)} 
                    autoFocus
                    className="text-lg font-medium"
                />
                 {title && !isEnhancing && (
                    <button 
                        onClick={handleAIEnhance} 
                        className="w-full py-2.5 flex items-center justify-center gap-2 bg-gradient-to-r from-purple-500/10 to-indigo-500/10 hover:from-purple-500/20 hover:to-indigo-500/20 text-purple-600 dark:text-purple-400 rounded-xl text-sm font-medium transition-all border border-purple-500/20 hover:border-purple-500/30 group"
                    >
                        <Wand2 size={16} className="group-hover:rotate-12 transition-transform" /> 
                        Auto-Enhance with Gemini AI
                    </button>
                )}
                {isEnhancing && (
                    <div className="w-full py-2.5 flex items-center justify-center gap-2 text-slate-400 text-sm">
                        <Wand2 size={16} className="animate-spin text-purple-400" /> Thinking...
                    </div>
                )}
            </div>

            {/* Tags - Moved to top */}
            <div className="relative">
               <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-2 ml-1 flex items-center gap-2">
                   Tags
                   {newTag && <span className="text-[10px] normal-case font-normal text-brand-500 animate-fade-in">Type tag and press enter</span>}
               </label>
               <div className="flex flex-wrap gap-2 mb-3">
                   {tags.map(tag => (
                       <span key={tag} className="bg-brand-500/10 text-brand-600 dark:text-brand-300 text-xs font-medium px-2.5 py-1 rounded-md flex items-center gap-1.5 border border-brand-500/20">
                           {tag}
                           <button onClick={() => removeTag(tag)} className="hover:text-slate-800 dark:hover:text-white" aria-label={`Remove tag ${tag}`}><X size={12} /></button>
                       </span>
                   ))}
               </div>
               <div className="flex gap-2">
                   <div className="flex-1">
                       <Input 
                           placeholder="Type tag..." 
                           value={newTag} 
                           onChange={e => {
                               setNewTag(e.target.value);
                               setShowTagSuggestions(true);
                               setSelectedSuggestionIndex(0);
                           }}
                           onKeyDown={handleAddTag}
                           onFocus={() => {
                               if (suggestedTags.length > 0) {
                                   setShowTagSuggestions(true);
                               }
                           }}
                           onBlur={() => {
                               // Delay to allow click on suggestion
                               setTimeout(() => setShowTagSuggestions(false), 150);
                           }}
                           className="text-sm py-2"
                           enterKeyHint="done"
                       />
                   </div>
                   <button
                       type="button"
                       onClick={() => {
                           if (showTagSuggestions && suggestedTags.length > 0 && selectedSuggestionIndex >= 0) {
                               const selectedTag = suggestedTags[selectedSuggestionIndex];
                               if (!tags.includes(selectedTag)) {
                                   setTags([...tags, selectedTag]);
                               }
                               setNewTag('');
                               setShowTagSuggestions(false);
                               setSelectedSuggestionIndex(0);
                           } else if (newTag.trim()) {
                               if (!tags.includes(newTag.trim())) {
                                   setTags([...tags, newTag.trim()]);
                               }
                               setNewTag('');
                               setShowTagSuggestions(false);
                           }
                       }}
                       disabled={!newTag.trim() && !(showTagSuggestions && suggestedTags.length > 0)}
                       className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                           newTag.trim() || (showTagSuggestions && suggestedTags.length > 0)
                               ? 'bg-brand-500 text-white shadow-md hover:bg-brand-600 active:scale-95'
                               : 'bg-slate-200 dark:bg-slate-700 text-slate-400 dark:text-slate-500 cursor-not-allowed'
                       }`}
                   >
                       <Plus size={18} />
                   </button>
               </div>
               
               {/* Autocomplete Dropdown */}
               {showTagSuggestions && suggestedTags.length > 0 && (
                   <div className="absolute z-10 w-full mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl max-h-48 overflow-y-auto animate-scale-in">
                       {suggestedTags.map((tag, index) => (
                           <button
                               key={tag}
                               type="button"
                               onClick={() => selectSuggestedTag(tag)}
                               className={`w-full text-left px-4 py-2.5 text-sm transition-colors ${
                                   index === selectedSuggestionIndex
                                       ? 'bg-brand-500/20 text-brand-700 dark:text-brand-300'
                                       : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'
                               }`}
                           >
                               <span className="flex items-center gap-2">
                                   <span className="w-2 h-2 rounded-full bg-brand-500"></span>
                                   {tag}
                               </span>
                           </button>
                       ))}
                   </div>
               )}
            </div>

            <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-2 ml-1">Description</label>
                <textarea 
                    className="w-full bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-xl px-4 py-3 text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-brand-500/50 min-h-[100px] resize-none transition-all hover:border-slate-400 dark:hover:border-slate-500"
                    placeholder="Add more details..."
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                />
            </div>

            {/* Time & Duration Grid */}
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5">
                 <div className="sm:col-span-2">
                    <DateTimePicker
                        label={isEventOrAppointment ? 'Start Date & Time' : 'Due Date & Time'}
                        value={reminderTime}
                        onChange={setReminderTime}
                        placeholder="Select date and time"
                    />
                 </div>
                 
                 {isEventOrAppointment && (
                    <div className="sm:col-span-2 grid grid-cols-2 gap-4">
                        <div>
                             <label className="flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">
                                <Clock size={16} className="text-purple-500" /> Duration (Minutes)
                            </label>
                            <input 
                                type="number"
                                min="0"
                                placeholder="e.g. 60"
                                value={duration}
                                onChange={(e) => setDuration(e.target.value === '' ? '' : parseInt(e.target.value))}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500/50" 
                            />
                        </div>
                        <div>
                             <label className="flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">
                                <MapPin size={16} className="text-red-500" /> Location
                            </label>
                             <input 
                                type="text"
                                placeholder="Add location"
                                value={location}
                                onChange={(e) => setLocation(e.target.value)}
                                className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500/50" 
                            />
                        </div>
                    </div>
                 )}
             </div>

            {/* Per-Task Notification Settings */}
            {reminderTime && (
              <div className="bg-amber-50 dark:bg-amber-900/20 p-4 rounded-2xl border border-amber-200 dark:border-amber-500/20">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2 text-sm font-medium text-amber-700 dark:text-amber-300">
                    <Bell size={16} className="text-amber-500" />
                    Notification for this {type.toLowerCase()}
                  </div>
                  <button
                    onClick={() => {
                      const newValue = notificationEnabled === undefined ? true : notificationEnabled === true ? false : undefined;
                      setNotificationEnabled(newValue);
                    }}
                    className={`relative w-12 h-6 rounded-full transition-colors duration-200 ${
                      notificationEnabled === true ? 'bg-amber-500' : 
                      notificationEnabled === false ? 'bg-slate-300 dark:bg-slate-600' :
                      'bg-gradient-to-r from-slate-300 to-amber-400 dark:from-slate-600 dark:to-amber-500'
                    }`}
                    title={
                      notificationEnabled === undefined ? 'Using global settings' :
                      notificationEnabled ? 'Enabled' : 'Disabled'
                    }
                  >
                    <div className={`absolute top-1 left-1 w-4 h-4 rounded-full bg-white shadow-md transition-transform duration-200 ${
                      notificationEnabled === true ? 'translate-x-6' : 
                      notificationEnabled === false ? 'translate-x-0' :
                      'translate-x-3'
                    }`} />
                  </button>
                </div>
                
                <p className="text-xs text-amber-600 dark:text-amber-400 mb-3">
                  {notificationEnabled === undefined && (
                    globalNotificationSettings?.enabled 
                      ? `ΓÇó Using global notification settings (${formatMinutesLabel(globalNotificationSettings.reminderMinutesBefore)})`
                      : 'ΓÇó Using global notification settings (off)'
                  )}
                  {notificationEnabled === true && 'ΓÇó Notification enabled for this item'}
                  {notificationEnabled === false && 'ΓÇó Notification disabled for this item'}
                </p>

                {(notificationEnabled === undefined || notificationEnabled === true) && (
                  <div className="space-y-3">
                    {/* Notification Mode Toggle */}
                    <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg w-fit">
                        <button
                            onClick={() => {
                              setNotificationMode('relative');
                              // Auto-switch to custom if in default mode
                              if (notificationEnabled === undefined) setNotificationEnabled(true);
                            }}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${
                                notificationMode === 'relative' 
                                ? 'bg-white dark:bg-slate-700 shadow text-slate-800 dark:text-slate-100' 
                                : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                            }`}
                        >
                            Time Before
                        </button>
                        <button
                            onClick={() => {
                                setNotificationMode('absolute');
                                // Auto-switch to custom if in default mode
                                if (notificationEnabled === undefined) setNotificationEnabled(true);
                                // Default absolute time to reminder time if available, or now
                                if (!notificationTime) {
                                  setNotificationTime(reminderTime || new Date().toISOString().slice(0, 16));
                                }
                            }}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${
                                notificationMode === 'absolute' 
                                ? 'bg-white dark:bg-slate-700 shadow text-slate-800 dark:text-slate-100' 
                                : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                            }`}
                        >
                            Specific Time
                        </button>
                    </div>

                    {notificationMode === 'relative' ? (
                        <>
                            <label className="block text-xs font-semibold text-amber-700 dark:text-amber-300">
                              Notify me before
                            </label>
                            <div className="flex flex-wrap gap-2">
                              {[
                                { value: undefined, label: 'Default' },
                                { value: 5, label: '5 min' },
                                { value: 15, label: '15 min' },
                                { value: 60, label: '1 hr' },
                                { value: 720, label: '12 hr' },
                                { value: 1440, label: '1 day' },
                              ].map((option) => (
                                <button
                                  key={option.label}
                                  onClick={() => {
                                    // Auto-switch to custom if in default mode and selecting non-default option
                                    if (notificationEnabled === undefined && option.value !== undefined) {
                                      setNotificationEnabled(true);
                                    }
                                    setNotificationMinutesBefore(option.value);
                                    setShowCustomNotification(false);
                                  }}
                                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                                    !showCustomNotification && notificationMinutesBefore === option.value
                                      ? 'bg-amber-500 text-white shadow-md'
                                      : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-amber-100 dark:hover:bg-slate-700 border border-amber-200 dark:border-slate-600'
                                  }`}
                                >
                                  {option.label}
                                </button>
                              ))}
                              <button
                                onClick={() => {
                                  // Auto-switch to custom if in default mode
                                  if (notificationEnabled === undefined) setNotificationEnabled(true);
                                  setShowCustomNotification(true);
                                  const multiplier = customNotificationUnit === 'days' ? 1440 : customNotificationUnit === 'hours' ? 60 : 1;
                                  setNotificationMinutesBefore(customNotificationValue * multiplier);
                                }}
                                className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                                  showCustomNotification
                                    ? 'bg-amber-500 text-white shadow-md'
                                    : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-amber-100 dark:hover:bg-slate-700 border border-amber-200 dark:border-slate-600'
                                }`}
                              >
                                Custom
                              </button>
                            </div>

                            {showCustomNotification && (
                              <div className="flex items-center gap-2 mt-2 animate-fade-in">
                                <input
                                  type="number"
                                  min="1"
                                  max="999"
                                  value={customNotificationValue}
                                  onChange={(e) => {
                                    const num = parseInt(e.target.value) || 1;
                                    setCustomNotificationValue(num);
                                    const multiplier = customNotificationUnit === 'days' ? 1440 : customNotificationUnit === 'hours' ? 60 : 1;
                                    setNotificationMinutesBefore(num * multiplier);
                                  }}
                                  className="w-16 bg-white dark:bg-slate-800 border border-amber-200 dark:border-slate-600 rounded-lg px-2 py-1.5 text-sm text-center text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-amber-500/50"
                                />
                                <Select
                                  value={customNotificationUnit}
                                  onChange={(value) => {
                                    const unit = value as 'minutes' | 'hours' | 'days';
                                    setCustomNotificationUnit(unit);
                                    const multiplier = unit === 'days' ? 1440 : unit === 'hours' ? 60 : 1;
                                    setNotificationMinutesBefore(customNotificationValue * multiplier);
                                  }}
                                  options={[
                                    { value: 'minutes', label: 'minutes' },
                                    { value: 'hours', label: 'hours' },
                                    { value: 'days', label: 'days' }
                                  ]}
                                  currentTheme={theme}
                                  className="w-24"
                                />
                                <span className="text-xs text-amber-600 dark:text-amber-400">before</span>
                              </div>
                            )}
                        </>
                    ) : (
                        <div className="animate-fade-in">
                            <label className="block text-xs font-semibold text-amber-700 dark:text-amber-300 mb-2">
                                Notify exactly at
                            </label>
                            <DateTimePicker
                                value={notificationTime}
                                onChange={setNotificationTime}
                                placeholder="Select notification time"
                            />
                             <p className="mt-2 text-xs text-amber-600/80 dark:text-amber-400/80">
                                This notification time is fixed and won't change even if you reschedule the task.
                            </p>
                        </div>
                    )}
                  </div>
                )}
              </div>
            )}

            <div className="grid grid-cols-2 gap-6">
                <div>
                    <Select
                        label="Priority"
                        value={priority}
                        onChange={(value) => setPriority(value as TaskPriority)}
                        options={Object.values(TaskPriority).map(p => ({ value: p, label: p }))}
                        currentTheme={theme}
                        className="w-full"
                    />
                </div>
                <div>
                    <Select
                        label="Status"
                        value={status}
                        onChange={(value) => setStatus(value as TaskStatus)}
                        options={Object.values(TaskStatus).map(s => ({ value: s, label: s.replace('_', ' ') }))}
                        currentTheme={theme}
                        className="w-full"
                    />
                </div>
            </div>

             <div className="grid grid-cols-1 sm:grid-cols-1 gap-4 bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5">
                 <div>
                     <label className="flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300 mb-2">
                        <Users size={16} className="text-blue-500" /> Collaboration
                    </label>
                    <button
                        onClick={() => setIsShared(!isShared)}
                        className={`w-full px-3 py-2 rounded-lg text-sm border flex items-center justify-between transition-all ${
                            isShared 
                            ? 'bg-blue-500/10 text-blue-600 dark:text-blue-300 border-blue-500/30' 
                            : 'bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                    >
                        <span>{isShared ? 'Shared with Partner' : 'Private'}</span>
                        {isShared && <Check size={14} />}
                    </button>
                 </div>
             </div>

             {/* Recurrence Settings */}
             <div className="bg-slate-50 dark:bg-black/20 p-4 rounded-2xl border border-slate-200 dark:border-white/5">
                 <div className="flex items-center gap-2 text-sm font-medium text-slate-600 dark:text-slate-300 mb-3">
                     <Repeat size={16} className="text-emerald-500" /> Repeated Item
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                      <div>
                          <label className="block text-xs font-semibold text-slate-500 mb-1.5">Frequency</label>
                          <Select
                              value={recurrenceFreq}
                              onChange={(value) => setRecurrenceFreq(value as any)}
                              options={[
                                  { value: 'none', label: 'Does not repeat' },
                                  { value: 'daily', label: 'Daily' },
                                  { value: 'weekly', label: 'Weekly' },
                                  { value: 'monthly', label: 'Monthly' },
                                  { value: 'yearly', label: 'Yearly' }
                              ]}
                              currentTheme={theme}
                          />
                      </div>
                     {recurrenceFreq !== 'none' && (
                         <div className="space-y-3">
                            <div>
                                <label className="block text-xs font-semibold text-slate-500 mb-1.5">Repeat Every</label>
                                <div className="flex items-center gap-2">
                                    <input 
                                        type="number"
                                        min="1"
                                        value={recurrenceInterval}
                                        onChange={e => setRecurrenceInterval(parseInt(e.target.value) || 1)}
                                        className="w-16 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                                    />
                                    <span className="text-sm text-slate-400">
                                        {recurrenceFreq === 'daily' ? 'day(s)' : 
                                         recurrenceFreq === 'weekly' ? 'week(s)' : 
                                         recurrenceFreq === 'monthly' ? 'month(s)' : 'year(s)'}
                                    </span>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-semibold text-slate-500 mb-1.5">End Date (Optional)</label>
                                <input 
                                    type="date"
                                    value={recurrenceEnd}
                                    onChange={e => setRecurrenceEnd(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-slate-800 dark:text-slate-200 text-sm [color-scheme:light] dark:[color-scheme:dark]"
                                />
                            </div>
                         </div>
                     )}
                 </div>
             </div>
             
             {/* Dependencies */}
             <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-2 ml-1 flex items-center gap-2">
                    <LinkIcon size={12} /> Dependencies
                </label>
                <div className="max-h-32 overflow-y-auto bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded-xl p-2 space-y-1">
                     {availableTasks.length === 0 && <p className="text-xs text-slate-500 p-2">No other tasks available to link.</p>}
                     {availableTasks
                        .filter(t => t.id !== task?.id) // Cannot depend on self
                        .map(t => (
                        <div 
                            key={t.id} 
                            onClick={() => toggleDependency(t.id)}
                            className={`flex items-center gap-3 p-2.5 rounded-lg cursor-pointer text-sm transition-colors ${
                                dependencyIds.includes(t.id) ? 'bg-brand-500/20 text-brand-600 dark:text-brand-300' : 'hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-500 dark:text-slate-400'
                            }`}
                        >
                            <div className={`w-4 h-4 rounded border flex items-center justify-center flex-shrink-0 transition-colors ${
                                dependencyIds.includes(t.id) ? 'border-brand-500 bg-brand-500' : 'border-slate-400 dark:border-slate-600'
                            }`}>
                                {dependencyIds.includes(t.id) && <Plus size={10} className="text-white" />}
                            </div>
                            <span className="truncate">{t.title}</span>
                        </div>
                     ))}
                </div>
             </div>

             {/* Subtasks */}
             <div>
                <div className="flex items-center justify-between mb-3">
                    <label className="text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 ml-1">Subtasks</label>
                    <button onClick={handleAddSubtask} className="text-xs font-medium px-2 py-1 rounded hover:bg-black/5 dark:hover:bg-white/5 flex items-center gap-1 text-brand-600 dark:text-brand-400 transition-colors">
                        <Plus size={12} /> Add Item
                    </button>
                </div>
                <div className="space-y-2.5">
                    {subtasks.map(st => (
                        <div key={st.id} className="flex items-center gap-3 group bg-slate-50 dark:bg-black/20 p-2 rounded-lg border border-transparent hover:border-slate-200 dark:hover:border-white/5 transition-all">
                             <input 
                                type="checkbox" 
                                checked={st.isCompleted} 
                                onChange={() => handleToggleSubtask(st.id)}
                                className="rounded-md border-slate-400 dark:border-slate-600 bg-transparent text-brand-500 focus:ring-0 focus:ring-offset-0 w-4 h-4"
                            />
                            <input 
                                type="text"
                                value={st.title}
                                onChange={(e) => handleUpdateSubtask(st.id, e.target.value)}
                                className={`flex-1 bg-transparent border-none focus:ring-0 p-0 text-sm ${st.isCompleted ? 'line-through text-slate-400 dark:text-slate-500' : 'text-slate-800 dark:text-slate-200'}`}
                                placeholder="What needs to be done?"
                            />
                            <button
                                onClick={() => handleDeleteSubtask(st.id)}
                                className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 focus:opacity-100 transition-opacity p-1"
                                aria-label="Delete subtask"
                            >
                                <Trash2 size={14} />
                            </button>
                        </div>
                    ))}
                    {subtasks.length === 0 && (
                        <p className="text-xs text-slate-500 italic ml-1">No subtasks yet.</p>
                    )}
                </div>
             </div>
         </div>

         {/* Footer */}
        <div className="p-6 border-t border-slate-200 dark:border-white/5 bg-white/80 dark:bg-slate-900/80 flex justify-between items-center z-10">
            {task ? (
                <Button variant="danger" size="icon" onClick={() => onDelete && onDelete(task.id)} className="bg-red-500/10 hover:bg-red-500/20 text-red-500 dark:text-red-400">
                    <Trash2 size={18} />
                </Button>
            ) : <div />}
            
            <div className="flex gap-3">
                <Button variant="ghost" onClick={onClose} className="hover:bg-slate-100 dark:hover:bg-white/5 text-slate-600 dark:text-slate-400">Cancel</Button>
                {task && onStartFocus && (
                    <Button 
                        variant="secondary" 
                        onClick={() => { onClose(); onStartFocus(); }}
                        className="bg-brand-500/10 hover:bg-brand-500/20 text-brand-600 dark:text-brand-400 border border-brand-500/20"
                    >
                        <Play size={16} className="mr-2" /> Focus
                    </Button>
                )}
                <Button variant="primary" onClick={handleSave} className="shadow-lg shadow-brand-500/25">Save</Button>
            </div>
        </div>

      </div>
    </div>
  );
};

export default React.memo(TaskEditor);

import React, { useEffect, useState } from 'react';
import { LayoutTemplate, Trash2, X } from 'lucide-react';
import Button from './Button';
import { DayPlanTemplate } from '../types';
import * as DayPlanService from '../services/dayPlanService';

interface TemplatesModalProps {
  isOpen: boolean;
  onClose: () => void;
  onApply: (template: DayPlanTemplate) => void;
}

const TemplatesModal: React.FC<TemplatesModalProps> = ({
  isOpen,
  onClose,
  onApply,
}) => {
  const [templates, setTemplates] = useState<DayPlanTemplate[]>([]);

  useEffect(() => {
    if (isOpen) {
      setTemplates(DayPlanService.getTemplates());
    }
  }, [isOpen]);

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this template?')) {
      DayPlanService.deleteTemplate(id);
      setTemplates(prev => prev.filter(t => t.id !== id));
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl w-full max-w-2xl border border-slate-200 dark:border-white/10 overflow-hidden flex flex-col max-h-[80vh]">
        {/* Header */}
        <div className="p-6 border-b border-slate-200 dark:border-white/10 flex items-center justify-between">
          <div>
            <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 flex items-center gap-2">
              <LayoutTemplate className="text-brand-500" />
              Templates
            </h2>
            <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">
              Select a template to apply to your day plan.
            </p>
          </div>
          <button 
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-white/5 text-slate-500 dark:text-slate-400 transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {templates.length === 0 ? (
            <div className="text-center py-12 flex flex-col items-center">
              <div className="w-16 h-16 bg-slate-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4 text-slate-400">
                <LayoutTemplate size={32} />
              </div>
              <h3 className="text-lg font-medium text-slate-800 dark:text-slate-100">No saved templates</h3>
              <p className="text-slate-500 dark:text-slate-400 max-w-xs mx-auto mt-2">
                Save your favorite day structures as templates to quickly reuse them.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {templates.map(template => (
                <div 
                  key={template.id}
                  onClick={() => onApply(template)}
                  className="group relative p-4 bg-slate-50 dark:bg-black/20 rounded-xl border border-slate-200 dark:border-white/5 hover:border-brand-500/50 hover:shadow-md transition-all cursor-pointer"
                >
                  <div className="flex items-start justify-between mb-2">
                    <h3 className="font-semibold text-slate-800 dark:text-slate-100 flex-1 truncate pr-2">
                      {template.name}
                    </h3>
                    <button
                      onClick={(e) => handleDelete(template.id, e)}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 opacity-0 group-hover:opacity-100 transition-all"
                      title="Delete template"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                  
                  {template.description && (
                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 mb-3 h-8">
                      {template.description}
                    </p>
                  )}
                  
                  <div className="flex items-center gap-3 text-xs text-slate-400 border-t border-slate-200 dark:border-white/5 pt-3 mt-1">
                    <div className="flex items-center gap-1">
                      <span className="font-medium text-slate-600 dark:text-slate-300">{template.tasks.length}</span> tasks
                    </div>
                    <div className="flex items-center gap-1">
                      <span className="font-medium text-slate-600 dark:text-slate-300">{template.links.length}</span> links
                    </div>
                  </div>
                  
                  <div className="absolute inset-0 border-2 border-brand-500 rounded-xl opacity-0 scale-95 group-hover:opacity-100 group-hover:scale-100 pointer-events-none transition-all duration-200" />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TemplatesModal;

import React, { useState } from 'react';
import { Transaction, TRANSACTION_CATEGORIES } from '../types';
import { ArrowUpRight, ArrowDownLeft, Calendar, Search, Edit2, Trash2, Check, X, Repeat, ChevronLeft, ChevronRight, Tag } from 'lucide-react';
import { format, addMonths, subMonths, startOfMonth, endOfMonth, addWeeks, subWeeks, startOfWeek, endOfWeek, isWithinInterval } from 'date-fns';
import { logger } from '../utils/logger';

interface TransactionListProps {
    transactions: Transaction[];
    className?: string;
    onEdit?: (params: { id: string; description: string; amount: number; type: 'income' | 'expense'; category?: string }) => Promise<any>;
    onDelete?: (id: string) => Promise<any>;
}

const TransactionList: React.FC<TransactionListProps> = ({ transactions, className = '', onEdit, onDelete }) => {
    const [searchTerm, setSearchTerm] = React.useState('');
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editDesc, setEditDesc] = useState('');
    const [editAmount, setEditAmount] = useState('');
    const [editType, setEditType] = useState<'income' | 'expense'>('expense');
    const [editCategory, setEditCategory] = useState<string>('Uncategorized');

    const [viewMode, setViewMode] = useState<'all' | 'month' | 'week'>('month');
    const [currentDate, setCurrentDate] = useState(new Date());

    const getDateRange = () => {
        if (viewMode === 'month') {
            return { start: startOfMonth(currentDate), end: endOfMonth(currentDate) };
        }
        if (viewMode === 'week') {
            return { start: startOfWeek(currentDate, { weekStartsOn: 1 }), end: endOfWeek(currentDate, { weekStartsOn: 1 }) };
        }
        return null; // For 'all' view
    };

    const navigate = (dir: -1 | 1) => {
        if (viewMode === 'month') setCurrentDate(d => dir === 1 ? addMonths(d, 1) : subMonths(d, 1));
        if (viewMode === 'week') setCurrentDate(d => dir === 1 ? addWeeks(d, 1) : subWeeks(d, 1));
    };

    const periodLabel = () => {
        if (viewMode === 'month') return format(currentDate, 'MMMM yyyy');
        if (viewMode === 'week') {
            const range = getDateRange();
            if (!range) return '';
            return `${format(range.start, 'd MMM')} - ${format(range.end, 'd MMM')}`;
        }
        return 'All Time';
    };

    const filteredTransactions = transactions.filter(t => {
        const matchesSearch = t.description.toLowerCase().includes(searchTerm.toLowerCase());
        
        if (viewMode === 'all') return matchesSearch;

        const range = getDateRange();
        if (!range) return matchesSearch;

        const matchesDate = isWithinInterval(new Date(t.date), range);
        return matchesSearch && matchesDate;
    });

    const startEdit = (transaction: Transaction) => {
        setEditingId(transaction.id);
        setEditDesc(transaction.description);
        setEditAmount(transaction.amount.toString());
        setEditType(transaction.type);
        setEditCategory(transaction.category || 'Uncategorized');
    };

    const cancelEdit = () => {
        setEditingId(null);
        setEditDesc('');
        setEditAmount('');
        setEditType('expense');
        setEditCategory('Uncategorized');
    };

    const saveEdit = async (id: string) => {
        if (!onEdit) return;
        
        const amount = parseFloat(editAmount);
        if (!editDesc.trim() || isNaN(amount) || amount <= 0) {
            alert('Please enter valid description and amount');
            return;
        }

        try {
            await onEdit({ id, description: editDesc, amount, type: editType, category: editCategory });
            cancelEdit();
        } catch (error) {
            logger.error('Failed to update transaction', error);
            alert('Failed to update transaction');
        }
    };

    const handleDelete = async (id: string) => {
        if (!onDelete) return;
        
        if (confirm('Are you sure you want to delete this transaction?')) {
            try {
                await onDelete(id);
            } catch (error) {
                logger.error('Failed to delete transaction', error);
                alert('Failed to delete transaction');
            }
        }
    };

    if (!transactions.length) {
        return null;
    }

    return (
        <div className={`glass-panel p-6 rounded-3xl space-y-4 ${className}`}>
            <div className="space-y-4 mb-4">
                <div className="flex items-center justify-between">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500 font-mono flex items-center gap-2">
                        <Calendar size={14} />
                        Transactions History
                    </h3>
                    <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-lg">
                        {(['all', 'month', 'week'] as const).map((mode) => (
                            <button
                                key={mode}
                                onClick={() => setViewMode(mode)}
                                className={`px-3 py-1 text-xs rounded-md capitalize transition-colors ${
                                    viewMode === mode
                                        ? 'bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm'
                                        : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                }`}
                            >
                                {mode}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex items-center justify-between gap-4 flex-wrap">
                    {viewMode !== 'all' && (
                        <div className="flex items-center gap-2 bg-slate-100 dark:bg-white/5 rounded-lg p-1">
                            <button 
                                onClick={() => navigate(-1)}
                                className="p-1 hover:bg-white dark:hover:bg-white/10 rounded-md text-slate-500 transition-colors"
                                aria-label="Previous period"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <span className="text-xs font-mono font-bold text-slate-600 dark:text-slate-300 min-w-[120px] text-center">
                                {periodLabel()}
                            </span>
                            <button 
                                onClick={() => navigate(1)}
                                className="p-1 hover:bg-white dark:hover:bg-white/10 rounded-md text-slate-500 transition-colors"
                                aria-label="Next period"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    )}
                    
                    <div className={`relative ${viewMode === 'all' ? 'w-full' : 'flex-1 min-w-[150px]'}`}>
                        <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input 
                            type="text" 
                            placeholder="Search transactions..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="bg-slate-100 dark:bg-black/30 border border-slate-200 dark:border-white/10 rounded-full pl-9 pr-4 py-1.5 text-xs text-slate-700 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-brand-500/50 w-full"
                        />
                    </div>
                </div>
            </div>

            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                {filteredTransactions.length === 0 ? (
                    <div className="text-center py-8 text-slate-400 text-sm">
                        No transactions found
                    </div>
                ) : (
                    filteredTransactions.map((t) => {
                        const isEditing = editingId === t.id;

                        return (
                            <div key={t.id} className={`p-3 rounded-xl border transition-colors group ${
                                isEditing 
                                    ? 'bg-brand-500/5 border-brand-500/30' 
                                    : 'bg-slate-50/50 dark:bg-white/5 border-slate-100 dark:border-white/5 hover:bg-slate-100 dark:hover:bg-white/10'
                            }`}>
                                {isEditing ? (
                                    /* Edit Mode - Mobile Friendly Vertical Layout */
                                    <div className="space-y-3">
                                        <div className="flex items-center gap-3">
                                            <button
                                                onClick={() => setEditType(editType === 'expense' ? 'income' : 'expense')}
                                                className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center ${
                                                    editType === 'income' 
                                                        ? 'bg-emerald-500/10 text-emerald-500' 
                                                        : 'bg-red-500/10 text-red-500'
                                                }`}
                                                title="Toggle type"
                                                aria-label={editType === 'income' ? 'Switch to expense' : 'Switch to income'}
                                            >
                                                {editType === 'income' ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}
                                            </button>
                                            <input
                                                type="text"
                                                value={editDesc}
                                                onChange={(e) => setEditDesc(e.target.value)}
                                                className="flex-1 min-w-0 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                                                placeholder="Description"
                                            />
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <select
                                                value={editCategory}
                                                onChange={(e) => setEditCategory(e.target.value)}
                                                className="flex-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                                            >
                                                {TRANSACTION_CATEGORIES.map((cat) => (
                                                    <option key={cat} value={cat}>{cat}</option>
                                                ))}
                                            </select>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <input
                                                type="number"
                                                value={editAmount}
                                                onChange={(e) => setEditAmount(e.target.value)}
                                                className="flex-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-brand-500/50"
                                                placeholder="Amount"
                                            />
                                            <button
                                                onClick={() => saveEdit(t.id)}
                                                className="p-2.5 rounded-lg bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500/20 transition-colors"
                                                title="Save"
                                                aria-label="Save changes"
                                            >
                                                <Check size={18} />
                                            </button>
                                            <button
                                                onClick={cancelEdit}
                                                className="p-2.5 rounded-lg bg-slate-100 dark:bg-white/5 text-slate-500 hover:bg-slate-200 dark:hover:bg-white/10 transition-colors"
                                                title="Cancel"
                                                aria-label="Cancel editing"
                                            >
                                                <X size={18} />
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    /* Display Mode - Mobile Friendly Layout */
                                    <div className="flex items-start gap-3">
                                        <div className={`w-10 h-10 shrink-0 rounded-full flex items-center justify-center ${
                                            t.type === 'income' 
                                                ? 'bg-emerald-500/10 text-emerald-500' 
                                                : 'bg-red-500/10 text-red-500'
                                        }`}>
                                            {t.type === 'income' ? <ArrowDownLeft size={18} /> : <ArrowUpRight size={18} />}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-start justify-between gap-2">
                                                <div className="flex items-center gap-1.5 min-w-0">
                                                    <p className="font-semibold text-slate-800 dark:text-slate-200 text-sm truncate">
                                                        {t.description.replace(/\s*\(Recurring\)\s*/i, '')}
                                                    </p>
                                                    {t.description.toLowerCase().includes('(recurring)') && (
                                                        <Repeat size={12} className="text-slate-400 shrink-0" title="Recurring Transaction" />
                                                    )}
                                                </div>
                                                {(onEdit || onDelete) && (
                                                    <div className="flex gap-1 shrink-0 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
                                                        {onEdit && (
                                                            <button
                                                                onClick={() => startEdit(t)}
                                                                className="p-1.5 rounded-lg text-slate-400 hover:bg-brand-500/10 hover:text-brand-500 transition-colors"
                                                                title="Edit"
                                                                aria-label="Edit transaction"
                                                            >
                                                                <Edit2 size={14} />
                                                            </button>
                                                        )}
                                                        {onDelete && (
                                                            <button
                                                                onClick={() => handleDelete(t.id)}
                                                                className="p-1.5 rounded-lg text-slate-400 hover:bg-red-500/10 hover:text-red-500 transition-colors"
                                                                title="Delete"
                                                                aria-label="Delete transaction"
                                                            >
                                                                <Trash2 size={14} />
                                                            </button>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                            <div className="flex flex-wrap items-center gap-x-2 gap-y-1 mt-1">
                                                <div className="flex items-center gap-1.5 text-xs text-slate-500">
                                                    <Calendar size={11} />
                                                    <span>{new Date(t.date).toLocaleDateString()}</span>
                                                    <span>ΓÇó</span>
                                                    <span>{new Date(t.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                                </div>
                                                <span className={`font-bold font-mono text-sm ${
                                                    t.type === 'income' ? 'text-emerald-500' : 'text-red-500'
                                                }`}>
                                                    {t.type === 'income' ? '+' : '-'}Γé╣{t.amount.toLocaleString('en-IN')}
                                                </span>
                                                {t.category && t.category !== 'Uncategorized' && (
                                                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-brand-500/10 text-brand-600 dark:text-brand-400 text-[10px] font-semibold">
                                                        <Tag size={9} />
                                                        {t.category}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
};

