/**
 * Get all shares for notes owned by current user
 */
export const getNoteShares = async (noteId?: string): Promise<NoteShare[]> => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Not authenticated');

  let query = supabase
    .from('note_shares')
    .select(`
      *,
      shared_with:profiles!note_shares_shared_with_id_fkey(id, email, full_name)
    `)
    .eq('owner_id', user.id);

  if (noteId) {
    query = query.eq('note_id', noteId);
  }

  const { data: shares, error } = await query;

  if (error) throw error;

  return (shares || []).map((dbShare: DbNoteShare) => {
    const sharedWith = Array.isArray(dbShare.shared_with) 
      ? dbShare.shared_with[0] 
      : dbShare.shared_with;

    return {
      id: dbShare.id,
      noteId: dbShare.note_id,
      ownerId: dbShare.owner_id,
      sharedWithId: dbShare.shared_with_id,
      sharedWithEmail: sharedWith?.email || '',
      sharedWithName: sharedWith?.full_name,
      createdAt: dbShare.created_at,
    };
  });
};

/**
 * Share a note with a partner
 */
export const shareNoteWithPartner = async (
  noteId: string,
  partnerId: string
): Promise<boolean> => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Not authenticated');

  // First, update the note to mark it as shared
  const { error: noteError } = await supabase
    .from('notes')
    .update({ is_shared: true })
    .eq('id', noteId)
    .eq('user_id', user.id);

  if (noteError) throw noteError;

  // Then create the share record
  const { error: shareError } = await supabase
    .from('note_shares')
    .insert({
      note_id: noteId,
      owner_id: user.id,
      shared_with_id: partnerId,
    });

  if (shareError) {
    // If already shared, ignore the error
    if (shareError.code === '23505') { // unique constraint violation
      return true;
    }
    throw shareError;
  }

  return true;
};

/**
 * Unshare a note (remove a specific share)
 */
export const unshareNote = async (shareId: string): Promise<boolean> => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Not authenticated');

  // Get the share to find the note_id
  const { data: share } = await supabase
    .from('note_shares')
    .select('note_id')
    .eq('id', shareId)
    .eq('owner_id', user.id)
    .single();

  // Delete the share
  const { error } = await supabase
    .from('note_shares')
    .delete()
    .eq('id', shareId)
    .eq('owner_id', user.id);

  if (error) throw error;

  // Check if there are any remaining shares for this note
  if (share) {
    const { data: remainingShares } = await supabase
      .from('note_shares')
      .select('id')
      .eq('note_id', share.note_id)
      .eq('owner_id', user.id);

    // If no more shares, update the note to mark as not shared
    if (!remainingShares || remainingShares.length === 0) {
      await supabase
        .from('notes')
        .update({ is_shared: false })
        .eq('id', share.note_id);
    }
  }

  return true;
};

/**
 * Notification Service
 * Handles Web Push Notifications for background/offline notifications
 * 
 * This service uses the Push API to deliver notifications even when:
 * - The browser tab is closed
 * - The PWA is in the background
 * - The device is locked (but powered on)
 */

import { NotificationSettings } from '../types';
import { supabase } from './supabaseClient';
import { logger } from '../utils/logger';

const DEFAULT_SETTINGS: NotificationSettings = {
  enabled: false,
  taskReminders: true,
  eventReminders: true,
  budgetAlerts: true,
  reminderMinutesBefore: 15,
};

const SETTINGS_KEY = 'chronodex_notification_settings';
const PUSH_SUBSCRIPTION_KEY = 'chronodex_push_subscription';

// VAPID public key - this should match your Supabase secrets
// Generate with: npx web-push generate-vapid-keys
const VAPID_PUBLIC_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY || '';

// Feature flag to disable push notification backend calls
// Set to true when the push-notification Edge Function is properly deployed and working
const PUSH_NOTIFICATIONS_BACKEND_ENABLED = true;

/**
 * Check if browser supports notifications
 */
export const isSupported = (): boolean => {
  return 'Notification' in window;
};

/**
 * Check if browser supports Web Push
 */
export const isPushSupported = (): boolean => {
  return 'PushManager' in window && 'serviceWorker' in navigator;
};

/**
 * Get current notification permission status
 */
export const getPermissionStatus = (): NotificationPermission | 'unsupported' => {
  if (!isSupported()) return 'unsupported';
  return Notification.permission;
};

/**
 * Request notification permission from user
 */
export const requestPermission = async (): Promise<boolean> => {
  if (!isSupported()) return false;
  
  try {
    const permission = await Notification.requestPermission();
    return permission === 'granted';
  } catch (error) {
    console.error('Error requesting notification permission:', error);
    return false;
  }
};

/**
 * Get notification settings from localStorage
 */
export const getSettings = (): NotificationSettings => {
  try {
    const stored = localStorage.getItem(SETTINGS_KEY);
    if (stored) {
      return { ...DEFAULT_SETTINGS, ...JSON.parse(stored) };
    }
  } catch (error) {
    console.error('Error reading notification settings:', error);
  }
  return DEFAULT_SETTINGS;
};

/**
 * Save notification settings to localStorage
 */
export const saveSettings = (settings: NotificationSettings): void => {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch (error) {
    console.error('Error saving notification settings:', error);
  }
};

/**
 * Convert VAPID key to Uint8Array for Push API
 */
const urlBase64ToUint8Array = (base64String: string): Uint8Array => {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding)
    .replace(/-/g, '+')
    .replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
};

/**
 * Subscribe to Web Push notifications
 */
export const subscribeToPush = async (): Promise<boolean> => {
  // Skip if backend is disabled
  if (!PUSH_NOTIFICATIONS_BACKEND_ENABLED) {
    console.debug('Push notification backend is disabled');
    return false;
  }

  if (!isPushSupported()) {
    console.warn('Push notifications not supported in this browser');
    return false;
  }

  if (!VAPID_PUBLIC_KEY) {
    console.error('VAPID_PUBLIC_KEY not configured');
    return false;
  }

  try {
    // Wait for service worker to be ready
    const registration = await navigator.serviceWorker.ready;
    
    // Check for existing subscription
    let subscription = await registration.pushManager.getSubscription();
    
    if (!subscription) {
      // Create new subscription
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
      });
    }

    // Get current user
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
      console.error('User not authenticated');
      return false;
    }

    // Check for valid session to avoid 401 errors
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) {
      console.error('No valid session');
      return false;
    }

    // Save subscription to backend
    const { error } = await supabase.functions.invoke('push-notification', {
      body: {
        action: 'subscribe',
        userId: user.id,
        subscription: subscription.toJSON(),
      },
    });

    if (error) throw error;

    // Cache subscription locally
    localStorage.setItem(PUSH_SUBSCRIPTION_KEY, JSON.stringify(subscription.toJSON()));
    
    logger.info('Push notification subscription successful');
    return true;
  } catch (error) {
    console.error('Error subscribing to push notifications:', error);
    return false;
  }
};

/**
 * Unsubscribe from Web Push notifications
 */
export const unsubscribeFromPush = async (): Promise<boolean> => {
  // Skip if backend is disabled
  if (!PUSH_NOTIFICATIONS_BACKEND_ENABLED) return true;
  if (!isPushSupported()) return true;

  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.getSubscription();
    
    if (subscription) {
      await subscription.unsubscribe();
    }

    // Get current user
    const { data: { user } } = await supabase.auth.getUser();
    const { data: { session } } = await supabase.auth.getSession();
    if (user && session) {
      await supabase.functions.invoke('push-notification', {
        body: {
          action: 'unsubscribe',
          userId: user.id,
        },
      });
    }

    localStorage.removeItem(PUSH_SUBSCRIPTION_KEY);
    logger.info('Unsubscribed from push notifications');
    return true;
  } catch (error) {
    console.error('Error unsubscribing from push:', error);
    return false;
  }
};

/**
 * Check if user is subscribed to push
 */
export const isPushSubscribed = async (): Promise<boolean> => {
  if (!isPushSupported()) return false;
  
  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.getSubscription();
    return !!subscription;
  } catch {
    return false;
  }
};

/**
 * Send a notification immediately (via Service Worker for background support)
 */
export const sendNotification = async (
  title: string,
  options?: {
    body?: string;
    icon?: string;
    tag?: string;
    data?: Record<string, unknown>;
    onClick?: () => void;
  }
): Promise<boolean> => {
  if (!isSupported()) return false;
  if (Notification.permission !== 'granted') return false;
  
  const settings = getSettings();
  if (!settings.enabled) return false;

  try {
    // Use Service Worker showNotification for better background support
    if ('serviceWorker' in navigator) {
      const registration = await navigator.serviceWorker.ready;
      await registration.showNotification(title, {
        body: options?.body,
        icon: options?.icon || '/logo-dark.jpg',
        badge: '/logo-dark.jpg',
        tag: options?.tag,
        data: options?.data,
        requireInteraction: false,
        vibrate: [100, 50, 100],
      } as any);
      return true;
    } else {
      // Fallback to regular Notification
      const notification = new Notification(title, {
        body: options?.body,
        icon: options?.icon || '/logo-dark.jpg',
        tag: options?.tag,
        data: options?.data,
      });

      if (options?.onClick) {
        notification.onclick = () => {
          window.focus();
          options.onClick?.();
          notification.close();
        };
      }

      setTimeout(() => notification.close(), 10000);
      return true;
    }
  } catch (error) {
    console.error('Error sending notification:', error);
    return false;
  }
};

/**
 * Schedule a notification for a specific time (via backend)
 * This works even when the app is closed!
 */
export const scheduleNotification = async (
  id: string,
  title: string,
  scheduledTime: Date,
  options?: {
    body?: string;
    taskId?: string;
  }
): Promise<boolean> => {
  // Skip if backend is disabled
  if (!PUSH_NOTIFICATIONS_BACKEND_ENABLED) return false;

  const settings = getSettings();
  if (!settings.enabled) return false;

  const now = new Date();
  const delay = scheduledTime.getTime() - now.getTime();

  // Don't schedule if time has passed
  if (delay <= 0) return false;

  try {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return false;

    // Also check for a valid session to avoid 401 errors
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return false;

    // Silently fail if push notification function is not available
    // This prevents CORS errors when the function isn't deployed or configured
    const { error } = await supabase.functions.invoke('push-notification', {
      body: {
        action: 'schedule',
        userId: user.id,
        taskId: options?.taskId || id,
        notification: {
          title,
          body: options?.body,
          scheduledTime: scheduledTime.toISOString(),
        },
      },
    }).catch((err) => {
      // Suppress 401 errors (user not authenticated) - this is expected
      if (err?.message?.includes('401') || err?.status === 401) {
        return { error: null }; // Silently ignore auth errors
      }
      return { error: { message: 'Push notification service unavailable' } };
    });

    if (error) {
      // Silently log the error instead of throwing
      console.debug('Push notification scheduling skipped:', error.message);
      return false;
    }
    
    logger.debug(`Scheduled notification for ${scheduledTime.toISOString()}`);
    return true;
  } catch (error) {
    // Silently handle errors to prevent console spam
    console.debug('Error scheduling notification:', error);
    return false;
  }
};

/**
 * Cancel a scheduled notification
 */
export const cancelNotification = async (taskId: string): Promise<boolean> => {
  // Skip if backend is disabled
  if (!PUSH_NOTIFICATIONS_BACKEND_ENABLED) return false;

  try {
    // Check for valid session before making API call
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return false;

    const { error } = await supabase.functions.invoke('push-notification', {
      body: {
        action: 'cancel',
        taskId,
      },
    }).catch((err) => {
      // Suppress 401 errors (user not authenticated) - this is expected
      if (err?.message?.includes('401') || err?.status === 401) {
        return { error: null }; // Silently ignore auth errors
      }
      return { error: { message: 'Push notification service unavailable' } };
    });

    if (error) {
      console.debug('Push notification cancellation skipped:', error.message);
      return false;
    }
    return true;
  } catch (error) {
    console.debug('Error cancelling notification:', error);
    return false;
  }
};

