// ============ TEAMS ============

export async function getTeams(): Promise<Team[]> {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return [];

  // Get teams user owns
  const { data: ownedTeams, error: ownedError } = await supabase
    .from('teams')
    .select('id, name, description, owner_id, created_at')
    .eq('owner_id', user.id);

  if (ownedError) {
    logger.error('Error fetching owned teams', ownedError);
  }

  // Get teams user is a member of
  const { data: memberTeams, error: memberError } = await supabase
    .from('team_members')
    .select(`
      team:teams(id, name, description, owner_id, created_at)
    `)
    .eq('user_id', user.id)
    .eq('status', 'accepted');

  if (memberError) {
    logger.error('Error fetching member teams', memberError);
  }

  // Combine and deduplicate
  const allTeams: Team[] = [];
  const seenIds = new Set<string>();

  for (const t of ownedTeams || []) {
    if (!seenIds.has(t.id)) {
      seenIds.add(t.id);
      // Get member count
      const { count } = await supabase
        .from('team_members')
        .select('*', { count: 'exact', head: true })
        .eq('team_id', t.id)
        .eq('status', 'accepted');

      allTeams.push({
        id: t.id,
        name: t.name,
        description: t.description || undefined,
        ownerId: t.owner_id,
        isOwner: true,
        memberCount: (count || 0) + 1, // +1 for owner
        createdAt: t.created_at
      });
    }
  }

  for (const m of memberTeams || []) {
    const t = m.team as any;
    if (t && !seenIds.has(t.id)) {
      seenIds.add(t.id);
      const { count } = await supabase
        .from('team_members')
        .select('*', { count: 'exact', head: true })
        .eq('team_id', t.id)
        .eq('status', 'accepted');

      allTeams.push({
        id: t.id,
        name: t.name,
        description: t.description || undefined,
        ownerId: t.owner_id,
        isOwner: t.owner_id === user.id,
        memberCount: (count || 0) + 1,
        createdAt: t.created_at
      });
    }
  }

  return allTeams;
}

